/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20221115-4","meetingId":"r04-c-settlement","date":"2022年11月15日","dateIso":"2022-11-15","committee":"決算特別委員会","time":"午前１０時００分～午後 ４時４９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を134件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"江野下委員","kind":"質問","question":"私からは、３５３ページ、防災情報配信経費についてお伺いいたします。町会長にお配りしている防災タブレットについて、その当時の防災ニュースによると、２０１３年９月、品川区では、災害時の情報伝達を目的に、防災用のタブレット端末を１０月から配付する。２３区で初めての試みになる。２３区で初というのはいいですよね。全ての町会・自治会、避難所になる区立小・中学校など３１５か所が対象。","respondent":"平原防災課長","answer":"評価といたしましては、そういったところを考えてあります。","voiceIndex":4,"id":"exchange-001","title":"町会・自治会支援"},{"speaker":"江野下委員","kind":"質問","question":"あれから９年、たしか本会議でも新妻委員が、八潮地区でしょうか、タブレットを使用した講習会などをして活用が進んでいるとお聞きしましたが、私の地域では、「タブレットのＬＩＮＥで連絡が取れれば便利なのに」とか、「タブレットは大きくて、持ち歩くのに不便」などの声があり、うまく活用されていないと実感しております。活用には地域的な差があるのかと思いますが、その辺はいかがでしょうか。","respondent":"平原防災課長","answer":"今後、進んでいる地域の取組内容や、あるいは使いこなしが難しいといったところには、かなり基本的なところをもう一度やらせていただきまして、広がりをつくってまいりたいと考えています。","voiceIndex":6,"id":"exchange-002"},{"speaker":"江野下委員","kind":"質問","question":"荏原第一地区では防災タブレットの説明会や講習会を行うと町会長からも伺っておりますが、この１年半、残念ながら、いまだに開催されていないようです。コロナ禍もあるとは思いますが、これまでに、特に今年度、地区によっては講習会を行っているのか、何地区で何回ぐらい行ったのか、教えていただければと思います。現在のタブレットは１台お幾らなのか、お知らせください。","respondent":"平原防災課長","answer":"説明会ですけれども、今年度は大井第一地区で１回、夏ぐらいに行ったものです。","voiceIndex":8,"id":"exchange-003","title":"町会・自治会支援"},{"speaker":"江野下委員","kind":"質問","question":"リースでしたか。勉強になりました。今後、荏原第一地区では、いつまでに講習会などを開催するかなどもお聞かせいただけますでしょうか。","respondent":"平原防災課長","answer":"講習会につきましては、それぞれの町会長会議などの場を活用することを考えてございまして、今後、荏原第一地区との間で調整させていただきまして、開催できるように進めていきたいと考えています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"江野下委員","kind":"質問","question":"品川区では、デジタルデバイド解消に向けた取組みは考えていますでしょうか。通信サービス企業と連携した事業はお考えでしょうか。防災タブレット端末の利用を、デジタルデバイドを踏まえた形で進めたり、防災情報の確実な伝達をするためにも、タブレットの代わりに、持ち歩きにも便利なスマートフォンで対応していくことはお考えでしょうか。","respondent":"平原防災課長","answer":"様々な声があるということはこちらでもお聞きしておりますので、今後、防災タブレットをどのようにしていくかという中で、検討を進めてまいりたいと考えています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"江野下委員","kind":"質問・要望","question":"そうですね。私もスマホアプリは、品川区のものをかなりいろいろ入れておりますけれども、情報が結構多く入ってきていると思いますので、今後もそちらも拡充していただきたいと思います。町会・自治会のデジタル化の拡充を、防災タブレットを含めて今後も進めていっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"質問","question":"私からは、３２５ページ、水辺利活用事業、３２９ページ、やさしいまちづくり整備費、３３１ページ、立会川・勝島地区まちづくり検討経費、３３７ページ、公園・児童遊園費、３５５ページ、避難所管理費、順不同で伺っていきます。舟運実験等について伺います。先月１７日から１１月４日まで、らくらく舟旅通勤第２弾が行われました。","respondent":"栗原河川下水道課長","answer":"アンケートの結果につきましては、今後、分析いたしますけれども、比較的、水辺に対して、運行していただきたいというような声をいただいているということは認識しています。","voiceIndex":16,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"後日、インターネットによるアンケートを取りましたが、注目すべきは乗船者のお住まいの地域です。今回、水辺利活用の推進を要望するに当たり、令和２年５月に策定されました品川区水辺利活用ビジョンの内容を改めて確認してみました。日常の利用、通勤、観光と、様々な側面から舟運を推進してほしいと思っています。船着場の待合場所、トイレの整備について、区の見解を伺います。見解を伺います。","respondent":"栗原河川下水道課長","answer":"今回の社会実験や水辺のイベントの告知などでは、これまでもホームページやＳＮＳなどを活用してまいりましたが、ご提案いただきました、舟運など水辺を紹介する区のホームページの充実につきましては、区民に分かりやすく、また興味を引くようなホームページにつきまして。","voiceIndex":18,"id":"exchange-008"},{"speaker":"新妻委員","kind":"提案","question":"どうぞ具体的に推進をお願いしたいと思います。私も議会質問で重ねて要望してまいりましたので、説明会で初めて人道橋のイメージパースが示され、いよいよ花海道が回遊できるようになると期待しています。民間事業者である佐川急便には、今後どのような協力を求めていくのか、伺います。橋の途中に少し膨らみをつけて、そこにベンチを置き、休憩できる場所をつくってはと提案いたしますが、見解を伺います。","respondent":"森道路課長","answer":"確かに休憩する場所があれば、そこで一休みできますし、また運河を橋の上から眺めるということも可能かと考えております。そこにつきましては、橋の構造上、どの程度のものが可能になるのかということも含めて検討してまいりたいと考えております。","voiceIndex":20,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"区内鉄道駅のホームドア設置について伺います。先日の建設委員会で京急線青物横丁駅にホームドアが設置される予定との質疑があったと伺いました。昨年度は品川シーサイド駅可動式ホーム柵整備助成として１億６,０００万円が決算額となっております。品川区と事業者が一緒に設置を進めてまいりましたが、青物横丁駅をはじめ、今後設置する駅において区の予算をつけて行っていくのか、伺います。","respondent":"鈴木都市計画課長","answer":"北品川駅は２０２９年度頃、連立事業とあわせての整備予定で、残り４駅、新馬場駅、鮫洲駅、立会川駅、大森海岸駅は、２０３０年度中頃までには、固定式か可動式などの何らかの安全対策を実施する予定と聞いております。","voiceIndex":22,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"品川区が後押しをしていただき、早い設置を要望いたします。次に、ペットの避難について伺います。私は２０１９年、第３回定例会の一般質問で、避難所運営マニュアルにペット避難について記載しているのが４５か所なのはなぜか。５２か所全てでペット同行避難を受け入れられるよう要望いたしました。区のホームページに、ペットが避難できる避難所を公開してほしいと要望いたしますが、見解を伺います。","respondent":"吉岡防災体制整備担当課長","answer":"今後の対応ですけれども、全区民避難所でペットを受け入れていくというところは、避難所も前向きに捉えているところもありますので、引き続き、区としても働きかけを行ってまいりたいと思います。","voiceIndex":24,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"早急にこれは進めていただきたいと思いますが、まだ全ての避難所が整備されておりません。ペット情報のホームページを見ると、全２３区のペット避難状況が出ていまして、ペット避難を全ての避難所で受け入れているという区も多くあります。このペットの災害対策ガイドラインの策定を含めて、また区のお考えをお伺いいたします。","respondent":"吉岡防災体制整備担当課長","answer":"引き続き、ペットの防災に関することですけれども、違うところでペットを受け入れるということよりは、まず、全区民避難所でペットを受け入れられるような体制をつくっていくといったところに力を入れてまいりたいと思います。","voiceIndex":26,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"本当に力を入れて、一日も早く整備されますようにお願いいたします。時間がなくなりました。東大井公園の整備についてですけれども、保育園の移動が終わりました。この後の整備状況をお伺いいたします。","respondent":"高梨公園課長","answer":"保育園と児童センターの移転に合わせて整備を進めていければと考えているところです。","voiceIndex":28,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"３３５ページの市街地整備事業費より、駅前に次々と建つタワーマンションやオフィスビル、そこに住んでいる住民を追い出す再開発事業の中止を求めて質問したいと思います。これを追い出しと呼ばずに何と呼ぶのか。従わなければ奪い取る。ここで述べた権利の主張とはどのような主張なのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"この再開発を含めて、まちづくりを進めていくに当たりましては、その地域にお住まいの権利者の方々が皆さんで、そのまちの課題、防災性の課題であったり、また、にぎわいの創出であったり、皆さんが抱える、どういうまちにしていこうかということを話し合いながら。","voiceIndex":31,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"賛成・反対ではなく皆さんが話し合ってとおっしゃいますが、反対を主張していても土地を奪われるのが再開発だと、私は先ほど指摘いたしました。改めて質問いたしますが、憲法によって個人の私有財産は認められています。この主張のどこが、再開発が進まない権利の主張と考えているのか、端的にご説明ください。","respondent":"多並都市開発課長","answer":"その新たなまちをつくっていく中で、皆さんで一緒にやっていこうということを皆さんで共有して進めていくものでありますので、そこをしっかり、区としてもそういう趣旨を伝えていただけるように、再開発準備組合でお話し合いしているところについて。","voiceIndex":33,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"正直、何を言っているのかよく分かりません。再開発を進めてほしくないと思っている人が、再開発を進める人たちに土地と財産を奪われることを、都市再開発法の第２０条と第８７条で議論したわけです。部長は、どんな権利の主張があると再開発が進まないと、邪魔な主張だと考えているのか、改めて具体的にご説明いただきたいと思います。","respondent":"多並都市開発課長","answer":"その法律の中で、区としましては、１つの、この事業を進めていく中で、３分の２という手続きもありますけれども、一人でも多くの方がその中でご納得いただいて、事業が進むようにということで、事業を進める、今、調整させていただいている事務局なりにお伝えし。","voiceIndex":35,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"法律にのっとって、３分の２を持っていると、３分の１の土地と建物を奪えると。これをまさに住民の追い出しだと、私は先ほどから繰り返し指摘しているところです。再開発事業者は巧妙な手口で様々、地権者に迫ってきます。これを知っていて、一円も負担せずに新しいマンションが手に入るとの開発業者の説明は、実際の住民が負担するお金を説明しない、うその説明だと思いますが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"そういう事業のスキームでありますので、一円もかからないというのは、限定したところで、今の事実については確認しなくてはいけないところでありますけれども、基本的な考え方はそういう話ですので、それは、権利者の方々に、もしそういう誤解が生じるようなことがあれば。","voiceIndex":37,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"一円も負担せず新しいマンションが手に入ると地権者を惑わすこの説明は、大井町も大崎も武蔵小山も五反田も、どこでも行われています。ぜひ区は把握をしていただきたいと思います。こうした再開発事業は、地方自治体が行うべき公共事業ではないと思います。再開発の中止を強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"私からは、３５１ページの防災訓練経費について、３５３ページの災害廃棄物処理計画作成経費について、時間がありましたら、３５５ページの街頭消火器の格納箱等について伺いたいと思います。初めに、３５１ページの防災訓練経費で、先ほどもご質問がありましたけれども、ペットとの同行避難について伺いたいと思います。そこで伺います。あれば、その実績についてお知らせください。","respondent":"五十嵐災害対策担当課長","answer":"ペット同行避難訓練についてのお伺いだと思います。現在、避難所訓練のところで、ペット同行避難の訓練をやったという報告は来ておりません。ただ、しながわ防災学校の中で、今度、１１月２６日、土曜日ですけれども、浜川中学校でペット防災の講義は実施していく予定です。","voiceIndex":41,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひやっていただきたいと考えています。現在、ペット避難所のガイドラインを作成中と、先ほどの質問でありましたが、今まで一緒に暮らしてきた家族の一員であるペットと離れ離れになったときは、飼い主は精神的にも不安定になってしまうおそれがあります。私は、全ての避難所でペットと同行避難できる体制づくりを進めていただきたいと思いますが、区の見解について改めてお伺いします。","respondent":"吉岡防災体制整備担当課長","answer":"ペットの同行避難ができる区民避難所についてということで、こちらにつきましては、５２か所の避難所でペットの受入れができるように、引き続き、連携・協議を進めていきたいと考えています。","voiceIndex":43,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問・要望","question":"そこで、ペットとの同行避難訓練について少しお伺いしたいと思います。そうしたことも踏まえて、今年行われます区内一斉防災訓練で行うことは難しいかもしれませんが、次回の総合防災訓練で一度行っていただきたいと考えています。行う際は、ぜひ消防署員の方、消防団員の方、獣医師の方、医師会等、各種団体と連携していただきたいと思いますが、ご検討をお願いしたいと思いますが、いかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"来年度の地区防災訓練ですけれども、まだ何をやるかは決まってはおりませんけれども、各自治会とお話しして、テーマを決めて実施していきたいと考えております。そこでは引き続き、感染症対策を継続しますし、消防、警察の方々とも合同で訓練をやっていきたいと考えております。","voiceIndex":45,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"ぜひ、そうしたスケジュールで行っていただければと考えています。そして、ペットには様々な種類があります。哺乳類、鳥類、爬虫類等、様々な動物がおり、餌に関しても様々です。そこで、事前に、できたらでいいのですが、ペットショップやスーパーなど、ペットのご飯を販売しているところと提携することも視野に入れて、品川区独自の体制をつくっていただければと思いますが、いかがでしょうか。","respondent":"吉岡防災体制整備担当課長","answer":"様々、民間との協定というところは、区においても進めているところです。そのほか、食料や飲料水といったものも含めまして、どういった協定が結べるのかというところは研究していきたいと考えています。","voiceIndex":47,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ進めてください。ペットは家族の一員です。よろしくお願いします。関連して、マンション住民との防災訓練について伺います。近年、品川区は、多くのマンションが建ち並ぶまちに変化しつつあります。ぜひ、ペットも含め、一人でも多くの命を救うためには、まずマンションの防災訓練を徹底して行っていただきたいのですが、区はどのような考えを持ち、今後進めていかれるのでしょうか。お知らせください。","respondent":"平原防災課長","answer":"今後も引き続き、こういった活動を進めまして、マンションでの訓練が進むように取り組んでまいりたいと考えています。","voiceIndex":49,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ進めてください。次に、３５３ページの災害廃棄物処理計画作成経費について伺います。そこで質問いたします。生活ごみ、し尿、倒壊家屋からの瓦礫、家具など、災害廃棄物の仮置場について伺います。ぜひ、区民への周知を徹底していただきたいと思います。その中で、この計画の内容を少し、第一次、第二次というふうな話は聞いておりますが、仮置場についてどのようになっているのでしょうか。","respondent":"平原防災課長","answer":"仮置場につきましては、最終的に災害廃棄物が処理されるまでの間に何段階かあるのですけれども、区の中での取組みといたしましては、地区仮置場、一時仮置場という形で、身近な公園、あるいは割と大きな公園という形で、だんだん集約していくようなところで、現在。","voiceIndex":51,"id":"exchange-024"},{"speaker":"松永委員","kind":"質問","question":"最終的にごみは１つの場所にまとめられると思いますが、例えば東京都と連携して、海側近くにあります広い公園、いわゆる大井ふ頭中央海浜公園を活用してはどうかと思うのですが、いかがでしょうか。","respondent":"平原防災課長","answer":"最終的な瓦礫等の処分ですけれども、こちらにつきましては、今、委員がご指摘のとおり、東京都が最終的に処分の方向に持っていくかと思いますので、しっかりと区と都で連携しながら進めてまいりたいと考えています。","voiceIndex":53,"id":"exchange-025"},{"speaker":"松永委員","kind":"質問","question":"災害対策は待ったなしですので、ぜひよろしくお願いします。時間がありますので、次に、３５５ページの街頭消火器格納箱について伺います。品川区中に街頭消火器があります。そこで、どういった形で区民の皆さんに、「ここに消火器があるよ」というような形になっているのか、お知らせください。","respondent":"吉岡防災体制整備担当課長","answer":"街頭消火器についてのお尋ねです。街頭消火器は、令和４年９月末時点で６,４９３本、区が把握しているところで設置させていただいているところです。","voiceIndex":55,"id":"exchange-026"},{"speaker":"松永委員","kind":"質問・要望","question":"例えば、「ここに消火器がありますよ」というような、みんなが使えるアプリを活用したりといったところも含めてご検討いただきたいと思います。そこで、先ほどもお話しさせていただきましたが、防災訓練等でも、こうした消火器は、訓練は行うのだけれども、消火器がどういったものなのか、仕組み、処分方法、点検方法の確認も一緒に行うことが必要だと考えますが、最後に伺います。","respondent":"吉岡防災体制整備担当課長","answer":"街頭消火器の廃棄の方法等についてのご質問です。街頭消火器につきましては、あっ旋事業という形で行っておりまして、購入に関して、あるいは廃棄に関してお知らせをさせていただいているところです。今後も様々な機会を捉えて、分かりやすい周知に努めていきたいと思います。","voiceIndex":57,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"３１７ページ、交通安全啓発費で、まず３点伺います。西大井の駅付近にシェアサイクルをという要望をしているのですけれども、これはいかがですか。西大井駅東口には改札口がありますが、何回も要望していますが、これはぜひ西口にも改札口をつくっていただきたいと思います。大井町線。それと、３３７ページの、連続立体交差化事業をお伺いしたいのですけれども、私は高崎線を止めてほしいと要望しています。","respondent":"工藤交通安全担当課長、溝口土木管理課長、森道路課長、鈴木都市計画課長、多並都市開発課長、大石木密整備推進課長、高梨公園課長、中道まちづくり立体化担当課長、長尾建築課長、竹田住宅課長、平原防災課長","answer":"私からは、４点のご質問に対してお答えしたいと思います。令和２年度に本格実施してから、これまで区内全域にポートの設置を進めてきたところです。多少、渋滞等も減ってきたかとは考えておりますけれども、今年度、今、歩道の拡幅も含めて、横断歩道の配置も整備していますので。ＪＲからは、設置は困難との回答ですが、区としましては、駅を利用する皆さんのさらなる利便性の向上に向け、引き続き。","voiceIndex":60,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問・要望","question":"一時停止するだけなのだから、それを考えていただきたい。１００％にならないと駄目なのですから。それがまだ、１０人のうち３人というか、１０台のうち３台しか止まらないということでしょう。実績は分かりましたけど、今後やるのですか。あの施策はもうやめるのですか。西大井の件を答えてくれた皆さん、実は第１回定例会のときに、私は同じような質問をしたのです。質問したものだけ答弁ください。","respondent":"長尾建築課長","answer":"基本的には、建て替えであったり耐震改修というところを、区としては支援していきたいと考えておりますが、やはりどうしても費用面など、負担が大きいというお声もありますので、そこに応えていけるように、品川シェルターについては引き続きやっていきたいと考えております。","voiceIndex":73,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"不燃化特区。実績が上がってきたというのは分かるのですが、実質的に、フルでやると一、二年かかってしまいますよね。ということは、もう少しで施策が終わってしまうと思うのですが、これは目標値に達するまで、もっと延期していただきたいので、もう今の時期から東京都に要望していただきたいと思うのですけれども、いかがでしょうか。","respondent":"大石木密整備推進課長","answer":"不燃化特区の再延伸についてのご質問だと思います。再度の延伸につきましては、令和７年度までの達成状況と今後の都の動向を見据えて検討してまいりたいと考えております。","voiceIndex":75,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"３３４ページ、都市開発費について伺います。最初に、３２８ページ、特定整備路線について伺います。２０１９年３月の予算特別委員会で、生活者ネットワークは、道路予定地がフェンスに囲まれていることについて、地域からは圧迫感があると声が上がっていることと、用地活用を求める声があり、東京都に求めてほしいという要望をいたしました。用地はどのようなことに使えるのか。","respondent":"大石木密整備推進課長","answer":"道路建設予定地ですので、その利用については一定程度の制約があると考えられますが、区としては引き続き、地域の声を踏まえた上で東京都に働きかけてまいりたいと考えています。","voiceIndex":78,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり、ルールがあるのであれば、きちんとルールを公表して、不公平がないような形にしていただきたいと思います。それについては、ぜひ後で見解を伺いたいと思います。当該地区への現状の報告は必要なのではないでしょうか。もしくは、区のホームページで公開して、ここに公開されていますということを情報提供すべきではないのでしょうか。その辺について見解を伺います。","respondent":"鈴木都市計画課長","answer":"特定整備路線の用地取得率の過去３年間の状況ですが、放射２号線につきましては、平成３１年から令和４年度までで、プラス１６％の用地取得率の向上、現在が４４％の状況です。補助２８号線につきましては、３年間で４５％の取得率の上昇、現在７３％の用地取得率の状況です。","voiceIndex":80,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"東京都は２０１６年３月に、第三次事業化計画における優先整備路線の着手状況を公表しております。そこでの区分の着手率は約半分でした。３年です。整備完成が可能だと区はお考えでしょうか。生活者ネットワークは、３路線全てで用地取得にこれほど時間がかかっているのであれば、もう現実的に不可能な事業として、区としてこの事業の中止を都に求めてもいいのではないかと考えますが、見解を伺います。","respondent":"鈴木都市計画課長","answer":"区としましては、沿道の不燃化・耐震化も含め、延焼遮断帯の形成というのはセットで進めていくというところで、今、進めているところですので、中止を求めるという考えはございませんし、ソフト対策とともに密集市街地の防災性の向上に向け、東京都と連携し。","voiceIndex":82,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"３３７ページの公園・児童遊園費の中から、区有施設のトイレ機能を伺います。質問です。今後、トイレの改修や新しい施設を造るときには、障害者や乳幼児を連れた方などの当事者に参加していただき、トイレ機能の意見を聞いて設置に反映させてほしいと考えますが、民生費のときに続いての質問になりますが、区の見解を伺います。","respondent":"高梨公園課長","answer":"今後、様々な場面での、公園改修等における当事者点検の実施等につきましては、ほかの施設の状況等も勘案して検討してまいりたいと考えているところです。","voiceIndex":84,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"犯罪が起きない公園のつくり方について伺います。これまでも何度も求めていますが、公園計画をつくっていただき、犯罪が起きない公園づくりをきちんと計画に位置づけていただきたいと思いますが、見解を伺います。小さい子どもが安全に遊ぶことができて、高学年の子どもも過ごせる、誰もが安心して過ごせる公園をつくっていくということを明確に計画に示していただきたいのですが、見解を伺います。","respondent":"高梨公園課長","answer":"公園に求められる性能等につきましては、今後、また計画を踏まえて検討を進めていきたいと考えています。","voiceIndex":86,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"私たちが求めているのは、今、課長は理解してくださったと思うのですけれども、どういう公園を、防犯の視点からも、それから利用される方にとっても、いい公園をつくり続けられるか、存在し続けられるかというような、途中の手入れとか、そういうものも含めた計画で、常に品川区の公園は犯罪が起きにくい、誰もが利用できる安全な公園ということを求めておりますので、引き続き。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":88,"id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"３１６ページの土木管理費で、交通安全啓発、駅周辺等放置自転車対策事業について、３３６ページの公園管理費について、質問します。自転車事故の予防啓発について、子どもが絡む自転車事故の発生件数を伺いたいのですが、もし抽出が難しいようでしたら、自転車事故全体の件数と推移を、令和２年度と３年度でお願いいたします。","respondent":"工藤交通安全担当課長","answer":"区内の事故の推移についてご説明いたします。令和３年度ですけれども、自転車事故が４２２件、前年比でプラス９２件となっております。子どもの事故ということでの抽出は把握しておりませんので、申し訳ございません。","voiceIndex":90,"id":"exchange-037"},{"speaker":"せらく委員","kind":"意見","question":"事故件数が前年度よりも増えているということです。しっかりマナーを守って運転すれば、事故件数はもちろん減っていくことになりますが、子どもの１人乗りやチャイルドシートを使用した二、三人乗りなどの自転車マナー啓発について、区でどのような取組みを行っているか、お聞かせください。","respondent":"工藤交通安全担当課長","answer":"チャイルドシートの自転車ですけれども、こちらも、大人の交通安全教室等を計画していますので、警察と協力の上、実施して、啓発を行っているところです。","voiceIndex":92,"id":"exchange-038"},{"speaker":"せらく委員","kind":"質問・要望","question":"前後にチャイルドシートをつけてお子様を乗せていて、少し目を離した瞬間に、前方シートに乗っているお子様が落下したり、あとお子様の要望に応えているのだと思うのですが、前方シートに、上の大きなお子様を乗せて、自転車が転倒したという現場を見たという話は聞いたことがあります。けがもしますし、周囲を巻き込んでしまうこともあるかもしれません。今後の計画を伺います。","respondent":"工藤交通安全担当課長","answer":"引き続き、広報・啓発、撤去活動等をやってまいりたいと思います。駐輪場の整備計画ですけれども、今年度は立会川駅の駐輪場の、住宅と駐輪場の間を阻む壁が古くなっておりますので、改修工事を実施する予定です。","voiceIndex":94,"id":"exchange-039"},{"speaker":"せらく委員","kind":"提案","question":"整備の際のご提案ですけれども、コインパーキングの空車のように「空き〇〇台」や、渋滞情報の表示板のように、周辺の駐輪場の空き状況の確認がすぐにできると、利用しやすくなるのではないかと思います。大阪では、放置自転車が多いスポットに、子どもたちが描いた絵を設置すると、９０％ほど放置自転車が減ったそうなので、この対策について区の見解を伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"そちらもあわせて、今後、計画に向けて検討してまいりたいと考えています。２点目の、違法駐輪に対する子どもの絵ですけれども、実施している自治体に確認しましたところ、初めはきれいに絵が描かれていて、そこには駐輪しない。ただ、その横にどうしてもとめてしまう。","voiceIndex":96,"id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"少しの工夫で、今ある駐輪場がもっと利用しやすくなり、路上にとめてしまう方も減っていく好循環が生まれるといいと思います。続いて、公園管理費について質問いたします。区のホームページによると、キャッチボールができる公園一覧が載っています。キャッチボールとは、野球のボールとグローブを使用した球技という理解をしていますが、これに限定されている理由を伺います。","respondent":"高梨公園課長","answer":"品川区では、ボールを使って遊んでいただけるスペースのことを、キャッチボール場ということで名前をつけてございまして、今、委員がご紹介のとおり、ホームページにも載せているところですが、中ではキャッチボールのみしかできないといったものではございませんで。","voiceIndex":98,"id":"exchange-041"},{"speaker":"せらく委員","kind":"質問","question":"息子のサッカーのお友達やママ友達から、フェンスで区切ってある公園を見て、「サッカーボールは駄目なんだね」という声を聞いておりましたので、質問させていただきました。勘違いしている方も多いかもしれませんので、ボール遊び用のフェンスが設置してある公園などと、ホームページの記載の変更をしたほうがいいかと思いますが、いかがでしょうか。","respondent":"高梨公園課長","answer":"周知の方法については検討させていただきたいと思います。現地においても、どうしても迷惑行為に対する禁止看板が多くなっている現状ですので、そちらについても、皆さんの誤解がないように理解をしていただける周知に努めたいと考えているところです。","voiceIndex":100,"id":"exchange-042"},{"speaker":"せらく委員","kind":"質問・要望","question":"決算特別委員会１日目でも発言させていただきましたが、ボール遊びができる公園を求める声が多くて、多目的広場や球技場の一般開放を皆様利用しておりますが、駄目もとで伺いますが、サッカーができる公園や施設の新設など、計画がありましたら教えてください。","respondent":"高梨公園課長","answer":"現在、しながわ区民公園で再整備を段階的に進めておりますが、その中の北側ゾーンにおきましては、現在、少年野球場があります。こちらも更新いたしますが、新たに少年サッカー場を新設するべく、これから工事を行う予定です。","voiceIndex":102,"id":"exchange-043"},{"speaker":"せお委員","kind":"質問","question":"ただ、現状は、伺ったら、まだこのガイドラインを用いてのルールづくりはゼロ件だそうですけれども、本来、公園は自由利用の原則があるので、基本の禁止行為を守れば自由でいいという思いを込めて、条件付きで遊べることを、禁止看板ではなく看板で周知している。品川区は都心ですから、敷地を有効に活用できれば、皆さんのこういったところの感覚は変わると思います。","respondent":"高梨公園課長","answer":"３点目、学校において公園のルールを学ぶという教育委員会との連携についてですが、ご提案として検討させていただきたいと思います。","voiceIndex":105,"id":"exchange-044"},{"speaker":"せお委員","kind":"質問・要望","question":"２点目、公園の改修に移ります。皆さんのお声を聞くためのルールも決めていただきたいと考えます。対象は誰なのか。町会・自治会は当たり前ですけど、近隣に幼稚園、保育園があれば、その保護者にも聞いていただきたいです。保育園は、お散歩に行くので、職員にもお話を伺っていただきたいです。このような改修のルールについて、現状と今後の方向性、２点お聞かせください。","respondent":"高梨公園課長","answer":"今後、様々、意見を聞いてほしいというご要望があろうと思いますので、広く皆さんのお声を聞いて、可能なところから取組みをさせていただければと考えています。","voiceIndex":107,"id":"exchange-045","title":"町会・自治会支援"},{"speaker":"せお委員","kind":"意見","question":"ガイドラインとかワークショップとか、うるさくなってすみません。いずれも、何か課題が現れたときにどうするかを丁寧に考えたいと思っていて、区民の皆さんの多様性の相互理解だったり、あとは区民のご意見と、ある程度、行政側の事情といったところの相互理解といったところを大切にして、みんなの公園をつくっていくために、ぜひご検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":109,"id":"exchange-046"},{"speaker":"小芝委員","kind":"質問","question":"私からは、３１９ページ、駅周辺等放置自転車対策事業と、３４１ページ、公衆便所について、もう一つは３５１ページ、防災訓練助成金に関連しまして、国民保護計画について伺います。放置自転車対策です。西大井駅と大井町駅周辺の駐輪対策についてお伺いします。西大井駅周辺の駐輪についての区の認識について、また、どのような対策・対応がされているのか、教えていただければと思います。","respondent":"工藤交通安全担当課長","answer":"そういった利用状況にあります。まだ西大井駐輪場も空きスペース等が若干ありますので、そういった空きスペースに誘導するというような形で、放置自転車をなくすために活動を続けてまいりたいと考えています。","voiceIndex":112,"id":"exchange-047"},{"speaker":"小芝委員","kind":"質問・要望","question":"空きスペースに誘導させるというのも１つの手だと思いますし、また、やはり、違法といいますか、駐輪されています自転車の利用者の方からしますと、もしかしたら純粋に、駐輪場の建屋をそもそも認識されていない方もいらっしゃるかもしれませんので、そういった方々に向けた注意といいますか、掲示、案内を、ぜひ徹底していただきたいと思います。続きまして、大井町駅、阪急前の駐輪について伺います。","respondent":"工藤交通安全担当課長","answer":"こちらの歩道上の駐輪については、当係としても把握しています。大井町駅周辺については、人通りが、自転車も含めて多いということで、自転車の撤去、ならびに放置しないような指導・啓発活動を実施しています。周辺に阪急の駐輪場が３か所あります。","voiceIndex":114,"id":"exchange-048"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、３４１ページの公衆トイレについて、お伺いいたします。大井町駅西口にあります公衆トイレは２０２０年に生まれ変わりました。最大１２ｍの高さがあり、入り口ドアの下から空気を取り込み、建物の上端へ空気を排出するという、自然換気を取り入れているなど、公衆便所特有の臭いといったものを極力取り除く仕組みとなっていると聞いております。","respondent":"高梨公園課長","answer":"区内３５か所に公衆トイレがありますが、立地の状況に合わせまして、最低でも１日１回の清掃をやってあります。今、委員からご紹介がありました大井町駅前公衆便所のように、駅前等、利用者の多い公衆便所につきましては、清掃回数１日３回ということで清掃をしています。","voiceIndex":116,"id":"exchange-049"},{"speaker":"小芝委員","kind":"質問","question":"コロナ前は月間で２００万人以上の外国人が来日されてきたわけですが、先ほど課長の答弁で、清掃の回数を増やしているという答弁をいただきました。防災訓練助成金に関連しまして、国民保護計画についてお伺いいたします。地域の方からも１０月以降、よくそういった心配の声をお聞きします。そこで、単刀直入にお聞きします。屋内にいる場合と屋外にいる場合に分けて教えていただきますよう、お願いします。","respondent":"五十嵐災害対策担当課長","answer":"屋内にいる場合は、破片による負傷を防ぐため、窓から離れるか、窓のない部屋に移動する。そして、建物がない場合は、物陰に身を隠すか、地面に伏せて頭部を守る。そういったことが、内閣官房の国民保護ポータルサイトで示されてあります。","voiceIndex":118,"id":"exchange-050"},{"speaker":"小芝委員","kind":"質問","question":"しかし、このパターンの内容については、武力攻撃側に避難場所や詳細な措置が知られてしまうために公開しないとの答弁でございました。国防の観点からも、要領の詳細を公開すべきではないと私も思いますが、着弾に備えた、区民が命を守るための行動パターンについては公開し、そして周知することで、品川区の住民の皆様が危機意識を持つことにつながると考えますが、ご検討はいかがでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"着弾については、弾頭が生物剤なのか核なのかといったことは分かりませんので、着弾時は、先ほど委員がおっしゃったとおり、屋外に避難する場合は口を覆って、なるべく外気を吸わないようにしてというようなことは、国民保護のポータルサイトでも周知されているというところで。","voiceIndex":120,"id":"exchange-051"},{"speaker":"小芝委員","kind":"質問・要望","question":"そういった訓練が行われた記憶が全くないわけですが、これまでもし区が行ってきました、区民参加型の、国民保護を対象とする事案の訓練があったかないかも含めて、実績について教えていただきたいのと、区内の、これは先般の定例会の答弁でもあったかもしれませんが、児童・生徒に対する訓練の実績について教えていただきたいと思います。","respondent":"五十嵐災害対策担当課長","answer":"２つのご質問がございました。訓練実績についてと、生徒・児童に対する啓発です。訓練実績ですけれども、住民と連携した訓練というのは実際に行ってはおりません。ただ、平成２７年に東京都と合同で、職員による合同訓練、国民保護訓練は実施しています。図上訓練になります。","voiceIndex":122,"id":"exchange-052","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"意見","question":"区民の中には、先ほど話しましたとおり、危機意識を持つ区民の方が必ずいます。もちろん、いたずらに危機感をあおるつもりはありません。しかし、今そこにある危機に立ち向かうべく、区民が自らの命を守れるよう、１分１秒を争う緊急の避難訓練も必要と考えますが、ご見解をいただければと思います。","respondent":"五十嵐災害対策担当課長","answer":"今後の訓練につきましては検討させていただいて、国民保護訓練を進めていく方向で考えていきたいと思います。","voiceIndex":124,"id":"exchange-053"},{"speaker":"小芝委員","kind":"質問・要望","question":"検討という回答をいただきましたが、訓練は本当に様々であると思います。例えば防災体験館の中でＶＲを使った疑似体験など、区民が実際に動いて避難行動を取れるような訓練の実施を検討すべきとも思います。そういったこともぜひ活用していただきまして、有事といいますか、危機に備えていく準備をこれからも引き続き行っていただきたいと思いまして、少し時間が残りましたが、終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-054"},{"speaker":"石田委員","kind":"質問","question":"３３５ページ、市街地整備事業費の大井町駅周辺地区再開発事業から、Ｃ地区について伺いたいと思います。その後、勉強会というのは継続的にやられているのでしょうか。伺いたいと思います。今どういう状況なのか。残っているという理解でいいのか、伺います。それと、再開発準備組合というものに対して、運営等に対して区や都などから補助金などが出る仕組みというのはあるのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"もう一つ、区や都の補助ということですけれども、まちづくりの勉強等で検討する際にも、活動に対しての補助という形で区でも用意がありますので、それは個別に、いろいろなご相談に応じて、都市環境部の部署でも様々な部署の中で、それを支援するメニューはありますので。","voiceIndex":128,"id":"exchange-055"},{"speaker":"石田委員","kind":"質問","question":"それで、準備組合は活動はされていないということですけれども、解散していないというところに、地域の皆さんはすごく危機感を感じております。自主的につくられているみたいにもおっしゃるのですけれども、区の考えとしては、一旦解散して、もう一度、賛同を得て、準備組合をつくるならそうするべきと考えているということかどうか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"ただ実際には、再開発事業というものを円滑に進めるためには、必ず協議会なり準備組合なり、そういう検討組織があって、都市計画と、あとは組合施行で行うのであれば、組合の施行に対して一定の同意が必ず必要ということになりますので。","voiceIndex":130,"id":"exchange-056"},{"speaker":"石田委員","kind":"質問","question":"今現在は、先ほども言いましたけれども、反対の声を上げている方々は排除されている状況です。ですので、準備組合が再指導なり設置なりされることは、排除されたままの状況では許されないという、みんなで話し合ってということですので、このままでの準備組合の設置は望ましくないと区は考えているでしょうか。","respondent":"多並都市開発課長","answer":"地域の方が皆さんでまちづくりの検討をしていただくことが一番重要であって、組織を解散、解散ではないということではなくて、話し合っていただきたいということが重要です。","voiceIndex":132,"id":"exchange-057"},{"speaker":"つる委員","kind":"提案","question":"３１９ページ、路面維持管理費、３２１ページ、かむろ坂根上対策整備工事、３４５ページ、コンクリートブロック塀等安全化支援事業、３５５ページ、災害時応急物資確保費について伺っていきます。路面維持に関連してですが、しなみちレポートについて伺います。","respondent":"森道路課長、高梨公園課長","answer":"区民の方としては、やはり２４時間投稿できるということと、やはり電話よりも大分、ハードルが下がるというようなお話が一部で出ているです。委員ご案内のとおり、なかなか終了後の写真が投稿されていないですが、５月に、八潮公園の園路と区民公園において対応した事例については、写真を用いて完了の報告をしていますが、なかなか全てにおいて対応ができていないということで。","voiceIndex":135,"id":"exchange-058"},{"speaker":"つる委員","kind":"提案","question":"これも２０１６年、根上がり対策が根下げして対策できるということで、当時における広報も含めて提案していたところであって、新たな広報も含めて、これは全国初ということで、ＹｏｕＴｕｂｅもやっているところだと思いますが、３か年で、ちょうど今年度が真ん中ということで、令和５年度にかけて、３工期に分けて、今、進めていただいているところであるかと思います。","respondent":"森道路課長","answer":"かむろ坂の根上がり対策です。委員ご紹介のように、昨年度から令和５年度まで３か年にわたって行う予定でございまして、対策が必要な桜１５か所のうち６か所を新工法で行い、従来工法は２か所、あと植え替えが７か所というような内訳で行っているところです。","voiceIndex":138,"id":"exchange-059"},{"speaker":"つる委員","kind":"質問・要望","question":"全てにおいて足元が大事ということで、そういったことを、まさに見えない縁の下の力のところが、今日の費目に関わる職員皆さんのお仕事だと思いますので、ぜひお願いしたいと思います。かむろ坂はまさに桜の木が名所でありますけれども、ここは毎回聞いています。ここは昭和３１年に１５０本からスタートしたと伺っておりますけれども、今の区全体の街路樹の本数と桜の本数、それから比率を教えてください。","respondent":"森道路課長","answer":"街路樹の本数につきましては、区全区で３,８５３本、桜については１,４４４本で、一番多い樹種になってあります。","voiceIndex":140,"id":"exchange-060"},{"speaker":"つる委員","kind":"質問・要望","question":"桜梅桃李ですから、いろいろな木や花があるのが一番いいのですけれども、桜を１本でも多くという思いで、ずっと求めしています。サステナブル防災備蓄とか、そういう観点も含めてというところも確認させていただいたところでありますけれども、まず、今、昨年１２月の特別委員会の資料等では、また質疑も含めてですが、備蓄物資の有効活用についても、資料を提示して説明がされたところであります。","respondent":"吉岡防災体制整備担当課長","answer":"物資に係る運搬経費ということですけれども、こちらは、どちらにそういった物資を寄附するかということで、年々、金額というのは異なってくるのですけれども、基本的には、地域や学校、小規模なものですとそこまで金額はかからないということで。","voiceIndex":142,"id":"exchange-061"},{"speaker":"つる委員","kind":"確認","question":"それで、食品に関する活用の部分ですが、賞味期限、消費期限とあって、賞味期限についてですが、大体、期限が迫ったものなどの有効活用という言い方になると思うのですけれども、いろいろな自治体のそういったものを見ていくと、１年とかで入れ替えたりとあるのですが、この辺の入替えのタイミングと、どういう期限のものを有効活用しているのかを教えてください。","respondent":"吉岡防災体制整備担当課長","answer":"物資の入替えのタイミング等々、ご質問いただいたところです。物資によって保存年限というのは異なりますので、具体例を出してご説明をしますと、例えばアルファ化米というところになりますと、５年という保存年限です。","voiceIndex":144,"id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"やはり食品ロスの観点でというのは、区がいろいろ活用ということでお配りしても、その先でやはり最終、活用していただくということが一番いいのかなというところでは、やはり求めている先にマッチングさせていくということも、これは防災の備蓄についても大切な観点なのかなと思えてきて、防災備蓄品を受け取ったり提供したりするときの会計処理も。","respondent":"吉岡防災体制整備担当課長","answer":"順不同になりますけれども、先ほど、防災備蓄物資が配布されても食べられていないというような、ちょっと残念なお話もございましたけれども、これはしっかりとご活用いただけるというところで、レシピというところもありましたけれども。","voiceIndex":146,"id":"exchange-063"},{"speaker":"つる委員","kind":"意見","question":"すみません。答弁時間がタイトだったと思います。失礼しました。国では、売払い手続きの実績を勘案した後、有効活用とあります。仕組み自体も違うかもしれませんが、ぜひ引き続き、有効活用を含めて、ご検討いただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":148,"id":"exchange-064"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私からは、３２１ページ、自転車走行環境整備工事、それから３２３ページ、補助１６３号線整備、３３７ページ、公園・児童遊園費についてお伺いいたします。改めて、この間、区が行ってきたこと、警察に対して要望していること、連携して行っていることをお知らせください。駐車監視員とはどういった方で、どのような活動と権限をお持ちの方なのか、活動している時間も分かればあわせてお知らせください。","respondent":"工藤交通安全担当課長","answer":"こちらですけれども、以前、委員からご指摘いただきまして、警察に申入れを行いました。その際には、委員ご説明のとおり、駐車監視員が１グループになって排除活動というものを実施したということで伺っております。","voiceIndex":150,"id":"exchange-065"},{"speaker":"湯澤委員","kind":"質問・要望","question":"交通安全に関する区民からの要望につきましては、課長にご相談するといつも丁寧かつスピード感を持って解決していただいておりますので、本当に感謝しているのですけれども、それだけにこの問題が進んでいないのを残念に思っております。ぜひともこの問題を解決していくために、朝の時間帯に関しましては、自転車専用レーンへの駐停車禁止を検討していただきたいと思いますが、区のご見解をお知らせください。","respondent":"工藤交通安全担当課長","answer":"走行する自転車に対する危険度だけではなくて、自転車が車線変更をするために、後ろから来る車両等にも危険を及ぼすといったところで認識しております。このような違法駐車の取締りならびに規制の関係については、警察と相談をしまして、検討させていただきたいと考えています。","voiceIndex":152,"id":"exchange-066"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ぜひ、所轄警察と連携しながら、朝の時間帯に安心して通勤・通学といったことができるような道路にしていただきたいと思います。次の質問に移ります。大崎ガーデンタワーは４年前に完成されたと思いますけれども、道路も歩道も竣工と同時に完成予定ではなかったのか。道路、歩道ともに、いつ完成予定なのかをお知らせください。","respondent":"森道路課長、多並都市開発課長","answer":"歩道の拡幅であったり、都市計画道路のラインに沿って少し車道を振るような形にはなりますけれども、歩行者の通行等、かなりスムーズになるのかなと考えておりますし、最終的には電柱を３本抜柱して、より安全なまち。もう一個ご指摘がありました大崎支線につきましては、そこから大崎方面に坂を下りたところかと思いますけれども、これについては、道路課で街路事業ということで、認可に向けて設計を進めている段階ということで認識しています。","voiceIndex":154,"id":"exchange-067"},{"speaker":"湯澤委員","kind":"意見","question":"ＪＲの大井支線のガード下の整備は、都市計画を進める際に、建設物の竣工とともに開通するような計画にはならなかったということだと思うのですけれども、それはどういった理由なのか。警備員の費用は現在、誰がお支払いしているのかというところはお知らせください。","respondent":"多並都市開発課長","answer":"今のお問合せは、広町地区の中から大井町線をまたいで補助２６号線を通るところのことかと思いますけれども、そこにつきましては、土地区画整理事業の中で、幹線道路として整備したことになります。そこの中で拡幅して整備していくところです。失礼いたしました。","voiceIndex":157,"id":"exchange-068"},{"speaker":"湯澤委員","kind":"質問","question":"公園・児童遊園費から、緑道公園について質問します。緑道公園は、車が通行しない、樹木や季節の花々が楽しめる、歩行者や自転車が通行できる公園であると考えています。私は、公園利用者を守るために、また区民が公園課への不信感を持たないためにも、許可の取消しに対して明確な規定を策定するべきと考えますけれども、ご見解をお知らせください。","respondent":"高梨公園課長","answer":"今、委員からもご提案がありましたが、しっかりとまずは指導を徹底して、業者にこちらの意図をしっかり伝えること。それでも改善できない場合には、毅然とした態度で区として対応していきたいと考えているところです。","voiceIndex":159,"id":"exchange-069"},{"speaker":"木村委員","kind":"質問","question":"私からは、３１７ページ、交通安全啓発費、２,０５３万円余からですけれども、交通安全運動と交通安全教育とはどのような違いがあるのか。私的には、交通安全運動とは一般向けの運動で、そして、品川区や東京都を挙げての運動と思っていました。そして、交通安全教育とは学校や子どもたちに対する教育との理解をしていますけれども、いかがでしょうか。お願いいたします。","respondent":"工藤交通安全担当課長","answer":"この運動については全国一斉に取り組むものです。毎年、春・秋の年２回実施されまして、春については４月６日から１５日までの間、秋については９月２１日から３０日の間ということで、いずれも１０日間、集中的に実施される運動です。","voiceIndex":162,"id":"exchange-070"},{"speaker":"木村委員","kind":"質問・要望","question":"交通安全運動は全国を挙げての運動でした。そういうことで、やはり誰もが交通事故には気をつけていただきたいと思います。ありがとうございました。事故に巻き込まれやすいのは、子どもと高齢者だと思います。重点的に高齢者と子どもたちを守る運動の対策というものは、特別に何かあるのでしょうか。","respondent":"工藤交通安全担当課長","answer":"先般１０月に、大崎警察署と東京都と連携しまして、高齢者の自転車交通安全教室を実施いたしました。内容といたしましては、自転車シミュレーターを経験していただく。警察官からの安全講話を受講していただく。","voiceIndex":164,"id":"exchange-071"},{"speaker":"木村委員","kind":"質問","question":"私は思うのですけれども、高齢者と子どもたちが手をつなぎながら、高齢者がほほえみながら子どもに教える。笑顔の子どもが高齢者の手を握る。何か、高齢者と子どもたちの特別な友情が生まれそうな感じがするのですけれども、そのようなお考えというか、そのような指導というのは考えられないのでしょうか。お聞かせください。","respondent":"工藤交通安全担当課長","answer":"幼稚園・保育園などでは、そういったことを教育しているところもあるかと思います。区と警察で連携しまして、そういった個々の具体的なところまでの指導は行っていないのですけれども、今後の参考にさせていただきたいと思います。","voiceIndex":166,"id":"exchange-072"},{"speaker":"木村委員","kind":"質問・要望","question":"頭の中で想像するだけでも、高齢者と子どもたちが一緒になってにこにこしている姿を思い浮かべるだけでも、何か幸せになったような感じがいたしますし、これからの日本を、いろいろな事件、醜い事件もたくさん起きていますけれども、そういう点におきましても、また１つの明かりが見えてくるのではないかと思います。ぜひ頑張っていただきたいと思います。そのお金のことに対して、また少しお聞かせください。","respondent":"工藤交通安全担当課長","answer":"放置自転車の撤去関係について、ご質問にお答えしたいと思います。撤去費用につきましては、指定管理者等に支払われる費用ということでございまして、放置自転車を行った者が、撤去されて、その保管料として支払われる金額と、また異なってあります。","voiceIndex":168,"id":"exchange-073"},{"speaker":"木村委員","kind":"意見","question":"そうですね。全ての人がそれを引き取りに来るということは聞いたことがありませんけれども、多分もう要らなくなった自転車を処理するだけでもやはり費用がかかりますので、違法な駐輪をすることによって、それを撤去してもらう。まちから、そういうものがなくなることを、心から願っております。実際にはどのぐらいの率で、今言った引き取りに来るのか、残った自転車をどうするのかをお聞かせください。","respondent":"工藤交通安全担当課長","answer":"自転車の返還についてお答えしたいと思います。八潮北保管所と不動前保管所の２か所で撤去自転車を保管しておりますが、令和３年度、返還した合計台数となりますけれども、６,３０６台です。おおむね７４.９％の返還率でございました。","voiceIndex":170,"id":"exchange-074"},{"speaker":"木村委員","kind":"意見","question":"分かりました。無駄のないようにするしかないと思っています。確かに、自転車というものは便利な乗り物、我々人間には絶対に必要なものであると思っています。小回りが利き、どこにでも停められる自転車。考えれば考えるほど解決策は見つかりませんが、もし解決策があるとすれば、どのようなところから糸口が出てくるのか、お聞かせください。","respondent":"工藤交通安全担当課長","answer":"ただ、着実に放置自転車というものは減少している傾向にありますので、引き続き、三本柱ということで、指導・警告、撤去・保管、駐輪場の維持管理ということをしっかりやっていきまして、取組みを強化してまいりたいと考えております。","voiceIndex":172,"id":"exchange-075","title":"町会・自治会支援"},{"speaker":"木村委員","kind":"質問・要望","question":"頑張っていただきたいと思います。次に、３２９ページ、やさしいまちづくり整備費からです。令和２年度は７,０６８万円余ですけれども、令和３年度は１億７,７８２万円になっています。石でできていて、故意的にでなければ壊れることはないと私は思っていますが、原因はどういうことが考えられるのか、お聞かせください。","respondent":"鈴木都市計画課長","answer":"ただ、座面は自然の木で製作しているということもあって、一定程度、風雨にさらされて、経年変化が起こって、劣化が起こっているというところで、今、区では、全てのお休み石について、その木造の座面のところについて、合成樹脂の、見た目は非常に木調に近い、やわらかい素材で。","voiceIndex":174,"id":"exchange-076"},{"speaker":"木村委員","kind":"意見","question":"このお休み石ですけれども、このようなことで意図的に破損させることなどは考えられませんが、そういうことに対して、どのようにすれば、それを守ることができるのか、分かる範囲でお答えください。","respondent":"鈴木都市計画課長","answer":"お休み石自体は非常にしっかりできているものですので、なかなか意図的に破損というのは、報告としては上がってきていないのですが、やはり全てのお休み石、二百五十何基ありますが、全て場所についても把握していますし、定期的に見回り等も行ってありますので、そうした中で。","voiceIndex":176,"id":"exchange-077"},{"speaker":"松澤委員","kind":"質問・要望","question":"私からは、決算書３５３ページ、防災体制整備費と、３５５ページ、避難所に関連することについて質問いたします。はＬＩＮＥ防災です。品川区公式ＬＩＮＥの防災メニューを充実してほしい。私をはじめ、議員の質疑におきまして、各議員からも要望がありました防災メニューの拡充。このようなリニューアルに至った経緯の説明をお願いいたします。","respondent":"平原防災課長","answer":"委員ご指摘のとおり、導入当初は、区のホームページへのリンクにとどまっていたところですけれども、情報を受け取る方にとって、より分かりやすく、さらにその先の情報につなぎやすくするための検討を防災課内で進めさせていただきまして、令和４年度、今年度。","voiceIndex":179,"id":"exchange-078"},{"speaker":"松澤委員","kind":"提案","question":"見やすくなりました防災メニューの中で、またさらなる要望として、ちょっとしつこいですけれども、デジタル防災の要素も増やしていただけたらと考えています。以前にも提案させていただきましたけれども、このデジタル防災、そのときは福岡市の「とつぜんはじまる避難訓練」というものを紹介させていただきました。このメニューの中に、楽しく学べる防災などを入れてみても、とてもよいのではないでしょうか。","respondent":"五十嵐災害対策担当課長","answer":"子ども向けキッズ防災クイズでは５７８回のアクセスがございました。今後もデジタル防災訓練のさらなるコンテンツの充実を図ってまいりたいと思います。","voiceIndex":181,"id":"exchange-079"},{"speaker":"松澤委員","kind":"質問","question":"ｅラーニング、おっしゃるとおり、そういうメニューがあることは大変すばらしいと思っています。それは、防災学校に行ったり、これを調べないとなかなか分からない部分なので、ぜひプッシュ型ですか、品川区の公式ＬＩＮＥの中に入れていただけると、これは誰でも簡単につながるので、そういった活用をお願いします。最後にご見解をお聞かせください。","respondent":"五十嵐災害対策担当課長","answer":"防災タブレットはＬＩＮＥ機能も活用できることから、今年１２月の区内一斉防災訓練では実験的に使用することを進めてみたいと考えています。この訓練結果を基に、区民への情報共有についても検討していきたいと考えております。","voiceIndex":183,"id":"exchange-080"},{"speaker":"松澤委員","kind":"質問","question":"防災タブレット、そうですね。続きまして、避難道の周知です。先ほど我が会派の小芝委員も、国防、国防と強く、熱い質問をされておりましたが、私もこのＪアラートについて聞きたいです。どこに避難したらいいのか。この緊急一時避難施設は、２００４年に施行された国民保護法、都道府県知事や政令都市に確保の義務があり、避難施設のうちコンクリート造りなど頑丈な施設を指します。教えてください。","respondent":"五十嵐災害対策担当課長","answer":"緊急一時避難施設のお尋ねですが、区内に９８か所あります。内訳として、小・中学校など４８施設、シルバーセンターなど１１施設、児童センターなど２６施設、そして地下駅舎は、目黒駅３線分を３施設と勘定し、８施設、都立学校など５施設となります。","voiceIndex":185,"id":"exchange-081"},{"speaker":"松澤委員","kind":"質問","question":"そうですね。国や都だったのです。私は区というか、そのホームページで、いろいろ緊急一時避難で探したのですけれども、一時避難場所、避難所、広域避難、津波避難と、なかなかこれにたどり着かなかったです。これは非常に分かりづらいと思っています。先ほどもちょっと質疑があり、かぶってしまいますけれども、この緊急一時避難施設、避難の計画、運用のマニュアルがあったら教えてください。","respondent":"五十嵐災害対策担当課長","answer":"武力攻撃事態等における避難の計画などに関するお尋ねですが、令和２年３月に、品川区国民保護計画に基づく避難実施要領を策定しております。計画している６つのパターンのうち、弾道ミサイルによる攻撃も入ってあります。","voiceIndex":187,"id":"exchange-082"},{"speaker":"松澤委員","kind":"質問・要望","question":"おっしゃるとおりです。これは、自治体がどうやってくれと言われても非常に難しい。もう、これは本当は国がやるべきだと私も正直思っております。先ほど訓練という話をしていましたけれども、私は、防災訓練、避難訓練の際に、緊急一時避難施設に触れていただきたいです。そうすることによって、この緊急一時避難施設というものが、区民の皆様に周知が広がると思いますが、ご見解をお聞かせください。","respondent":"五十嵐災害対策担当課長","answer":"あわせて、緊急一時避難施設についても触れていきたいと考えております。都との連携訓練につきましては、都の国民保護担当と相談していきたいと考えています。","voiceIndex":189,"id":"exchange-083"},{"speaker":"松澤委員","kind":"質問","question":"万が一、大規模災害が起こり、多くの方が避難所に押し寄せた場合、現在、杜松ホームでは収容し切れないのではないでしょうか。大崎高校、さっきの緊急一時避難施設になりますけれども、大崎高校が例えば補完場所になるということはお聞きしていますが、実際にどのような話し合いが行われているのか教えてください。品川区と協定を結んでいる団体との協議ですね。例えば、ホテル業界というか、民宿業界ですか。","respondent":"吉岡防災体制整備担当課長","answer":"引き続き、在宅避難を推奨していくとともに、委員よりご提案いただきました、ホテルの空き部屋の確保につきましても、有用であると認識しておりますので、そちらも含めまして、今後も避難所の確保に努めてまいります。","voiceIndex":191,"id":"exchange-084"},{"speaker":"松澤委員","kind":"質問","question":"そういった話し合いがしっかりできていれば安心しました。１点だけ、大崎高校が補完避難所というお話がありましたよね。そういったときに、避難所連絡会議、町会、また有志の方ですか、町会と区の方が主となるのですけれども、こういうときに大崎高校側から参加者があるのか。そういったことだけ教えてください。","respondent":"吉岡防災体制整備担当課長","answer":"しかしながら、補完避難所の位置づけにつきまして、地域の方にご理解いただくことは非常に重要なことですので、周知方法につきましては、しっかりと検討してまいります。","voiceIndex":193,"id":"exchange-085","title":"町会・自治会支援"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３２９ページ、区民の自主的なまちづくりへの支援、まちづくりマスタープラン改定検討経費、３４９ページ、居住支援事業、３５３ページ、応急活動対策費、４９８ページ、災害復旧費についてお伺いいたします。品川区居住支援協議会はまだ立ち上がったばかりですので、今後設置の目的が達成されますよう、機能を充実していただきたいと要望いたしますが、現在の進捗と課題を教えてください。","respondent":"竹田住宅課長、鈴木都市計画課長","answer":"令和４年度はさらに一歩進めまして、セミナーをご覧いただく方に、より身近な問題と捉えていただけるよう、先行自治体等の連携事例のご紹介などのご講演をしていただくことを考えているところです。今後も、子ども、若者というのは、もうしっかりまちづくりの担い手、将来も含めて現在の担い手だという認識を持って、マスタープランの策定あるいは今後のまちづくりを進めていきたいです。","voiceIndex":197,"id":"exchange-086"},{"speaker":"横山委員","kind":"提案","question":"パズルがありまして、そのパズルのピースを１つ外したときに、そこをどうはめていいかというのが分かるようになります。時間がありませんので要望みたいな形になってしまうのですけれども、３点目に応急活動対策費については、平成３０年からトイレトレーラーについて提案・質問していますので、引き続き検討をいただきたいと考えています。４点目ですけれども、災害復旧費についてです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":200,"id":"exchange-087"},{"speaker":"あくつ委員","kind":"提案","question":"自転車の区民交通傷害保険ですけれども、今までいろいろな質問をさせていただいてきて、区内では毎年２００件前後、自転車に関係する人身事故が発生していて、私自身も南品川で発生しました自転車による死亡事故の被害者の方からご相談を受けたこと、また損害賠償額が高額になってきたという報道が非常に多くなってきたということと。","respondent":"工藤交通安全担当課長","answer":"区民交通傷害保険の加入者数ですが、令和４年度は３,１９４人ということで、前年比プラス２８名という状況になってあります。","voiceIndex":202,"id":"exchange-088"},{"speaker":"あくつ委員","kind":"確認","question":"これは、民間の様々な保険もありますけれども、まだまだこれから加入していただく余地があるのではないかと思います。初年度に私も申し込みましたが、そのときにはなかった保険やサービスも今出てきておりますので、２つ確認させてください。これは令和２年度から附帯されているようですけれども、これをつけた理由、内容も若干教えてください。この追加の理由を教えてください。","respondent":"工藤交通安全担当課長","answer":"こちらについては、委員ご説明のとおり、犯罪被害者や、ひき逃げの被害者に対する補償ということで附帯されております。令和元年度の実績を見ますと、賠償金額が非常に高額になったということを踏まえまして、令和３年度、掛金が若干増加になっているという状況です。","voiceIndex":204,"id":"exchange-089"},{"speaker":"あくつ委員","kind":"確認","question":"理由も聞いたのですけれども、それはまた、おいおい確認しますけれども、まずは犯罪被害の補償がついたという。つくにこしたことはないですけれども、その辺りを教えていただきたかったということがあります。例えば令和３年度、保険を適用した例があったのか。「終わってしまった」みたいなのがあるので、ぜひこれはやってもらいたいと思うのですが、ご見解をお知らせください。","respondent":"工藤交通安全担当課長","answer":"港区の中途加入の事例ですけれども、港区に確認しましたら、本年度から試験的に実施ということで始めたです。まだこれからどのような状況になるのかというところもあろうかと思いますので、その辺を注視しながら、こちらも取り組んでまいりたいと考えています。","voiceIndex":206,"id":"exchange-090"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２７件、そのうち２件が自転車事故ということで、数十万円の支払いがあったということで、実績もできた。インターネットの申込みのほうも、ぜひこれはやっていただきたい。取り組むということでしたけれども、お願いします。次に、橋梁管理費。時間がないですが、青物横丁駅前歩道橋。これも何度もやっていますが、国会で質問してもらって、国土交通省の道路局長から答弁をもらいました。","respondent":"鈴木都市計画課長","answer":"青物横丁駅前交差点のバリアフリー化についてのお尋ねですが、ご紹介いただいた令和３年２月の国会でのやり取り以降、国が主導となりまして、関係機関、国道事務所になりますが、それから東京都、警察など関係機関と情報を共有しながら、今、国の主導で調整が進められているです。","voiceIndex":208,"id":"exchange-091"},{"speaker":"あくつ委員","kind":"質問","question":"その協議の内容や回数、もしここで言えるものがあるのであれば教えてください。","respondent":"鈴木都市計画課長","answer":"関係機関が一度集まりまして、様々な交差点周辺の状況について共有し、今後の進め方等についても国からお話があったと。区としては、具体的に、より明確な取組方法を明示いただけるように、今後も強く国に働きかけていきたいです。","voiceIndex":210,"id":"exchange-092"},{"speaker":"芹澤委員","kind":"質問","question":"私からは、３４９ページ、ファミーユ西五反田東館火災被害調査業務委託について、関連してマンション防災について、あと、３１７ページの交通安全啓発費についてお伺いいたします。調査委託として、調査に４００万円超かかったということで記載がありますが、まず、この内容をお聞かせください。","respondent":"竹田住宅課長","answer":"火元と思われるところが１３階ということで、かなり黒煙が出る大きな火災となりましたので、その煙や炎によって上下階等にどのような影響があったのか、あるいは躯体に影響がなかったのかというものを専門業者に調査していただいたものが、こちらの調査委託です。","voiceIndex":213,"id":"exchange-093"},{"speaker":"芹澤委員","kind":"質問・要望","question":"聞き取り調査についても、聞き取り調査という紙ではなくて報告ベースだったというようなお話もいただいていて、これは周辺の住民の方には、どういった被害があったのかというのは、ぜひ今後としてはしっかりと確認いただきたいと思います。","respondent":"竹田住宅課長","answer":"今回の案件につきましては、委員ご指摘のとおり、個々の聞き取りというよりは申し出ていただくという形で進めてまいりました。今後、今回の案件を礎にしまして、より丁寧な、居住者の方への対応というものを考えていきたいと思います。","voiceIndex":215,"id":"exchange-094"},{"speaker":"芹澤委員","kind":"提案","question":"非常に大きな火災で、先ほど申し上げたとおり、当日、リアルタイムでの中継が行われるほどの火災でした。この建物の町会は非常に防災訓練を熱心にやっていらっしゃって、迅速に対応できたというようなお話も伺っております。以前もこれは提案させていただきましたが、マンション単位での防災組織の評価といいますか、防災認定マンションというのも他の自治体で広がっていると理解しています。","respondent":"平原防災課長","answer":"先ほどご指摘がございました認定マンションというような形については、今はまだ、いろいろなところ、様々な事例を検討させていただいているところですが、本年５月の首都直下地震の被害想定の見直しの中でも、新たにマンションの訂正シナリオという形で。","voiceIndex":217,"id":"exchange-095"},{"speaker":"芹澤委員","kind":"質問・要望","question":"当然、町会の議論のときに私は呼ばれていませんけれども、やはり向こう３軒両隣ですか、少し小さなコミュニティを区切って、しっかりと町会でまちを守ってくださいというようなところで町会というものができたのだろうと思っていますが、そこの目に見えない線引きをあえてつくる必要が当時はあったのだろうと思っています。","respondent":"工藤交通安全担当課長","answer":"原動機付バイクの件についてお答えさせていただきたいと思います。委員ご指摘のとおり、タイヤの太い原動機付の、見た目は自転車ですけども、こちらは分類上は原動機付自転車の扱いになってあります。当然ながら、原付を運転できる……。","voiceIndex":219,"id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私からは、３３５ページの広町地区整備検討委託について伺いたいと思います。総務費の質問に引き続いて伺います。共産党としては、２０１８年度までは情報公開で、その委託報告書を全て取りましたけれども、その後、２０１９年度からも、今年度まで検討委託は続いています。５億円超の検討委託費です。その中身は一切議会にも報告されたことがないのではないか、伺います。その点について伺います。","respondent":"多並都市開発課長","answer":"これが大きな２つのところです。今後の公開につきましても、当時検討していたものというのは、当時の協議の中で進めてきたものですので、現時点では公開すべきではないと考えるところです。","voiceIndex":222,"id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５億円を超える区民の税金を使って検討業務を委託した。私は改めて、これは公開を強く求めておきたいと思います。新庁舎整備基本計画作成に当たり、これまでの検討委託の報告書がどう活かされたのかを伺いたいと思います。これは、その１です。これが、その４です。そして、その報告書は都市環境部が独占して、庁内で共有されることも、庁内で検討されることもないのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"今回のまちづくりの検討については、進め方といたしまして、先ほど、平成２５年から本格的にまちづくりの検討を進めているとお話しさせていただきましたけれども、これについては、この検討を進めていく中で、まとまってきたら、先ほど秘密という話がありましたけれども。","voiceIndex":224,"id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私が伺ったのは、この報告書というのは、庁内で共有されることはないのか。そして、これは、契約者が総務部長になっているのに、総務部に報告書を届けない。そして、総務部が見ていないというようなやり方の仕組みというのが、調査としてあり得るのかということを伺っているので、そのことを答えてください。","respondent":"多並都市開発課長","answer":"もう一度ご説明しますが、まちづくりの検討をしているのであって、そのまちづくりを検討するときに必要な関係する協議、または情報交換であったり情報収集をするのに、関係する部署と協議しながら進めていくという形で受けながら、成果をまとめてきているということです。","voiceIndex":226,"id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今の答弁は分からないのですけれども、基本計画の業務委託した報告書は、総務部に届けたのか、どうなのか。総務部が見ていないということがあるのか。そのことを伺いたいです。","respondent":"多並都市開発課長","answer":"委託の、要するに実施の事務手続きの話になりますけれども、契約を結ぶときの決定ではなくて、今のお話は成果物のことですね。成果物の納品については、各所管が受けて持っているものですから、各所管が責任を持って保管しています。","voiceIndex":228,"id":"exchange-100"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これだけのお金を使いながら、この計画を立てるに当たり、計画の業務委託をしたということを全く共有しないし参考にもしていない。そういう税金の使い方としても、私は間違っていると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":230,"id":"exchange-101"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これらは、現在のこの事業の勝島人道橋の整備に関して、回遊などと関わりがあると思いますが、こちらは少し先の話なので、これらとは切り離して、先行して人道橋と周辺整備が進められていくのでしょうか。これは、品川区の海岸、沿岸がありますので、こちらとの関係はどうなのでしょうか。ここについてはどういうことでしょうか。こちらの障害者施設の清掃委託の増額を求めますが、いかがでしょうか。","respondent":"森道路課長、高梨公園課長","answer":"デジタル館につきましては、たしか夜は２５時ぐらいまで開いているのかなと認識しておりますけれども、朝は８時半からだったかと思います。特に朝方につきましては、そこが使えないというところもあります。引き続き、よくお声を聞きながら、継続してお願いしたいと考えているところです。","voiceIndex":233,"id":"exchange-102"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それから大井町は、いろいろ関係機関とということですが、ヤマダ電機と具体的に交渉しよう、あるいはその可能性を探るというところはいかがでしょうか。やはり朝の部分に関してはどうしても、使わせていただけると、利用者の方が大変、利便性が利くと思うので、そこは１つお願いします。その点について、今後の増額等の見込みはいかがでしょうか。","respondent":"森道路課長、高梨公園課長","answer":"そういったものをうまく活用することがまず１つかと、ご提案を聞いて思いますので、まずは現地の確認とか、あるいはヤマダ電機に状況を伺うとか、そういったところから始めていければと考えています。清掃委託費の今後の見込みについてですが、一定程度、現在委託している予算額につきましても、福祉団体向けの予算ということで、一定配慮した予算額としているということもありますが、昨今の物価高等の影響もありますので。","voiceIndex":236,"id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"意見","question":"大井町のほうは、ありがとうあります。お掃除の委託費に関しては、シーリングでも減らしていないということで、大変ありがたい状況だと思います。今、お話しがありましたが、ぜひ声を聞いて、今後、増額等を含めて検討をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":239,"id":"exchange-104"},{"speaker":"西村委員","kind":"質問・要望","question":"３１７ページ、交通安全啓発費、３１９ページ、駅周辺等放置自転車対策事業、時間が許せば３３７ページの公園・児童遊園費について伺ってまいります。放置自転車について伺います。先ほどより様々、皆さんからご質問が出ておりますが、区営駐輪場の利用率もしくは利用状況が分かれば教えていただきたいと思います。分かる範囲で結構です。","respondent":"工藤交通安全担当課長","answer":"内訳につきましては、これは自転車になりますけれども、自転車の定期利用が５５.６％。バイクの定期利用が６９％、続いて当日利用になりますけれども、自転車が８１.１％、バイクが１０９.２％という状況でございました。","voiceIndex":241,"id":"exchange-105"},{"speaker":"西村委員","kind":"提案","question":"トータルで見ますと様々、差がありまして、大変参考になります。１か所ずつ見ますと、またパーセンテージも違ってくるのかなと思います。そこで、駐輪場の場所が分かるアプリのご提案をさせていただきたいと思います。アプリを独自開発するよりも、既にある、このような民間企業との連携で、予算を抑えて改善を図れるのではないかと考えていますが、区のお考えを伺います。","respondent":"工藤交通安全担当課長","answer":"こちらを今年度中に導入できればというところで検討しています。","voiceIndex":243,"id":"exchange-106"},{"speaker":"西村委員","kind":"質問・要望","question":"アプリはウェブでも見られるのですけれども、アプリの場合、導入された自治体によりますと、不正駐輪が明らかに減った場所があるということを伺っております。申し上げておりますが、このアプリでは、区営だけではなく民間の小規模な駐輪場を点在することができますので、地元の買い物客らの動線をカバーできる可能性があり、不正駐輪の対策に向くと伺っております。","respondent":"工藤交通安全担当課長","answer":"民間との連携ですけれども、当初予定しておりますのが区営駐輪場のみの表示ですので、また委員ご提案のアプリの関係についても、こちらで確認をさせていただきまして、今後考えていきたいと考えています。","voiceIndex":245,"id":"exchange-107"},{"speaker":"西村委員","kind":"質問","question":"ぜひともご検討いただければと思います。こういった取組みが普及しましたら、区民の皆様がきれいなまちづくりに参加できるようになるのではないかと考えていますので、どうぞよろしくお願いいたします。自転車は車道を走ることがルールですので、後ろからの追突を防ぐためにも、リアライトを増設すると、より安全性が高まると、自転車屋から伺いました。子ども乗せ自転車の事故も増えています。","respondent":"工藤交通安全担当課長","answer":"後ろの反射材のリアライトの関係ですけれども、私も把握してございませんで、今後、実物を確認しながら、そちらの有用性についても考えてまいりたいと思います。","voiceIndex":247,"id":"exchange-108"},{"speaker":"西村委員","kind":"提案","question":"リアライトを私も少し調べてみたのですけれども、子ども乗せ電動自転車の場合、フロントライトも比較的に明るくないものが多いそうでして、対向車や歩行者からも自転車の存在に気がついてもらえる確率が下がってしまうと、こちらも自転車屋から伺っております。そこで、保護者が自転車で集まる機会というのは幼稚園や保育園の送り迎えですから、ここで親向けの交通安全教室の実施ができないかと考えています。","respondent":"工藤交通安全担当課長","answer":"保育園・幼稚園における交通安全教育ですけれども、現在、警察と連携いたしまして、可能な限り、園児に対する交通安全教育というものを実施しています。","voiceIndex":249,"id":"exchange-109"},{"speaker":"西村委員","kind":"確認","question":"子ども乗せ自転車のフロントライトがそれほど明るくないということは、私も自分で乗っていて知りませんでしたので、改めましてご確認いただきまして、啓発に努めていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-110"},{"speaker":"たけうち委員","kind":"質問","question":"交通安全ですけれども、新聞報道等で、１０月末から警視庁が、自転車の安全運転ということに対して非常に取締りが厳しくなるということが報道されておりますけれども、どのような形で厳しくなっていくのかということと、また、区で何かそういうことが、警察からお話が来ているのかどうかというのを教えてください。","respondent":"工藤交通安全担当課長、平原防災課長","answer":"そのうち１６か所については既に導入済みということですので、残り３か所になります。３か所につきましても、今年度中の導入を予定しているところです。ＩＣカードの利用率ですけれども、全体の７０％です。防災区民組織が設置する防災倉庫ですが、こちらは町会・自治体を母体として自主的に組織する防災区民組織という特性から、まずは組織の皆様が自分たちで設置していただくということになりますけれども、２つございまして。","voiceIndex":253,"id":"exchange-111"},{"speaker":"たけうち委員","kind":"提案","question":"そこでいきなり、もしこのルールがこれからなってくると非常に、悪気はないのだけれども、そういうふうになっている。それが１つ。それで、町会長からご連絡いただいて、自助・共助・公助という中で言うと、何かあったときに自分たちがやはり活躍していくわけなので、そこにけがも伴ったりするのだけど、その費用はやはり区で出してもらえないのかというお声があったので、一応もう一回、見解をお伺いします。","respondent":"工藤交通安全担当課長、平原防災課長","answer":"２点お答えします。交通ルールのチラシでの広報・啓発についてです。警察署と合同で街頭キャンペーン等においてやってありますので、引き続き、一人でも多くの方に正しい交通ルールが伝わるように取り組んでいきたいと考えています。区民消火隊で使っているような動力ポンプ置場につきましては、委員ご指摘のとおり、区で行うこと、ある意味、公助の支援という性格を持っておりますので、こちらについては区で対応していますけれども。","voiceIndex":256,"id":"exchange-112","title":"町会・自治会支援"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それからＩＣチップは、料金のことは、１０年ぐらい前にやったときも、当時の担当課長が、業者と検討しますと言って、いい返事をいただいたのだけれども、やはり代わられてしまうことが多いものですから、しっかり引き継いでいただいて、ぜひそれも対応していただきたいと思いますが、一応一言お願いいたします。","respondent":"工藤交通安全担当課長","answer":"確実に引継ぎを行って進めたいと思います。","voiceIndex":259,"id":"exchange-113"},{"speaker":"松本委員","kind":"質問","question":"私からは、３４１ページ、しながわ水族館運営費、多分時間がないかもしれないですけど、私も先日の社会実験に乗らせていただいたので、水辺利活用事業について、舟運について、何とかここも触れられればと考えています。時期限定ですね。なので、例えば期間限定あるいはイベント限定で夜間に営業していただくということが考えられるのではないかと思いますが、見解を伺います。","respondent":"高梨公園課長","answer":"そのことと、あと水族館の開園当初、非常に多くの方が来館されて、周辺の住民の方々に一定ご迷惑をおかけしたということもあって、そういった経緯から現在、夜間営業は行っていないところですが、いろいろと年月も過ぎて。","voiceIndex":262,"id":"exchange-114"},{"speaker":"松本委員","kind":"質問","question":"この水族館についても、水族館単体で考えるのではなくて、やはりこの区民公園全体が活性化していくというのも１つ考えないといけないのかなと思っていて、例えばイルミネーションとかというところも考えていく。今、マルシェやイベント、イルミネーションの話もさせていただきましたので、この辺りについても、水族館だけではなくて公園全体の運営について少しご見解を伺えればと思います。","respondent":"高梨公園課長","answer":"現在も工事中ですけれども、区民公園は段階的に再整備を行ってまいりまして、来年度、全体の再整備が終わるという節目を迎えますので、そういったタイミングで地域の方々ともよく話し合って、地元の大井第一地区を中心に。","voiceIndex":264,"id":"exchange-115"},{"speaker":"松本委員","kind":"質問","question":"これは、出演していただく、来ていただくというところの出演料から、さらに参加の費用だけではなくて、そこから効果という意味では、どんどん拡散していくというところまで、梶さんのイベントも、実際にお客さんに来ていただく何かしらのイベントができたらさらによかったのかななどというところも思うのですけれども、こうした有名人を活用した広報、あるいはドラマの撮影や映画の撮影。","respondent":"高梨公園課長","answer":"ドラマロケ地等のＰＲにつきましては、現在でも年間８０件から１００件程度受け付けているのですが、使っていただいた際には、最後のクレジットに「しながわ水族館」と入れていただくであるとか、こちらからプッシュ型というか、積極的な働きかけにより。","voiceIndex":266,"id":"exchange-116"},{"speaker":"松本委員","kind":"質問・要望","question":"最後に、今、サンシャインシティの名前が挙がって、やはりサンシャインシティは、池袋の水族館を物すごくＶ字回復をさせたことでも有名なところかと思いますので、これからリニューアルに当たっては、いろいろな方の意見を聞きながらというところはありますが、私たち、維新としてはＰＦＩというものをよく言いますけれども、ぜひ実際に運営されている方の意見も聞きながらやっていただきたいと思いますが。","respondent":"高梨公園課長","answer":"現在の運営者が一番状況を把握していると思いますので、サンシャインシティからもよく話を聞いて進めてまいりたいと考えます。","voiceIndex":268,"id":"exchange-117"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３２１ページ、立会川緑道整備（３工区）、３３３ページ、不燃化特区支援事業、３４７ページ、空き家等対策事業についてお伺いいたします。最初に、３２１ページ、立会川緑道整備（３工区）に関連しまして質疑をします。歩行者と自転車の利用者が、ともに安全に通行できる道路環境の整備が行われ、間もなく整備が完了する方向となっておりますけれども、現在の進捗状況をお知らせいただきたいと思います。","respondent":"森道路課長","answer":"現在、立会川緑道整備工事につきましては、２工区、最後の区間について工事を進めているところです。ちょうど１１月に入った前後から実際に工事に着工いたしまして、今のところ順調に進んでいるです。","voiceIndex":271,"id":"exchange-118"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そこで、震災時の、震災時以外でもあると思うのですけれども、緊急車両の進入が可能となるということですけれども、整備完了後に、実際に緊急車両が走行してやっていくのかという、地元の方たちからも「どうなのですか」と、私のところにも声が届いておりますので、今後、どういうふうに車両を運行させるのか、しないのかという、整備が全区間終了した後の今後の展開を教えていただきたいと思います。","respondent":"森道路課長","answer":"ただ、日頃からといいましょうか、そういった消防、警察、救急といったものの進入ということも、今後少し地域の意見も聞きながら検討していければと思っています。","voiceIndex":273,"id":"exchange-119"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうすると、緊急時、消防自動車の普通のポンプ車ですと７.５トンぐらいあります。それで、実際に近隣で火災があったときは、当然、緊急車両、消防車のポンプ車が入れないという認識でよろしいのでしょうか。","respondent":"森道路課長","answer":"今、下に立会川幹線という下水が流れておりますけれども、下水道局からは２トンの重量規制ということで言われております。ですので、その重量だけ考えると、１つ難しい部分かと思うのですけれども、緊急時、どのような活用ができるか。","voiceIndex":275,"id":"exchange-120"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ、地域の消防団の方とも協議をしていただいて、地域と連携して、緊急時に備えていただきたいと思います。ぜひ、よろしくお願いいたします。続きまして、３３３ページ、不燃化特区支援事業、続けて３４７ページ、空き家等対策事業についてお伺いいたします。大まかでいいのですけれども、把握している一軒長屋の数と空き家の数がどういうふうになっているのか、お知らせいただきたいと思います。","respondent":"竹田住宅課長","answer":"今年３月末現在の数字ですが、品川区全体の不適正管理状態の空き家が９０棟です。一軒長屋というのは、１つの建物に数世帯が入っているものだと思われますが、そちらの数については承知してございません。","voiceIndex":277,"id":"exchange-121"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。これは木密地域なので、その中で、今、空き家と申し上げましたけれども、いろいろ、その地区の中でも助成しているところがあると思うのです。その件数と、あと空き家の、所管同士の連携という点を教えていただきたいと思います。","respondent":"大石木密整備推進課長","answer":"あわせまして、空き家対策との連携についてですが、従前から住宅課とは情報を共有しておりまして、今後も引き続き情報共有を密に行いながら、当課といたしましては不燃化の促進の視点で、住宅課としましては空き家対策の視点で。","voiceIndex":279,"id":"exchange-122","title":"町会・自治会支援"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３３１ページ、空港環境経費に関わって、羽田新ルートの運用停止について、３３５ページ、戸越公園駅周辺地区再開発事業に関わって、戸越公園駅周辺の再開発について伺います。今議会に、運用停止を求める請願署名が提出されました。区内全域で、羽田新ルートはやめてほしいという願いの現れだと思います。区は、これだけ強い願いを重く受け止めるべきですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区の受け止めとしましては、運用開始からこれまで、区民の方から５３１件の様々なお声をいただいております。こうした声と同様、重く受け止めているというところで、区はこれまで、区民の方のこうした声を国にしっかり届けてまいりました。","voiceIndex":282,"id":"exchange-123"},{"speaker":"のだて委員","kind":"質問・要望","question":"重く受け止めるということですので、これはやはり、運用を実施されてから２年半以上が過ぎましたけれども、これだけ運用停止を求める声があることは重く受け止めていただくということで、ぜひ、そうしていただきたいと思います。これだけ声がやはり広がっていて、特に区も重く受け止めるというのであれば、区が運用停止を国に求めるべきだと思います。","respondent":"鈴木都市計画課長","answer":"固定化回避検討会の状況についてのお尋ねですが、固定化回避につきましては、２年前、羽田新ルートが運用開始される以前、この新ルート運用を様々な角度で国が検討してまいりました。その中で、新飛行ルートというのが決定し、行われていると。","voiceIndex":284,"id":"exchange-124"},{"speaker":"のだて委員","kind":"質問・要望","question":"区は、少しでも軽減されるよう注視するということですけれども、国が検討している方式でも品川区の上を飛ぶことになりますし、仮に飛ばなくなったとしても、この方式を使うのは天候のよい日に限られることもあって、検討中の方式を使っても、現在の羽田新ルートが運用されるということは、国交省にも確認しています。区は運用停止こそ求めるべきだと思いますが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ご質問の中に、固定化回避が図られた場合に、現在の運用がもう行われないのかですが、まだその辺の具体的な内容は一切示されてございませんので、その辺のお答えは、まず今の段階ではできないです。","voiceIndex":286,"id":"exchange-125"},{"speaker":"のだて委員","kind":"質問・要望","question":"今、検討段階で、示されていないということですが、私が言ったとおり、天候が悪い日というのは、現在の羽田新ルートが運用されることになるということで、実際、固定化回避検討会自体は来年秋ということですから、そうなると、３年半もたつということになります。でたらめな活動をしている準備組合やまちづくり協議会に補助金を出すのはおかしいと思いますが、なぜ補助金を出すのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今現在、戸越公園は、連続立体交差事業であったり、駅前広場、または補助２９号線、様々な都市計画事業が進められているというところで、区民の方が自主的にまちづくりを検討されているです。","voiceIndex":288,"id":"exchange-126"},{"speaker":"のだて委員","kind":"意見","question":"区民が自主的にと言いますが、地権者にも相談なく勝手に計画を立てているというのが実態です。住み続けたいと願う住民を強制的に追い出し、まちを壊す再開発に税金投入し、推進するのはやめるべきです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":290,"id":"exchange-127"},{"speaker":"塚本委員","kind":"質問","question":"私からは、３４７ページ、空き家等対策事業、それから、３５３ページ、品川区強靱化地域計画作成経費をお伺いしたいと思います。３点目ですけれども、有効活用ということで、これは令和３年度も実績としては出てきていないということで、なかなか結果に結びつかないですけれども、令和３年度について、またこの有効活用についてどのような状況であったのか、以上３点をまずお伺いしたいと思います。","respondent":"竹田住宅課長","answer":"周知方法としては様々ありますが、例えば区のホームページ、広報紙、ケーブルテレビ、ＳＮＳへの配信、チラシの配布、ポスターの掲載等々が考えられますが、様々な周知方法の中から、どの方法が一番有効なのか、今後検討していきたいと考えております。","voiceIndex":292,"id":"exchange-128"},{"speaker":"塚本委員","kind":"質問","question":"そういった中で、まずは所有者不明土地というのはそもそもどういう、福利増進事業に使えるというか、福利増進事業に当たるような、事業に充てられるような所有者不明土地というのはどういったものを指すのかということと、また、区内にそういった不適正管理で所有者不明土地というものに、今回の法律の拡大に当たって、当たるような空き家というのは存在しているのかどうか。この２点をお伺いいたします。","respondent":"竹田住宅課長","answer":"今回、法改正等があったところですが、区内に、それに該当して改善されるものがどれぐらいあるかということは、ちょっとまだ精査していない段階ですので、これからしっかり精査して、法改正の趣旨が活きるような対策を取っていきたいと考えています。","voiceIndex":294,"id":"exchange-129","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"質問・要望","question":"例えば、所有者不明土地等の空き家をそうやって有効活用していこうといったときに、木密整備推進課でやられているＵＲの土地取得事業といったものともうまく連携しながら進めていくことも１つのアイデアではないかと思いますが、その点に関していかがでしょうか。","respondent":"大石木密整備推進課長","answer":"ＵＲとの協定についてのご質問です。委員にご指摘いただきました協定というのが、木密事業に関する協定といいまして、西品川地区と、今現在は豊町、二葉・西大井の２地区で協定を結んでいるものです。","voiceIndex":296,"id":"exchange-130"},{"speaker":"塚本委員","kind":"質問・要望","question":"最後に、時間があまりなくなりましたけれども、品川区強靱化地域計画作成経費に関連して、在宅避難ということについてお伺いしたいのですけれども、地域防災計画などにも在宅避難という章立てはないのですが、今後これはしっかり章立てをして力を入れていっていただきたいです。ちょっと短い答弁時間ですが、ご見解をお願いいたします。","respondent":"平原防災課長","answer":"災害発生時の在宅避難につきましては、健康維持等々に非常に重要なことですので、様々な計画、地域防災計画、強靱化計画といったものと相まって推進していきたいと考えています。","voiceIndex":298,"id":"exchange-131"},{"speaker":"鈴木（真）委員","kind":"確認","question":"あの交差点のところに少しスペースがあるのです。逆に、さっき言った改修によって十分に広がるのだったらそれで結構ですけれども、安全性のために確認させてください。ただ、時間があまりに際どいと、ロータリーを渡っていたら、信号を渡ったり歩道橋に上ったりすると危ないのもあるのですけれども、何か見やすい形というのができないかということの確認をしたいと思いますが、よろしくお願いします。","respondent":"森道路課長、鈴木都市計画課長","answer":"私からは、１６３号線の大井町線のガード下の部分についてお答えをします。今、委員ご指摘の、白いフェンスがあるところですけれども、そこの部分は、今現在行っております道路整備工事で、歩道が１ｍほど拡幅する予定になっております。ただ、いろいろこれから、その辺のデジタル化あるいはデジタル表示というのは、技術の進展というのもあるでしょうし、今いただいたご意見で、そういうデジタル化の前に何か工夫をして分かりやすい表示ができないか等々、大井町は特に。","voiceIndex":301,"id":"exchange-132"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"早めの手配をしておかないと、いざ終わったときにどういう状況になるかというのは心配もあるので、その辺を教えてください。どこからバスが出ていて、どこに行くのかというのが、非常に分かりづらくなってしまうので、これも早めに手配しておいていただいて、デジタル化ということはこれからいろいろあると思いますが、その辺のご検討もしていただきたいと思うので、よろしくお願いします。","respondent":"多並都市開発課長","answer":"もう一つ、先ほどの交通広場の件も、今度新たにつくる予定ですので、その中で、よりよい情報という観点でも改善できる点があるかということは、事業者ともよく協力しながら進めてまいりたいと思うところです。","voiceIndex":304,"id":"exchange-133"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区では何をやれと言えないと思うのですけれども、幅がないからホームを広げろという、現実的なものは難しいと思うのですが、その辺、安全のためにいろいろ交渉していただきたいという、これは要望にさせてもらいます。あの地震の１１秒前だったか、カウントダウンが始まったのですけれども、あれは庁内だけの連絡なのか。何かその辺の連携はできないのかと昨日思ったのですけれども、その辺を教えてください。","respondent":"平原防災課長","answer":"昨日は震度３という情報で流れましたので、昨日は無線のほうには流れてございません。","voiceIndex":306,"id":"exchange-134"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1524#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":108311,"voices":308}},{"id":"r04-20221117-4","meetingId":"r04-c-settlement","date":"2022年11月17日","dateIso":"2022-11-17","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時１４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を149件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、令和３年度品川区一般会計歳入歳出決算","agenda":"○午前１０時００分開会 ただいまより、決算特別委員会を開きます。 それでは、令和３年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"江野下委員","kind":"質問・要望","question":"本日もどうぞよろしくお願いいたします。私からは、３８１ページ、生ごみ処理費についてお伺いいたします。このお金で食べ物を買うとすれば、かなりの食べ物が買えるのではないでしょうか。もちろん給食も例外ではなく、給食の現場でも食品ロスが発生しているとお聞きしますし、食品ロスを起こさないための対策が求められます。これまで子どもたちへの食育は、どのように取り組んでいますでしょうか。","respondent":"矢部教育総合支援センター長","answer":"４年生の社会科につきましては、健康な暮らしとまちづくりの中で、学校の中のごみについて調べ、特に廃棄物、給食の生ごみも含めて考えて、３Ｒも含めた分別や生ごみの処理の仕方などを学習しております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"江野下委員","kind":"質問","question":"１年生から４年生、小学生も食育を学んでいくということで勉強になりました。フードロスは２０１５年に国連で採択されたＳＤＧｓの解決すべき課題の１つにもされており、給食委託会社も取り組んでいくべき課題です。品川区は、これまでに食品委託業者に対してどのような指導を行っていますでしょうか。今後またどのような取組を行いますでしょうか。教えてください。","respondent":"勝亦学務課長","answer":"調理時の工夫ですとか食品ロスを減らす工夫です。調理の段階におきましては、無駄が出ないような適切な技能を持った人を配置し、適切な器具を取り扱うという形で、可能な限り、調理かす等が出ないように取り組むように指導しております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"江野下委員","kind":"質問","question":"品川区では、ごみ減量と地球にやさしい暮らしへの啓発を図るため、家庭用の生ごみ処理機、いわゆる生ごみを堆肥に変えるコンポストの購入助成も行っていますが、学校では、コンポストを使った生ごみの削減、また、コンポストでできた堆肥を、今、学校では、品川カブですとか、いろいろな野菜を育てている学校も多くありますので、花壇などを使った食育などは、今現在、行っているのでしょうか。","respondent":"勝亦学務課長","answer":"生ごみのコンポストですけれども、こちらにつきましては、平成５年頃から導入はしておったのですけれども、機械の劣化ですとか、維持にかなり経費、手間がかかるということで、平成２３年度から生ごみ回収に全て切り替えてあります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"江野下委員","kind":"質問・要望","question":"ただ、区民に対してはこちらの助成も行っていますし、循環型の社会ということで、自分たちが食べた給食が、また残ったものが堆肥になって、それを自分たちが育てる野菜に使って、またそれを給食で食べるという実体験に基づいた食育というものを入れていただけるといいのではないかと個人的には思っているのですけれども、今後このような取組は、ぜひ行っていただきたいと思いますが。","respondent":"勝亦学務課長","answer":"こういった資源循環の取組については、先ほどもございましたように、教育の意義は大変多くありますので、子どもたちに様々な方法で伝えるよう努力していきたいと考えております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"新妻委員","kind":"提案","question":"おはようあります。３６０ページ、教育指導費から、ヤングケアラー支援、重たいかばん問題、３７５ページ、学校ＩＣＴ活用経費、デジタル教科書についてお伺いしてまいります。ヤングケアラー支援についてです。本年９月、文教委員会では、議員提案条例で埼玉県ケアラー支援条例を策定し、ヤングケアラー支援において先進的に取り組んでいる埼玉県を行政視察いたしました。","respondent":"矢部教育総合支援センター長","answer":"お尋ねの研修等ですが、基本的には、子ども家庭支援センター主導のヤングケアラーの研修に、ほとんどの教員が参加いたしまして講習を受けてあります。今お話のありました関係課と連携して、これからも団結して進めていきたいと考えております。","voiceIndex":14,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"ほとんどの教員の方が研修を受けられているということが確認されました。調査はまだ行われていないという現状でよろしいでしょうか。高校生用、中学生用、小学校４年生から６年生用があり、学校教職員へも配付されています。区として、このようなリーフレットの作成や、教育委員会のホームページにヤングケアラーとはとの情報を掲載し、啓発を行っていただきたいと要望します。見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"調査の結果については、所管ではございませんので、詳しくお伝えはできかねます。リーフレットにつきましては、国や東京都の所管からそれぞれ出ているものは学校のほうに周知しています。関係課と連携いたしまして、学校も一緒に子どもたちを守ってまいりたいと考えております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"区議会公明党は、２０１８年、第２回定例会の一般質問で、塚本委員が、同年１１月の決算特別委員会では私が要望、質疑をさせていただきました。当時のこの質疑で文科省の通知発出を受けて品川区の対応を伺いましたが、２０１８年９月６日付で出された通知を翌日の９月７日付で全校に出していただき、さらに、校長連絡会でも再び通知を全校に徹底していただき、丁寧な対応をしていただきました。","respondent":"矢部教育総合支援センター長","answer":"置き勉ですが、これも学年とか個別の対応もありまして、一律にはこちらから申し上げていることはありませんけれども、あらかじめ数日に分けて持ってくるとか、必ず持って帰らなくていいものは置いていくかというところは、学校がそれぞれ判断して学年等で対応しています。","voiceIndex":18,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"デジタル教科書について伺います。私は、２０２１年第１回定例会一般質問で、デジタル教科書の推進と、障害のある児童生徒に対してのデジタル教科書の活用を求めました。その積み上げを行って、障害特性に応じたメリット・デメリットをまとめ、今後のタブレットやデジタル教科書の使用にいかしていただきたいと思いますが、見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"アプリもそのお子さんに合わせて入れられるように、効果的だと考えられるアプリを入れておりますので、大変好評です。今後とも特別支援教育につきましては力を入れて推進してまいりたいと考えております。","voiceIndex":20,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"特にお子さん、児童生徒ご本人、そしてまた保護者の方にも、活用をすることによって、家庭での勉強とか、どういうことに変わっていったのか、そのようなこともお聞きいただければと思います。教科書のデジタル化で荷物を減らすことにつなげていただきたいと考えています。国の２０２４年度の本格導入を前に、副教材などのデジタル教科書の導入のお考えをお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"これは１０月から行いましたので、この動向もきちんとお子さんたちの様子を見ながら、教員の使い勝手も見ながら判断してまいりたいと考えています。","voiceIndex":22,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"教職員の使い方も含めて、タブレット、デジタル教科書の活用を検証していかないといけないと思いますが、荷物を減らすという１点での、またそういう視点も入れていただきながら、品川区が市民科で早く区独自でのデジタル教科書、推進をしていただいている実績がありますので、引き続き、デジタル教科書の推進、導入について検討を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"３６３ページの生徒指導対策等経費より、区立中学校、義務教育学校の校則について伺いたいと思います。この間、中学校の理不尽な校則について、生徒を主役に見直しを求めてきました。全ての区立中学校および義務教育学校において、ツーブロック禁止の規定がなくなったのか、いつからか、現状においてツーブロック禁止の校則はまだ残っているのか、現状を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"お尋ねのツーブロックの禁止という表現はございません。１５校ございません。これは今年度、令和４年度から全校でなくなっております。","voiceIndex":26,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"先ほどの答弁で、今年の４月から１５校全てでツーブロック禁止の校則はないというご説明で、歓迎したいと思います。併せて、教育活動の現場で起きていることですから、校則の見直しも教育活動の一環として取り組まれることが大事だと私は思います。どのような経過でツーブロック禁止の校則が廃止されたのか伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"生徒会のほうで案を上げたものを、もう一度、生活保健部という保健の部会で先生たちが検討して、さらに企画という委員会、これは管理職も入った企画委員会だと思いますけれども、そちらのほうで提案して議論、最終的に職員連絡会で周知というような。","voiceIndex":28,"id":"exchange-012"},{"speaker":"中塚委員","kind":"質問・要望","question":"生徒が生徒の意見を集めて、生徒同士も話し合って、また学校と協議をしていって校則を変えていく。変わった校則を自分たちで守っていく。生徒に少し話を聞いたら、「校則って変えることができるんだ。ぜひ今後も進めていただきたいと思います。女子生徒からは、男子は変わったが、女子が変わらないとの意見も伺っております。校則で髪を肩までおろしたまま禁止は必要ないと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"制服等についても積極的に変えているところは、男女の別なく進めておりますので、かなりお子さんたちの声は聞いていると考えております。","voiceIndex":30,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"生徒同士が話し合っていって、先生も含めて、地域も含めて、いろいろ校則は見直しが必要だというご指摘だと思います。センター長は、肩まで長い髪をおろしたまま禁止、その場合は、１つまたは２つに結ぶという校則について、昨年の決算特別委員会でこう説明したのです。いかがでしょうか。いわゆる連帯責任で一律に校則で指導するというのはやめるべきだと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"そういう意味では、今回のこともそうですけれども、今日のあした変えられるものではないものもあるので、ぜひ時間をかけて学校を応援していただきたいと考えております。","voiceIndex":32,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ生徒の気持ちや意見を酌み取って、時間をかけて見直しを一層進めていただきたいと思います。改めて生徒の意見を大事にして校則の見直しを求めていきたいと思います。最後に、幅広い意見を酌み上げる意味でも、ぜひ校則を学校のホームページで公開することを積極的に進めていただきたいと思います。そうした姿勢をとることが求められていると思いますけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"この夏に出されました生徒指導提要の素案の中にも例示はされておりますので、これは固まり次第、またこちらも検討していきたいと思います。意義ですとか、方法というところは、区のほうでもしっかり論議して進めてまいりたいと考えています。","voiceIndex":34,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が一番納得できなかったのは、朝、ドライヤー禁止。ただ、私、寝癖がひどいもので、朝、水をジャバジャバかけて寝癖を落として、びしょびしょのまま学校へ行くわけにいかないですから、やはりドライヤーを使うのです。ぜひ校則を学校のホームページで公開して、生徒の意見、地域の意見、保護者の意見、様々耳を傾けていただいて、理不尽な校則の見直しを強く求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"私からは、３６３ページの生徒指導対策費、クラブ・部活動指導費について、３６７ページの特色ある教育活動費のドリームジョブについて、３７７ページの学校環境整備事業について伺います。そこで初めに、３６３ページの生徒指導対策費について、教職員への負担について伺います。そこで区として、こうした教職員の時間外労働の負担軽減について、どういった取組をされているのでしょうか。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"働き方改革についてのご指摘をいただいたところなのですが、品川区としましては、教員の負担を軽減するという目的で、スクール・サポート・スタッフであったりとか、外部指導員、部活動指導員の配置など、様々な教育活動の場面で。生徒指導対策費のクラブ・部活動指導費についてです。こちらは、特に休日等の部活動に、時間外勤務として１回１,０００円の支給をしている費用です。","voiceIndex":38,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひそうしたところも含めて、教職員への負担を軽減していただければと思います。１回１,０００円というよりも、時給換算していただければありがたいなというふうに思っておりますので、これは要望で終わります。３６７ページの特色ある教育活動経費のしながわドリームジョブについて伺います。その中に、教職員になりたいという方の声がありましたでしょうか。併せて伺います。","respondent":"中谷指導課長","answer":"ドリームジョブにつきましては、品川区で平成２７年度から開始いたしました児童生徒が様々な分野の職業に就いている方の話を聞きまして、自身の職業観であったり、勤労観を考えて実現させていくための取組というところになります。","voiceIndex":41,"id":"exchange-018"},{"speaker":"松永委員","kind":"意見","question":"何とか教員も上位のほうにランクインできるように取り組んでいただければと思います。そこで、その夢の実現に向けて必ず必要になってくるのが学力です。学力定着度調査についてですが、どういった形で推移しているのか、その結果を受けて、どう対策をとられているのかお知らせください。","respondent":"中谷指導課長","answer":"評価を実施しておるのですけれども、その結果については、４分位の分析を行いまして、Ａ層からＢ、Ｃ、Ｄと４段階になるのですが、各層でどのぐらいの数があるかというところを見て、指導者としての授業の組立てをどうやって行っていくかということを考え。","voiceIndex":43,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"最後に、３７７ページの学校環境整備費の事業について、飼育小屋について伺います。現在、品川区内には、飼育小屋を設置されているところが幾つぐらいありますでしょうか。ぜひそうしたところも含めて、この飼育小屋の設置状況、そして今後、品川区としては、飼育小屋の進め方、どういうふうに考えているのかお知らせください。","respondent":"森学校施設担当課長","answer":"２点ご質問がございました。飼育小屋の今の現状ですけれども、現在、２８校に飼育小屋が設置されてあります。中学校に設置はございません。義務教育学校には１校設置されてあります。続きまして、今後はどういうふうな整備をされていくか。","voiceIndex":45,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問・要望","question":"動物に愛情を持って、そういった感情を持てる子どもたちに育てていきたいので、ぜひこの飼育小屋、必ず設置していただければと要望で終わります。これは、一応、保護者からの要望だったので、ぜひお応えしていっていただければと思います。","respondent":"森学校施設担当課長","answer":"トイレ用擬音装置のこと……。","voiceIndex":47,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"私は、３６０ページ、教育指導費についてお聞きします。採用倍率３倍を切ると教員の質が低下するなどと、教育委員会の採用担当、また一部の研究者やマスコミは言っていますが、品川区教育委員会の見解をお聞かせください。どうして教員の志望者が少ないのですか。人気がないのですか。これも教えてください。","respondent":"中谷指導課長","answer":"一方で、今現在、品川区の固有教員の採用選考ということも、かねてから継続してやっておるところなのですけれども、今年度、次年度の採用ということで選考いたしまして、４名という少ない枠に対してですけれども、今回、２０名のご応募がありました。","voiceIndex":50,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"品川区は品川区固有教員、これはすばらしい施策だと思うので、これは品川区独自で教員を採用しようと、区の予算でやっております。毎年、百何十名、２００名近くが異動したりしていますが、この教員を品川区で、都から来る教員を選べればいいのですが、実際は選ぶことができない。今回、何人が転勤しますよと、３年たつと転勤希望が出せます。これに対してどのようなご見解をお持ちですか。教えてください。","respondent":"中谷指導課長","answer":"一方で、東京都の教職員、こちらのほうが人数としても多い状況にはなっておりますが、様々な方がいらっしゃるということも現状として認識しております。","voiceIndex":52,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"その繰り返し繰り返しでやって、育て上げられないではないですか。実際これでいいのですか。こういう方も現にいるではないですか。子どもたちをこれから育て上げていくのに、こういう方たちが品川区に来て、その方たちがいるということは、ほかの教員に負荷がかかって、それが長時間労働にもつながるわけではないですか。実際こうではないですか。これだけ忙しいではないですか。ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"これによって、単なる副校長の時間、多忙感が減ったというだけではなく、副校長の本来の仕事である教職員への人材育成、指導というところに時間が割けるというか、そこに時間を充てて、学校の人材育成が充実できるようにということを狙って、今。","voiceIndex":54,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"一生懸命、ほかから来たら、その方たちが、ほかの先生に刺激を与えて、でも、そのような余裕、あるのですか。転職したり、ほかの用事があったりしておりますが、これで本当に公教育は大丈夫なのでしょうか。そういう方たちが、本来ならば、公立小学校から公立中学校に、私はできれば１００％行ってほしいですが、以前は２０何％の方が別の私立等の学校に行っていました。ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"公立がよいかとか、私立がよいか、はたまたほかの選択肢ということもありますが、学校選びというのは、それぞれの特色を見た上で、お子さんであったり、保護者の皆様が、ご自身の学びにどう何をいかしていきたいかというところで選択をする機会があるという意味で。","voiceIndex":56,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"毎年大体そういうお話を私はお聞きします。私は、本当にお試しでもいいから、品川区は、品川区に１回教員を預けてくれ。子どもたちだって、先生と長くいる、私立はそうですね、１０年、２０年、一緒に顔を合わせる。この人たち、研修をきちんと受けているのですか。ですけれども、やはり私は思っていただきたい。ぜひ今後も、教育長には特に早く品川区固有の教員で品川区を固めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-026"},{"speaker":"吉田委員","kind":"質問・要望","question":"私からは、３７７ページ、学校環境整備事業、３６３ページ、生徒指導対策等経費、そのほか、伊藤幼稚園の問題とか、英語スピーキングテストについて伺います。最初に、３７７ページの学校環境整備事業についてです。今年３月の予算特別委員会でも、この項目で羽田新飛行ルートについて伺っております。そのときのご答弁は、子どもたちの声を聞けるか研究したいとのことでした。その研究状況について伺います。","respondent":"勝亦学務課長","answer":"子どもの声を聞くべきとのご要望に対しまして、研究をしていきたいというふうにご答弁させていただいたと記憶しています。こちらにつきましては、その必要性ですとか、学校、教育委員会の組織としての役割を考慮した上で、現在、聞き取り等は行ってございません。","voiceIndex":60,"id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"なぜなら、生活者ネットワークに、大井町から近い区立小学校に通う小学３年生からお手紙をいただきました。子どもたちの声を聞く具体的な方法が必要だと思うのですが、いかがでしょうか。私たちにお手紙が来たのが、要は、学校が聞いてくれないから、聞いてくれそうなところを選んで手紙を出してきたということであれば、本当に情けないなというふうに思いますが、見解を伺います。","respondent":"勝亦学務課長","answer":"羽田の新飛行経路への相談窓口につきましては、しかるべき組織があると考えています。そういった部分につきまして、学校がまずお声を聞くという役割にある組織だとは考えてございません。","voiceIndex":62,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ学校でもそういう機会を持っていただきたいというふうに思います。次に、区立幼稚園の閉園問題です。当時の学務課長の答弁と、教育委員会の権限に属する事務の補助執行規則にある６項目を見ても、やはり今回の事案は、保育課の権限は調査までで、方針決定は教育委員会が所管すべきだったのではないかと考えますが、改めて見解を伺います。このときの発言をどう受け止められたのか、改めて伺います。","respondent":"勝亦学務課長","answer":"保育園の補助執行の範囲を超えているというお話の部分ですけれども、こちらにつきましては、公立、私立の幼稚園、保育園の入園状況などを区長部局のほうで横断的に調査、分析を行いまして、就学前児の保護者のニーズ調査等を行いまして、子育て支援ですとか。","voiceIndex":64,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問・要望","question":"これについて、あとで見解を伺います。それから、英語のスピーキングテストについて伺います。もし保護者が個人情報の流出を懸念して同意をしなかったら、その子どもたちのテストは、どういう扱いになるのでしょうか。受験する権利を盾にした同意のとり方は問題があると考えますが、見解を伺います。そういう了解のとり方で個人情報流出の懸念への解決にはつながらないと考えますが、見解を伺います。","respondent":"勝亦学務課長、中谷指導課長","answer":"区長部局との補助執行のすみ分けの部分ですけれども、現在も連携、協力をして事務を行っています。今後とも深く連携、協力しながら、就学前教育をしっかり進めていくというふうに考えてあります。保護者の同意についてということですけれども、基本として、学校から、進路説明会でしたり、保護者会またはお便りなどで、生徒、保護者へのテストの実施の詳細であったり、インターネットでの申込みの方法をお伝えしているところです。","voiceIndex":66,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"送り先がベネッセだということについて、どうなのだろうということはメディアでもいろいろ問題になっておりますので、その辺についての見解も伺いたいと思います。でも、やはり個人情報の流出というのは、事件というか、事故として起きるわけですから、その辺についての懸念をどうやって払拭するのか。品川区内の学校ではそれはないのか、確認をさせていただきたいと思います。区教委の見解を伺います。","respondent":"中谷指導課長","answer":"テストの評価者についてのご質問もございましたけれども、こちらにつきましても、採点者は、大学の学位を持っているほかに、大学院等の機関で英語を母語としない生徒に対して英語教授法のプログラムをきちんと修了している方に与えていく証明書というのがあるのですが。","voiceIndex":69,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"生徒指導について伺います。生徒指導提要が約１２年ぶりに改訂されます。新しい提要では、子どもの権利条約に基づき、先の国会で成立したこども基本法にもある児童生徒に対するいかなる差別もしない、児童生徒にとって最もよいことを大事にすることなどが示されていますが、それについて子どもたちが知る機会を保障していただきたいのですが、いかがでしょうか。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"英語のスピーキングテストの件で、私立の学校、国立の学校の生徒の方が受けないのかというお話でしたけれども、公立の学校と同様に、東京都教育委員会は受験のご案内をしているということをお伝えします。子どもの権利につきましては、これまでも権利条約につきましては、市民科、社会科等において指導の機会があります。生活指導主任会におきましても、これまでの生徒指導提要、また今の素案についても周知しています。","voiceIndex":71,"id":"exchange-032"},{"speaker":"せらく委員","kind":"質問","question":"３７４ページの学校管理費から学校校舎設備、タブレットの活用、３５８ページ、学務費から、学用品、学校選択制について質問します。学校のトイレ設備について、洋式化を進めていただいているとは思いますが、会議録を拝見すると、令和２年度の決算特別委員会で、洋式化率は、令和２年度は７７.２％、令和３年度の見込みは８０.５％ということでした。令和３年度の実績を伺います。","respondent":"森学校施設担当課長","answer":"トイレの洋式化率ですけれども、令和３年度で８１.３％になります。今年度が過ぎますと、８３.５％になる予定です。","voiceIndex":75,"id":"exchange-033"},{"speaker":"せらく委員","kind":"質問・要望","question":"見込みよりも多いということで、声を聞いていただけたことと思います。トラウマや不登校の原因になる前に、全てのトイレを洋式化してほしいと、息子と同じ学校の保護者から強く要望をいただいております。次に、タブレットの活用について質問いたします。授業でのタブレットの活用率はどれくらいでしょうか。学年ごとに変化があれば、それも教えていただけたらと思います。","respondent":"勝亦学務課長","answer":"タブレットの使用率ですけれども、多くの学年におきまして、ほとんどの授業で使ってあります。８割から９割程度、学年による大きな差異はございません。","voiceIndex":77,"id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"重たいかばんについて、先ほど、新妻委員もご発言されておられましたが、重複するところもあるかと思いますが、私もこれをよくしていきたいという思いで質問します。現場での対応となるため、まだまだばらつきがありそうです。再度、各学校、先生の皆様で、置き勉や荷物軽減に問題意識を持って取り組んでいただけるような周知をしていただくようお願いしたいと思いますが、見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"ご家庭の考え方もあるし、また、各ご相談で、別なバッグを要請される場合もありますので、個別に子どもの健康を第一に考えていきたいと考えています。","voiceIndex":79,"id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"各学校へ入学説明会で配布する資料等に、「ランドセル等（両肩で背負えるかばんも可能）」と表記を統一するとともに、在校生についても、個別の相談でリュックなどのかばんに代用することは可能というご答弁をいただきましたが、ランドセル以外の選択が可能となるように、周知を徹底していただきたく要望いたしますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"荷物が重いという実態があるということは学校も承知していますので、表現については、これからも周知しながら、学校のほうも弾力的に対応できるように働きかけていきたいと考えています。","voiceIndex":83,"id":"exchange-036"},{"speaker":"せらく委員","kind":"提案","question":"そういった具体例も持って、品川区としてもリュックなど両肩で背負えるかばんの提案も併せてしていただきたいと思います。こういった記載の変更はまだ間に合うと思いますので、令和５年度の入学案内に、多くの学校でそのようなことを書かれていることを願って、次の質問に移らせていただきます。そして品川区は、学校の選択制を導入していますが、令和５年度入学から選択除外校が出ていると確認しました。","respondent":"勝亦学務課長","answer":"昨年度は２０％程度のご希望をいただいております。５人に１人の方が、そういった選択肢を望まれているという現状もありますので、多様な選択肢を示すという意味でも学校選択制は継続していきたいと考えています。","voiceIndex":85,"id":"exchange-037"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、３６３ページ、区教員経費、教職員人材育成経費、３６５ページ、教育総合支援センター運営費、３６７ページ、品川英語力向上推進プラン、３６９ページ、マイスクール運営費、３７５ページ、教材教具等経費についてお伺いいたします。そこで、子どもたちと保護者がキャリア教育、子どもの発達を学ぶ機会をつくっていただきたいと要望いたしますが、区教委のご見解をお聞かせください。","respondent":"矢部教育総合支援センター長、中谷指導課長、宮尾庶務課長","answer":"不登校のキャリアにつきましても、ファミリークラブ品川というものを、１１月に入りまして、夕方６時から３回につきまして行いましたが、そこの中では。品川の先生方におかれましても、文部科学省が主催する、まず中央研修というものがございまして。学校の監査につきましては、毎年一定程度、定期監査で監査をいただいておりまして、その結果を受けて是正し、再発防止に努め。","voiceIndex":88,"id":"exchange-038"},{"speaker":"西村委員","kind":"質問","question":"３６９ページ、不登校児童・生徒支援事業、３６５ページ、習熟度別学習推進経費から、自由進度学習について伺ってまいります。不登校支援については、この間、様々視察や不登校児童、保護者、先生にもお話を伺いまして、複雑化していることを実感しています。子どもにアプローチできるのは、大人、そして子どもだというお話も伺っています。","respondent":"矢部教育総合支援センター長","answer":"その１人のお子さんの中にもバイオリズムや調子もありまして、今日はすごく調子がよくて取り組めるけれども、あしたはもう起きられないとか、午後になってからというようなところもあります。","voiceIndex":93,"id":"exchange-039"},{"speaker":"西村委員","kind":"意見","question":"センター長のおっしゃるとおり、お子さんのどこにスイッチがあるのかなというのは私も思います。いろいろな大人が対応していただいていて、学習形態も世の中には様々あり、中学を卒業した後の進路をどうするのか、こちらも数ある選択肢の中から選び取ることが大変な状況ではないかと思っています。不登校児童の中学校卒業後の進路先の現状と課題についてお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"マイスクールから、その上、進路につきましては、今、少しご紹介をさせていただいたところは、もちろん都立の高等学校、あと、通信制、エンカレッジスクール、サポート校などに行くお子さんが多いということで、今回もファミリークラブ品川の中におきまして。","voiceIndex":95,"id":"exchange-040"},{"speaker":"西村委員","kind":"質問・要望","question":"自民党からも、教員ではなく、スクールカウンセラー等によるＬＩＮＥ、メールなど、ＳＮＳ相談の充実を要望しております。一方で、保護者を対象にした子育て勉強会の開催ですとか、子ども、保護者双方を支援するために、スクールカウンセラー等によるＬＩＮＥ、メールのＳＮＳ相談などの充実を要望いたします。今していただいていることもあると思いますので、併せてお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"学校ではないほうがいいとか、ときどきスクールカウンセラーとの話が一致しなくて、ほかのということであれば、教育総合支援センターのほうにもご相談いただければ、順次案内してまいりたいと思いますし、学校の管理職からも相談があれば。","voiceIndex":97,"id":"exchange-041"},{"speaker":"西村委員","kind":"質問・要望","question":"以前にも私、これを質問させていただいたかと思うのですが、スクールカウンセラーではない方にも相談ができる、先生にももちろんできます、教育総合支援センターにもできるということがなかなか保護者の方は分かっていない方が多いというふうに思っておりまして、本当に子どもたちのためにオール品川で皆さん取り組んでいただいているのだということを、もっと伝えていけるといいなというふうに思っています。","respondent":"矢部教育総合支援センター長","answer":"今の個別に対応する件につきまして、幾つか事例を挙げします。１点目は、算数、数学、英語では、本区では習熟度別指導を実施しています。","voiceIndex":99,"id":"exchange-042"},{"speaker":"西村委員","kind":"意見","question":"確かに私が子どもの頃と比べますと、先生が授業の中でたくさん歩いてくださっていたり、生徒同士の話合いとか教え合いの場が増えたなというのは感じております。最近、令和の日本型学校教育としまして自由進度学習が取り上げられることがあるそうです。本区の子どもたちに向けて、自己有用感を育ませるために大切にしていることがあれば、お聞かせください。","respondent":"矢部教育総合支援センター長","answer":"特別支援のお子さんにつきましても、小さなお子さんにつきましても、読み書きの時間を短い時間にして、別の活動に気持ちを切り替えて変化などをつけて対応しています。","voiceIndex":101,"id":"exchange-043"},{"speaker":"西村委員","kind":"質問","question":"正にその振り返り学習についてこれからお伺いしたかったのですけれども、今の１０代の自殺ですとか不登校、いじめなど、子どもたちを取り巻く様々な課題が、成長実感と自己有用感にあるのではないかと最近ますます感じています。家庭教育を考えますと、日々忙しい親が宿題に関わる機会が減っていると感じていますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"時代に合わせて、そのような状況も踏まえて、担任、教員は、宿題の出し方等も検討しているところです。","voiceIndex":103,"id":"exchange-044"},{"speaker":"西村委員","kind":"質問","question":"確かに自分で録画をしてタブレットを活用して宿題を提出している姿を見ております。これまでの生活を振り返りまして、自分の成長や変化について自分自身で考えたり、友達に教えてもらったり、認めてもらったりして、気づかなかった自分の成長を実感できるようにする学習が、自己の成長を振り返る学習だと考えています。いま一度ご答弁をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"全員が学級目標を考えたときにも、その目標について今日のあなたの活動はどうだったかという場面もあります。そういうふうにいろいろなところで振り返り、長いスパンであったり、今日の今日という短いスパンであったりという機会は大切にしてまいりたいと考えています。","voiceIndex":105,"id":"exchange-045"},{"speaker":"西村委員","kind":"質問","question":"先ほどから宿題についてテーマにさせていただいているのですが、家庭でそれを継続していくことの大変さと大切さを実感しておりますので、改めてこの質問をしています。なかなか家庭の学習と学校の学習を結んでいく、つないでいくということが、親も分かりませんし、先生と交流をしながら教えていただけたらいいなと思うのですが、いま一度ご答弁をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"この３年間、コロナ禍もありまして、特に保護者との連携が学校もとりづらいところはあると思います。遠慮なく、電話もありますし、特に担任には相談していただきまして、お子さんの具体的な褒め方ですとか、認め方、あとは支援についてご相談いただきたいと思っています。","voiceIndex":107,"id":"exchange-046"},{"speaker":"つる委員","kind":"提案","question":"お願いします。その上で、食育の観点とか、また、今申し上げたような栄養士が現場で子どもたちとどう関わっていただいているかという形になるわけであって、そこについては、国政においても、既に公明党の提案で全国のアンケートをさせていただいて、完全給食の実施だとか、その辺も確認させていただいたり、また、当時４,４００億円、全国で一律に国で給食を見た場合かかる。","respondent":"宮尾庶務課長","answer":"その支援メニューの中に、基本的には１つ１つの事業に対して、それに対する経費をご支援するという形でやっております関係で、今、委員からお話しのあったような、通信環境に関する支援メニューというのは、現時点ではそろえていないというのが現状です。","voiceIndex":111,"id":"exchange-047"},{"speaker":"つる委員","kind":"質問・要望","question":"そういう意味では、このネット環境、Ｗｉ－Ｆｉとか、端末使用料とか、そういったところについても、例えば、ある地方では、まずアンケートをとっていただいて、いかがですか、必要ですかとかというようなこともやった上で支援に入れているということもありますので、段階を踏んでいただくこともいいかと思いますので、ぜひネット環境については、かつては渡部委員長が、もう２０年近く前、十五、六年前に。","respondent":"勝亦学務課長","answer":"新聞につきましても、小学校２紙、それから中学校は３紙ということで計画の中で定められておりますので、こちらを達成できるように積極的に検討していきたいと考えております。","voiceIndex":113,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"これはアクティブ・ラーニングで子どもたちにいろいろなことを事象を見せて、子どもたちで議論させて答えを１つ、２つ、３つ、４つと出させていくという、正にアクティブ・ラーニングの中にあって、教師の立ち位置がどういう形で教育の現場に臨んでいるのかという１つのエピソードかと思うのですが、このアクティブ・ラーニングをいろいろな教科で取り組んでいるとは思うのですけれども。","respondent":"矢部教育総合支援センター長","answer":"ただ、アクティブ・ラーニングとは、ここに来てということで言葉は出てきましたけれども、これまでも子どもたちの主体性をもって深く考えさせるというような活動は取り組んでおりまして、教師が一方的な授業で指導するような形ではなくて。","voiceIndex":115,"id":"exchange-049"},{"speaker":"つる委員","kind":"意見","question":"いろいろなことを意見も含めてお伝えさせていただきました。引き続き、子どもたちが本当に輝く笑顔で、この品川区を、いろいろな形で活躍できる人材をつくっていただけることをお願いをして、以上で終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":117,"id":"exchange-050"},{"speaker":"おくの委員","kind":"質問・要望","question":"私からは、３６７ページ、品川英語力向上推進プランに関わって、英語スピーキングテストについて質問いたします。品川区は、中学校英語スピーキングテスト（ＥＳＡＴ－Ｊ）のプレテストを２０１９年度から実施していると文教委員会で報告がありました。私は中止を求める立場から幾つか質問したいと思います。それから、７９点から６５点を取った生徒は、最終的には１６点に換算される。この点をまず伺います。","respondent":"中谷指導課長","answer":"お話しいただきましたとおり、６段階で表すということで、これらの観点を総括的に評価していくためには、このような評定が必要ということを東京都が判断したというところになります。","voiceIndex":119,"id":"exchange-051"},{"speaker":"おくの委員","kind":"質問","question":"東京都が判断したということですけれども、結局、最初の段階で１点の差であったものが４点に差が拡大してしまう。５教科というのは、そもそもどれも大切な科目で、同様に比重をかけて評価すべきはずなのに、英語だけこういうふうに重く評価されるというのは、やはりおかしいのではないかというふうに思うのですけれども、この点、いかがでしょうか。","respondent":"中谷指導課長","answer":"先ほどからご指摘いただいている４点差というところと、この数値化をして加算するというところですけれども、まず、東京都教育委員会の方針としましては、小学校、中学校、高等学校における一貫した英語教育の推進を強く求めています。","voiceIndex":121,"id":"exchange-052"},{"speaker":"おくの委員","kind":"質問","question":"英語の時間の中でそういう教育をやっていくことは大事だとは思います。ですから、英語だけ倍近い比重を置くような評価の仕方をするというのは、やはり私としてはおかしいと思わざるを得ません。次の質問にいきたいと思います。こういうふうに他人の点数で自分の点数が決まるなど、自分の実力で合否が決まるはずの入試では考えられないのではないでしょうか。この点、伺います。","respondent":"中谷指導課長","answer":"不受験者の扱いということですけれども、まず、１１月２７日に試験が予定されているところですが、ここで例えばインフルエンザであったりとか、新型コロナウイルス感染症など、感染をしてしまった場合ということも考えられると思います。","voiceIndex":123,"id":"exchange-053"},{"speaker":"おくの委員","kind":"質問","question":"そういう意味で、重大な問題ではないでしょうか。この点、伺います。","respondent":"中谷指導課長","answer":"今ご指摘いただいた国立であったりとか、私立学校の生徒が受けられないのではないかというところですけれども、受けられますということをお伝えさせていただければと思います。","voiceIndex":125,"id":"exchange-054"},{"speaker":"小芝委員","kind":"質問・要望","question":"お願いします。私からは、３６３ページ、品川区固有教員について伺います。そこで、まずお聞きしますが、この固有教員、これが品川区で誕生しましたいきさつについて教えていただきたいのと、また、固有教員の学校現場における役割といったものを教えていただけますでしょうか。","respondent":"中谷指導課長","answer":"これまで教育施策を推進していくために英語科や理数教育などの教科の免許を取得している方や、市民科を進めていくために小学校全科の免許を取得している方、また、オリンピック・パラリンピック教育を進めるために保健体育の免許を取得している方、現在は。","voiceIndex":128,"id":"exchange-055"},{"speaker":"小芝委員","kind":"質問・要望","question":"これまでどういった方が固有教員に採用されてきたのか教えていただきたいことと、また、もしできれば、可能な範囲で何名が新卒で採用されたのか、また、何名が経験者として採用されたのか、その内訳について分かれば教えていただきたいのと、またもう１点は、先ほど答弁があったかもしれませんが、直近の倍率の推移についても教えていただければと思います。","respondent":"中谷指導課長","answer":"倍率ですが、令和２年度にはやっておりませんでしたが、新型コロナウイルス感染症対策が明けまして、令和３年度、令和４年度と続いて実施しているところでして、先ほど申し上げた、今年度、倍率が５倍ということで、昨年度よりも微増という形で選考状況を受け付けている状況です。","voiceIndex":130,"id":"exchange-056"},{"speaker":"小芝委員","kind":"質問・要望","question":"倍率のほうも微増といいますか、上がってきているということを伺いました。これまで志のある方を発掘していくには大変な労力がかかってきたとは思います。この免許を取得するに当たっては、都内だと、国立は２校で、私立の大学が３４校と伺っておりますが、この大学への採用に向けましたアプローチだとか、また、既存の教職員の方へのアプローチに向けた取組について、分かれば教えていただきたいと思います。","respondent":"中谷指導課長","answer":"そのような状況です。","voiceIndex":132,"id":"exchange-057"},{"speaker":"小芝委員","kind":"質問・要望","question":"大学での訪問型の説明会なのかどうか、ちょっとはっきり分からないですけれども、そういったものはとてもいい取組であると思います。一方で、時代の流れはとても早いです。その先導役となり得る固有教員について、今後も引き続き採用を続けていただきたく、また、時代のニーズに即した新たな教育にも、固有教員を柱にして果敢に取り組んでいただきたいと思いますが、ご見解をお伺いいたします。","respondent":"中谷指導課長","answer":"何よりも、今いる２６人の教員をしっかりとキャリアアップをさせること、そしてまた、現在、６級職の一番最高職である統括副校長の成り手というところもしっかり育て、そして採用できるような仕組みを整えていきたいと考えていますので。","voiceIndex":134,"id":"exchange-058"},{"speaker":"小芝委員","kind":"質問・要望","question":"先ほどご答弁いただいたとおり、５倍の大変狭い門であると私も思いますが、今後も採用の継続として、発展性のある採用をぜひ求めていきたいと思いまして、私からの質問は終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-059"},{"speaker":"せお委員","kind":"質問","question":"よろしくお願いします。私からは、３６９ページ、特別支援教育費、３５９ページ、就学事務費についてお聞きします。最初は特別支援教育費です。一方、８月には、国連がインクルーシブ教育の権利を保障すべきと日本へ勧告を出しました。質問ですが、区立学校では、国の通知にありましたように、支援級の児童生徒が通常級で半分以上過ごしている状況が、令和３年度にあったかどうか教えてください。","respondent":"矢部教育総合支援センター長","answer":"これは大切なところなのですが、教育総合支援センターとしては、介助員とか学習支援員、今、始めています発達障害教育支援員、ここも取り組んでおりますけれども、そのような人材配置、質の確保も含めて、その辺りで支援してまいりたいというふうに考えております。","voiceIndex":138,"id":"exchange-060"},{"speaker":"せお委員","kind":"質問・要望","question":"１つずつ進めていただきたいと思います。よろしくお願いします。学校選択制のほうに移ります。主に指定校変更についてお聞きします。例えば、このようなご家族がいます。あえて双子と言いますが、双子の１人のほうが障害があって支援級がベストだと考えています。もう１人は障害がないので通常学級にと考えています。はこのご家族の場合、現在はどのような対応になるのか教えてください。","respondent":"勝亦学務課長","answer":"ただ、今ございましたように、支援級のほうは特に選択の範囲を設定してございませんが、学校選択におきましては、通常の学級につきましては、自分の学区、もしくはそこの隣接する学校から選んでいただくという仕組みになってあります。","voiceIndex":140,"id":"exchange-061"},{"speaker":"せお委員","kind":"質問・要望","question":"基準の５番目は、「その他教育委員会が特に必要と認めた場合」とあるのですが、曖昧ですし、保護者の立場からすると、認められるかどうか不安な中、保護者から申立てをしなければいけないというハードルが高いものです。各区、本当に回答は様々です。品川区はありません。そして、指定校変更の基準の見直しについて、調査などから始めていただきたいと思いますが、見解をお聞かせください。","respondent":"勝亦学務課長","answer":"こういった指定校変更に関しましては、特殊なケースもありますので、一律にお認めする、お認めしないという形ではなく、こういった特に障害等ある場合は、学務課、それから教育総合支援センターと連携しながら、お子様の状態ですとか、ご家庭の状態、そういった学校の状況。","voiceIndex":142,"id":"exchange-062"},{"speaker":"せお委員","kind":"質問・要望","question":"基準の見直しについてお答えいただけなかったのですけれども、配慮が必要なお子さんをお持ちのご家族のことを考えて、保護者の負担なども考えて、抽せんもなしで本当は入学させていただきたいのですけれども、品川区の状況に合わせてご検討をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-063"},{"speaker":"湯澤委員","kind":"質問","question":"私からは、３６５ページ、市民科・各教科充実経費についてお伺いいたします。以前、教育総合支援センター長に道徳との違いということについて質問させていただいたところ、道徳の課題である実際の行動に移すというところについても指導を行っているという点であるとご説明を受けました。","respondent":"矢部教育総合支援センター長","answer":"これは全都的に道徳授業地区公開講座というものは都の取組で進めておりまして、本区につきましては、市民科授業地区公開講座というふうになってあります。","voiceIndex":146,"id":"exchange-064"},{"speaker":"湯澤委員","kind":"質問","question":"私は、子どもが小学校に通っていることをきっかけに、去年、今年と２回参観をさせていただきました。実際に、同じクラスの保護者とお話しする機会があったのですけれども、その方に市民科での話をしたら、そのような内容なのですかとびっくりされておりました。授業をインターネット配信などすることも、今後、ご検討いただければと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"そのような中で、ＩＣＴも活用しながら周知に努めてまいりたいと思います。","voiceIndex":148,"id":"exchange-065"},{"speaker":"湯澤委員","kind":"質問・要望","question":"市民科では、人を思いやる心、命の大切さを学ぶ授業もあります。ある調査では、若者の３割は本気で自殺を考えたことがあるとしております。こういった授業は、動物に触れたり、そして飼育をしたりといった体験学習とともに、一部の学校、一部の生徒にとどまることなく、全ての児童生徒に対して等しく機会をつくっていただければと要望いたしますが、ご見解をお知らせください。","respondent":"矢部教育総合支援センター長","answer":"ただ、実態としましては、コロナ禍につきましては、マスクも含め、罹患したお子さんへの対応も含め、保護者の対応も含め、かなり思いやりを持って接するということが、コロナ禍において進んで、全国のいじめのほうも、令和２年は特に下がったという状況があります。","voiceIndex":150,"id":"exchange-066"},{"speaker":"湯澤委員","kind":"質問・要望","question":"最後に、デジタル化が進む中で、デジタルデバイスを活用しながら心と心を通わせるようなことができる取組が今後必要になってくるかと思いますけれども、そちらは区教委としてビジョンがあれば、お知らせいただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"これは様々な場面で活用できると思うのですが、やはり専門家の先生ですとか、本当に子どもたちに大変効果的な教育効果のあるお話をしてくださる方に遠隔からお話をいただくというようなことや、また今、不登校のお子さんなどは、欠席していますけれども。","voiceIndex":152,"id":"exchange-067"},{"speaker":"くにば委員","kind":"質問","question":"区内３校で、全く違った切り口、方針で、ＩＣＴを活用した重点的な研究がなされていること、大変興味深くお聞きしました。併せまして、ＡＩ型教材「Ｑｕｂｅｎａ」についてです。こちらのＱｕｂｅｎａについては、私が令和２年度予算特別委員会で質問させていただきました。現在、Ｑｕｂｅｎａのホームページを見ると、実績として既に全国１７０以上の自治体、２,３００校以上へ導入されているとのことです。","respondent":"中谷指導課長","answer":"ですので、全校展開につきましては、こういった既に活用している学校、昨年度で１７校活用しておるのですが、こちらの成果を引き続き把握していきながら検討していきたいというふうに思っております。","voiceIndex":157,"id":"exchange-068"},{"speaker":"くにば委員","kind":"質問","question":"今お伺いしました１７校で、具体的に、どのような授業で、全般的に、例えば月１回であるとか、どういった形で取り入れているのか。すみません、具体的にお分かりになる範囲でお答えください。","respondent":"中谷指導課長","answer":"例えばなのですが、算数などで割合の問題などをやっていく、高学年になりますけれども、そういった中で、ちょっと割り算ができなかったり、掛け算ができなかったりとなったときに、当然、下の学年で過去にやった教材をひもといていかなければいけないのですけれども。","voiceIndex":159,"id":"exchange-069"},{"speaker":"くにば委員","kind":"質問","question":"ちょうど今、お話をいただいた個別最適な学び、特に学力のつまずき、そちらの部分で補習の部分、補習的な形で活用がされているというふうにお伺いいたしました。それに付け加えまして、今度は、先ほどお話をしました特色のある教育活動、ここに関連をして、ギフテッド教育についてお伺いいたします。そこで伺います。本区におけるギフテッド教育に対しての認識、または捉え方をお教えください。","respondent":"矢部教育総合支援センター長","answer":"ただ、小さな頃からの判断はすごく難しいというふうに考えておりまして、ある事例では、とてもできるということで、もう簡単だというお子さんが、１００点を取れるかというとそうでもなく、では、この人はギフテッドではないのか、そうなのか、そこはやはり教員においても。","voiceIndex":161,"id":"exchange-070"},{"speaker":"くにば委員","kind":"質問","question":"本区でも、先ほど、ＡＩ教材「Ｑｕｂｅｎａ」について関連して伺ったのですけれども、Ｑｕｂｅｎａは、今は補完的に勉強ができないところ、つまずきを回収して進めていくという、そういった使い方もあると思いますけれども、逆に、このギフテッドという子たち、つまずきの先に、その子たち、その子たち、特異的に、ここの部分は分かったから、では、その先のことをやろうみたいな形で。","respondent":"吉田品川図書館長","answer":"その辺の利用状況等を見ながら、今後、電子書籍をそろえていければと考えております。発売方法等につきましても、最近はセット物、４０冊とかでセットという形での売り方もしているようなので、その辺を含めまして導入は考えてまいりたいと思っているところです。","voiceIndex":163,"id":"exchange-071"},{"speaker":"くにば委員","kind":"質問・要望","question":"ご丁寧なご説明ありがとうございました。これはもちろん次年度、令和５年度の予算にかかるところだと思いますけれども、ぜひとも効率的にしながわ電子図書館、私は前に進めていっていただきたいと思います。児童生徒の読書のきっかけとなるよう、タブレット等で発信をしていただければと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":165,"id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３８１ページの給食運営費について、学校給食費の無償化を求めて質問したいと思います。この問題は一般質問でも取り上げました。かなりの負担です。この負担が困難とした根拠について伺いたいと思います。２００人で１,０００万円ということですが、これは第三子以降の子どもの何％に当たるのかも伺います。","respondent":"勝亦学務課長","answer":"第三子の割合につきましては把握はしてございませんけれども、ご支援申し上げているご家庭については、約２００人程度になってあります。","voiceIndex":167,"id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"住宅を購入していれば住宅ローンがありますし、賃貸の場合は家賃が１０万円以上してしまうということであれば、私は経済的支援ということであっても、これは不十分だし、さらに引き上げが必要ではないかと思いますが、いかがでしょうか。こういうところでも改善は必要ではないかというふうに思いますが、いかがでしょうかというのが１点です。","respondent":"勝亦学務課長","answer":"就学援助等々の充実をですけれども、こちらにつきましては、生活保護の１.２５倍の所得で判断をさせていただいている中で、経済的にお困りの方に必要な支援が届いているという考えです。","voiceIndex":169,"id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"葛飾区が今年９月に来年度からの給食費無償化を打ち出しました。同じく実施する市川市のホームページを見ますと、こう述べています。そういう中で、品川区としては、まだ検討もしていないということなのですけれども、検討もしない、また、そういう無償化のことを自治体として行わない、そのネックとなっている問題、考え方については、どういうふうに考えられているかについて伺いたいと思います。","respondent":"勝亦学務課長","answer":"そういった物価高騰の状況に応じた対応等はとってあります。先ほど申し上げましたけれども、生活保護ですとか、就学援助といった制度の中で経済的な支援を行っております。","voiceIndex":171,"id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところからも、ぜひ踏み出していただきたいと思います。それから、教育費は無償とするという中身についても、これは政府の無償化の解釈について、参議院での答弁でも、無償は学用品、学校給食費、交通費なども含むと答弁をしていますので、この考え方からも、ぜひ踏み出していただきたいと思うのですが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"無償化に対する考え方です。無償化に関しては様々な考え方、学説を含めあることは承知しています。ただ、現状、例えば、最高裁判所等におきましては、義務教育の無償化については、授業料の不徴収というふうに判断も出てあります。","voiceIndex":173,"id":"exchange-076"},{"speaker":"松澤委員","kind":"質問・要望","question":"私からは、３６３ページ、生徒指導対策等経費について質問いたします。会派からも、この部活動の地域移行の流れに遅れないように、早い段階から有識者会議などをするべきであると要望させていただきましたが、区における部活動地域移行の話合いがどのように進んでいるのか、現状をお聞かせください。","respondent":"中谷指導課長","answer":"現時点で、中学校９校、義務教育学校６校、合わせて１５校の全ての学校において、既に地域での活動に近い部活動がございまして、まずはそれらの取組の一部の管理運営につきまして、地域が担われる仕組みができるように検討していきたいと考えています。","voiceIndex":176,"id":"exchange-077"},{"speaker":"松澤委員","kind":"確認","question":"来年度、１取組ですか、１取組準備が進んでいるというお話を聞きまして確認がとれました。こういった地域移行が進む中、実は保護者から不安の声が上がっているのも事実なのです。そういうことをすることによって、区でも困っている現状がいろいろ皆さんに伝わるのではないかと思いますので、ぜひこういう周知をしてほしいと思いますが、ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"チラシの配布ということでご質問をいただきました。今、国の流れとしましては、６月にスポーツ庁から示された運動部活動の地域移行に関する検討会議提言が出されました。８月には文化庁からの文化部活動の地域移行に関する検討会議提言が出されました。","voiceIndex":178,"id":"exchange-078"},{"speaker":"松澤委員","kind":"質問","question":"ガイドラインは、たしか今日ですか。何かニュースで、ガイドラインを出しましたみたいなものを見たので、それを見て、いろいろと試行錯誤していただければと思っています。しかし、気をつけなければいけないのは、地域移行というのは確かに大切です。本当に地域移行が子どもたちに合うのかとか、そういったデメリット目線でのお話合いが重要ではないかと思いますけれども、ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"例えば、子どもたちの成長段階に関する知識であったり、子どもたちが自主的に活動できる魅力的な取組内容をつくり上げることなど、やはり指導していただく前のそういったアプローチが必要であろうという声も上がっておりますので。","voiceIndex":180,"id":"exchange-079"},{"speaker":"松澤委員","kind":"提案","question":"よく分かりました。部活の種類や活動するしないというのは、今の学習指導上、校長先生に決定権があるものと認識していますので、今ある部活を全部地域移行でスライドするのではなくて、やはり子どもたちの意見を聞いて、部活動のスリム化を図った上で、担ってくれる団体、人物を募集する、方向性として提案します。品川にいらっしゃるプロ選手の方の声かけなどもご提案しますが、ご見解を聞かせください。","respondent":"中谷指導課長","answer":"プロ選手の活用につきましても、検討してまいりたいと思います。","voiceIndex":182,"id":"exchange-080"},{"speaker":"松澤委員","kind":"提案","question":"運動部でもなく、文化部も地域移行の対象になると思いますけれども、また提案したいのですけれども、例えば、エコルとごしです。エコルとごしで、科学部、実験部、中学生ですか、そういった方たちを、エコルとごしに集結させてしまうのです。そういった意味で、今、区立学校を巻き込んでいく、そういったことが地域での学び、地域移行ということになるのではないでしょうか。ご見解をお聞かせください。","respondent":"中谷指導課長","answer":"ご提案いただいたエコルとごしの活用ということにつきましても、学校での授業の活用はもちろん図っていきたいということと、やはり地域でのダイナミックな活動という視点でも、今後、区長部局と連携して考えていきたいというふうに思っております。","voiceIndex":184,"id":"exchange-081"},{"speaker":"松澤委員","kind":"質問・要望","question":"先生の負担軽減からこういった議論になっている地域移行ですけれども、やはり一番大切な視点は、子どもたちにとって何がよい取組になるのか、子どもたちは何を求めているのかだと思っています。ここを重点に置いて、引き続きよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-082"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私からは、３８１ページ、給食運営費に関連して、今日は１点だけ、給食の牛乳のストローレスについて伺います。そして、本年の予算特別委員会の総括質疑でご紹介したように、今年度から、都内では１１区７市町村で、開けやすくストローを使わずに直飲みしやすいスクールポップというストローレス容器が導入されました。確認のため、なぜ導入をされなかったのか教えてください。","respondent":"勝亦学務課長","answer":"今まで導入されていなかった経緯です。学校給食の牛乳の納入先につきましては、国の要領に従いまして、東京都が乳業者への入札、契約を行ってあります。そういった意味で、品川区の希望する牛乳提供事業者とは品川区のほうでそういう設定ができないというような状況だったです。","voiceIndex":188,"id":"exchange-083"},{"speaker":"あくつ委員","kind":"提案","question":"東京都は、毎年、次年度の国の施策および予算に対し提案要求を行っていますが、本年６月に新たな提案項目として、都道府県による学校給食用牛乳供給事業者の決定に当たっては、環境配慮等の取組を評価し事業者決定が行われるよう、学校給食用牛乳供給対策要領を見直すこと、これは東京都から国へ要求をした。そして、その成果が出たのか、出なかったのか教えてください。","respondent":"勝亦学務課長","answer":"こうした対応をする中で、成果といたしましては、雪印メグミルク株式会社のほうから、来年度以降、学校に提供する牛乳パックにつきましては、ストローレスのものに変更するというご回答をいただいております。","voiceIndex":190,"id":"exchange-084"},{"speaker":"あくつ委員","kind":"確認","question":"本当にこれは教育委員会の努力だと思いますし、ご尽力だと思いますので、感謝をしたいと思います。小学校、中学校、義務教育学校全てで一斉導入されるのか教えてください。以前試算をしていただきましたが、ストローを使用しなかった場合、実際のプラスチックの削減量、ＣＯ２の削減量、ペットボトル換算等も教えていただきましたが、もう一度確認させてください。","respondent":"勝亦学務課長","answer":"導入される予定の容器ですけれども、先ほど委員からご紹介ありましたスクールポップというものを導入するというふうに聞いてあります。こちらにつきましては、小・中・義務教育学校全てで、全ての牛乳に適用する予定と聞いております。","voiceIndex":192,"id":"exchange-085"},{"speaker":"あくつ委員","kind":"確認","question":"ストローレス導入の来年４月まで時間が若干ありますけれども、環境問題への対応を一番子どもたちが身近に学べる絶好の学習材料とタイミングだと思いますので、学校給食のプラスチックストローが、これからどうやって、どうしてなくなっていくのかということとか、この経緯とか、そういったこと、そして、先ほどおっしゃっていただいた、どういう削減になるのかなどを子どもたちと、例えば、メーカー。","respondent":"勝亦学務課長","answer":"そういった中で、環境学習、そういった取組の重要性、そういったものを牛乳提供者と連携して伝えていこうというふうに相談をしています。","voiceIndex":194,"id":"exchange-086"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一番身近な給食のプラスチックストローをなくしたいねということで、どういうふうに請願を書いたらいいのですかということで、私もそれはお手伝いしましたけれども、これは皆さんのご要望なのです。変な目で見られてしまうと、やはりその子もかわいそうだし、大人の事情もあるから、そこは黙ってストローを使って飲んだらどうですかとは、やはり口が裂けても言えなかったです、そのときは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":196,"id":"exchange-087"},{"speaker":"高橋（し）委員","kind":"質問","question":"３６９ページ、幼稚園運営費、３８３ページ、学校改築推進経費、先に学校改築です。城南第二小学校は、令和３年度に基本設計、令和４年度は実施設計です。この後、工事等は計画どおり進んでいると伺っていますが、それでよろしいでしょうか。地域の期待、ご希望が多いので、今年度、現地調査などが行われたのですが、今後、城南第二小学校の流れと同じように改築の流れに乗っていくのでしょうか。","respondent":"森学校施設担当課長","answer":"続きまして、鈴ヶ森小学校についてどうなるのかというところですけれども、現在は文化財の調査等を行っておりまして、今後の予定ですけれども、非常に有力な改築の候補校だというふうにこちらでは考えてあります。","voiceIndex":198,"id":"exchange-088"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"城南第二小学校は順調と、鈴ヶ森小学校は非常に有力な改築の候補の１つということが確認できました。区立幼稚園３園の廃止については、本会議および先日の民生費において質問をさせていただきましたが、明確な答弁をいただけず時間切れとなりました。もし手続をしていたとすれば、教えていただきたいと思います。この区長部局の勇み足を教育委員会事務局としてどのように捉えているでしょうか。","respondent":"勝亦学務課長","answer":"幼稚園３園の廃園の方針についてのお問合せです。こちらにつきましては、補助執行しています区長部局のほうで、子育て支援を一体的に行うという区長部局への補助執行の目的の中で検討を行い、幼稚園、保育園の入園状況などから調査を行って、その方向性を決めたものです。","voiceIndex":200,"id":"exchange-089"},{"speaker":"高橋（し）委員","kind":"質問","question":"ところで、１１月１日の文教委員会の記録によると、庶務課長は、端的に幼稚園の廃止に関することは教育委員会の職務権限に属するとはっきり明記されていますとおっしゃっています。これは至極真っ当な行政官としての認識であると思います。さきの庶務課長によるこのような認識があるならば、区長決定の前に、事前にどうしてストップがかけられなかったのか、教育委員会事務局としての見解を伺います。","respondent":"勝亦学務課長","answer":"こちらの方針の決定について関与しているものでございまして、先ほどご紹介ありました庶務課長がお答えしました教育委員会での議論、議決が必要になる。こちらも必ず必要になるものですので、何ら相反するものではございません。","voiceIndex":202,"id":"exchange-090"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今後、教育委員会でどのように審議していくのか、教育委員会のスケジュールを教えていただきたいです。時期と、そして、報告ではなくて、どのような議案を審議していくのでしょうか。条例をどうするかではなくて、３つの幼稚園の廃止をどうするかという議案なのかという点もお伺いします。","respondent":"勝亦学務課長","answer":"検討委員会の中でも、教育委員会の事務方としまして事務局の職員が委員会のメンバーとして参加して検討を重ねて出しておりますので、閉園の方針について言及することについても、教育委員会、区長部局の連携の中で補助執行の範囲の中だと考えています。","voiceIndex":204,"id":"exchange-091"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"つまり、幼稚園の廃園をフラットな形で決定する、そのことを求めます。前も申し上げましたが、検討委員会が検討したその検討の過程とか、それについて異議を唱えているわけではありません。手続上、きちんとしないことには、やはりその検討自体がどうなるのかという話にもなります。時間がありませんので、またの機会に取り上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":206,"id":"exchange-092"},{"speaker":"芹澤委員","kind":"質問","question":"よろしくお願いします。３７５ページ、学校ＩＣＴ活用経費、３５９ページの文化財保護費からお伺いします。３７５ページのＩＣＴ活用経費の中で、タブレットであったりとか、先ほどのランドセルの重さについても関連してお伺いをしていきたいと思います。そしてまた、どれぐらいからが子どもに悪影響を与えるとお考えなのかをお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"お子さんにどのように影響するかということですけれども、学年とか体力とか、中身にもよりますので、一概には申し上げられませんが、そのお子さんにとって重いということであれば、それは対応しなければいけないというような認識です。","voiceIndex":208,"id":"exchange-093"},{"speaker":"芹澤委員","kind":"質問・要望","question":"アメリカのデータによると、背負う荷物の理想、悪影響とはちょっと別ですけれども、理想としては、体重の１０％ぐらいまでが理想であろうというようなアメリカのデータがあります。そうすると、２０１７年のデータの５.７kgからは非常にかけ離れていて、ぜひこれは、国も連携しながらになりますが、減らしていっていただきたいなという思いであります。教育委員会のお考えをお聞かせください。","respondent":"矢部教育総合支援センター長","answer":"ただ、紙のほうがいい場合、また、１枚渡して、お子さんから保護者に手渡してほしいなどという紙もありますので、その辺りのバランスも考えながら、区教委としても検討して、子どもにあまり影響がないように配慮してまいりたいと考えております。","voiceIndex":210,"id":"exchange-094"},{"speaker":"芹澤委員","kind":"提案","question":"端末について引き続きお伺いしますが、今の端末では、基本的には、学校から子どもたち、児童にデータを配信して、子どもたちから学校へ返していくというような流れだと思っています。以前もご提案させていただきましたが、自民党で台湾に視察に行ったときに、学校の朝礼のときにテストみたいなものをやっていて、一番早く回答した人が常にクラスの一番前に表示されているというようなものがありました。","respondent":"勝亦学務課長","answer":"今後、Ｗｅｂ３.０といった個人と個人がインターネットの中でつながっていくという社会の中で、そういった変化は出てくるのかなですけれども、現状におきましては、そういった配慮とセキュリティの中で、メッセージ等々はやり取りできないようにしているという考え方です。","voiceIndex":212,"id":"exchange-095"},{"speaker":"芹澤委員","kind":"提案","question":"Ｗｅｂ３.０の中で、おっしゃるとおりで、いじめ等もあるので、ＳＮＳ等も使えないというのは理解をしていますが、私が求めているのは、そういう個人を特定する必要はなくて、それぞれの学校のクラスの中で、自分たちが、自分の成績であったりとか、進捗であったりとかが、どれほど例えば優れているのか、平均にとってまだ少し足りない部分があるのかということを、進捗を確認する。","respondent":"中谷指導課長、吉田品川図書館長","answer":"データの扱いというところでのご質問にお答えさせていただければと思います。１つのクラスの中でデータを共有したりなどということを１人１台タブレットの中でやっております。種類が、まだ紙の書籍ほど学校向けのものなどもそろっていないところがありまして、なかなか進まないところでもあります。","voiceIndex":214,"id":"exchange-096"},{"speaker":"芹澤委員","kind":"提案","question":"データについては、ロイロノートの件ももちろん存じ上げていますが、現状ではなくて、今後ぜひ、競争を目的とするというよりは、自分とクラス全体のモチベーションをそれぞれ高め合って進めていただきたいという提案ですので、よろしくお願いいたします。図書館については、課題はあると思うのですが、今、実際、しながわ電子図書館でやってきた実績もあると思います。最後、文化財についてお伺いします。","respondent":"宮尾庶務課長","answer":"もう１件が、南品川の石積護岸でございまして、こちらは品川区の指定文化財の登録に向けて、審議会の皆様にもご審議をいただき、また、現地を調査していただいたりなどという段階で、今、登録に向けて動いているです。","voiceIndex":217,"id":"exchange-097"},{"speaker":"芹澤委員","kind":"質問・要望","question":"八潮太鼓であったりとか、１つ、文化財になり得るものも、今、生まれているかと思いますが、それを保護して継承を促して、そして文化財へつなげていくというような支援も必要なのかと思いますが、ご見解をお聞かせください。","respondent":"宮尾庶務課長","answer":"文化財の保存と活用という法、もしくは法令等の趣旨をしっかり踏まえまして、また、今、委員からお話をいただいたことも踏まえて、今後、審議会の皆様と共にまた考えて。","voiceIndex":219,"id":"exchange-098"},{"speaker":"芹澤委員","kind":"意見","question":"文化財、正に歴史、文化、伝統という中で、歴史というのは、ある意味、勝手にというか、育っていくものもあれば、やはりこれは行政とか地域の方が一体となって文化を残していって、それが新たな歴史になっていくというような考えもあるかと思いますので、ぜひ区が積極的に引き続きバックアップをしていただいて、より豊かな文化、文化財が残るように、お力をお貸しいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":221,"id":"exchange-099"},{"speaker":"石田委員","kind":"質問・要望","question":"私からは、３６０ページ、教育指導費から、性教育について伺いたいと思います。この間、一般質問でも取り上げさせていただきました包括的性教育の実施を求めて質問いたします。第２回定例会の一般質問で、包括的性教育の実施を求めましたけれども、区は、現在区が行っている性に関する指導は、包括的性教育に準ずるものと考えていると答弁されたのです。一方で対照的なのが日本の性教育だと。","respondent":"矢部教育総合支援センター長","answer":"２点あるかと思いますが、１点目はご意見ということで承ります。２点目の産婦人科医による授業についてですが、やはりすぐに授業というよりは、養護教諭を対象に、産婦人科医を招聘しまして講義をしていただいたところです。","voiceIndex":224,"id":"exchange-100"},{"speaker":"石田委員","kind":"質問","question":"それは学校での授業でということですか。それとも、職員向けにということでしょうか。","respondent":"矢部教育総合支援センター長","answer":"養護教諭研修会の中で招聘したものです。","voiceIndex":226,"id":"exchange-101"},{"speaker":"石田委員","kind":"質問・要望","question":"避妊に失敗した場合、性交後３日以内であれば緊急避妊法があることや、性交後３週間たっても月経が来なければ、市販の妊娠反応検査、または産婦人科受診が必要であること、こういったことを話されたと。こうした都の事業があるというのは、区内の学校は知っているのか伺いたいと思います。それと北区のように、区教委から各学校に声をかけていただきたいと思うのですけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"ただ、先ほどの養護教諭研修の中では、養護の先生方は、大変ためになったということでしたので、専門としての認識がとても高まったというふうに認識しています。","voiceIndex":228,"id":"exchange-102"},{"speaker":"石田委員","kind":"質問","question":"子どもたちの周りの性に関する課題は多彩ですし、そういった上でも、身を守り、相手も尊重できるという、そういった関係性をつくるための性教育、性教育というか、包括的な多角面から取り上げた包括的性教育を実施していかないと、本当に子どもたちの安全が守られないのではないかと思っています。こうした考え方について、区の見解を伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"話が戻りますが、包括的性教育の中身の中に、今、委員がおっしゃいましたように、関係性ですとか、暴力から身を守るとか、ジェンダーとか、友情とかということも項目の中にあるわけで、それは、保健ですから生殖のことだけで完結することではなくて。","voiceIndex":230,"id":"exchange-103"},{"speaker":"石田委員","kind":"質問・要望","question":"なので、寝た子を起こすという論もお聞きしたのは、区は、そういう性教育をさらに進めることが、寝た子を起こすと思いますかということを改めて伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"人権に関わることなので、「寝た子を起こす」という、そういう表現ではなくて、大切なことはきちんと教えていく、学ぶべきだと考えております。","voiceIndex":232,"id":"exchange-104"},{"speaker":"石田委員","kind":"質問・要望","question":"ということは、性教育というのは、権利として大事なものだと捉えているということでよろしいですか。確認させていただきたいです。それで、正に寝た子を起こす論の子ども観が、子どもたちが置かれている現実に全く即していないということが、この寝た子を起こす論だと思います。これ、教員への研修とか、改めての教員への性教育が必要になってくるのではないかと思うのですけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"生活指導主任会中心に、性被害に遭わないという意味で、防止という意味で、改めて周知をしているところです。内容については大変大切なところですので、学校の中で時間をとって、それぞれ周知、指導しているものと考えております。","voiceIndex":234,"id":"exchange-105"},{"speaker":"石田委員","kind":"質問","question":"なので、そういったところが、品川区ではどのように取り組まれているのか、今の答弁ではちょっと簡単過ぎて分からなかったのですけれども、もう一度教えてください。","respondent":"矢部教育総合支援センター長","answer":"性被害、加害にかかわらず、子どもたちが相談するツールはたくさんありますし、機会もあります。ＣＡＰですとか、セーフティ教室、または目安箱、ＳＯＳフォルダを改めてタブレットに登載いたしました。ＳＯＳの受け方ということについても生活指導主任会で共有したところです。","voiceIndex":236,"id":"exchange-106"},{"speaker":"高橋（伸）委員","kind":"質問","question":"よろしくお願いします。３６３ページ、校長・園長向け研修会、３７３ページ、地区図書館運営費についてお伺いいたします。最初に、校長・園長向け研修会についてお尋ねいたします。それで、先日、先日と言っても、今年の６月ですか、校長・園長向けの研修会で、環境教育の一環で、「気候の危機と社会の大転換」というお題目で、エコルとごしで開催されたということです。","respondent":"矢部教育総合支援センター長","answer":"今このご紹介をした理由は、実はそこでは、授業で子どもたちにどう伝えるかというところを、先生方でですけれども、一生懸命グループで考えたのですけれども、なかなか難しいということが分かったのです。","voiceIndex":239,"id":"exchange-107"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは私ごとで恐縮なのですけれども、私も家庭教育学級の一環で、海の環境教育を区内の小学校、何校かやらせてもらった経験があります。そこで、いろいろ環境教育も様々あると思うのですけれども、私は特に小学校の低学年の子どもたちに対して、強く環境教育の大切さを教えていただきたいのですけれども、それについてどういうふうにご見解を考えているのかお知らせいただきたいと思います。","respondent":"矢部教育総合支援センター長","answer":"学校の中では、ごみを分別することから始まりまして、先ほどもストローの話もございましたし、様々考える材料はあるというところで、できるだけ具体的な操作を通して子どもたちとともに考えてまいりたいと思います。","voiceIndex":241,"id":"exchange-108"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ今後とも未来ある子どもたちのために、ぜひこの環境教育、邁進して取り組んでいただきたいと思います。続きまして、３７３ページ、地区図書館運営費についてお尋ねします。１つお尋ね、これは確認なのですけれども、認知症カフェは、今現在の４館でやっていると私は認識しているのですけれども、それでよろしいのかお尋ねしたいと思います。","respondent":"吉田品川図書館長","answer":"委員ご指摘の地区図書館における認知症カフェの開館の数ですけれども、荏原、八潮、五反田のほか、品川図書館を含めて４館です。","voiceIndex":243,"id":"exchange-109"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今、最初に申し上げた地区図書館１０館で、地域と連携をしながら様々なサービスを展開しているということなのですけれども、具体的にどういう展開をされているのか教えていただきたいと思います。それともう１つ、その１０館の中に、源氏前図書館は含まれているかどうかも確認させていただきたいと思います。","respondent":"吉田品川図書館長","answer":"地区図書館の地域連携ですけれども、指定管理の地区図書館におきましては、全ての図書館において何かしらの地域連携を行っております。例えば、源氏前図書館においては、中延商店街と連携しておりまして、ブックリスト等を作っております。","voiceIndex":245,"id":"exchange-110"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ様々なサービス、認知症カフェもそうですけれども、いろいろ運営など取り組んでいただきたいと思います。いろいろとこの先、改修等々やらなければいけない中で、源氏前図書館は３階にあるので、階段の上り下りが大変で、足元が不自由な方、高齢者から、エレベーターを設置してくださいという要望が結構寄せられているのです。","respondent":"吉田品川図書館長","answer":"エレベーターもなく、障害者向けトイレもないということで、その辺のところは認識しています。いつ建て替えるかなどについては決まっておらないところですが、建て替えを行う際には、高齢者対応だとか、バリアフリーの配慮などをしながら対応していこうと考えているところです。","voiceIndex":247,"id":"exchange-111"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひこれ、前向きにいろいろ対策を考えてやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":249,"id":"exchange-112"},{"speaker":"松本委員","kind":"質問・要望","question":"私からは、３６３ページ、生徒指導対策費、３８１ページ、学校運営費について伺います。ただ一方で、高校は義務教育ではありませんので、中学生が高校に進学したいのだというときに、親が同意しない、これは親権を行使しないということになるかと思いますけれども、親権を行使しないというふうな、進学を許してくれないというときに、これが法律上の虐待に該当するのかどうか、ご見解を伺います。","respondent":"矢部教育総合支援センター長","answer":"ただ、経済的なものや、その後の進路を親が考えているのは様々な背景もあると思いますので、そのときそのときで対応できることを学校としてはするものだと考えております。","voiceIndex":251,"id":"exchange-113"},{"speaker":"松本委員","kind":"質問・要望","question":"そちらの１１月の通知では、授業料や進学費用など経済的な相談を学校が受けた場合には、奨学金などの制度を紹介するとともに、保護者が給付金を教育費に使用しないおそれがある場合、学校が代理で受領するなどの対応を求めるといった内容でした。保護者の宗教を理由として、高校進学について生徒と保護者の方針が異なった場合に、学校としてどのような対応をするというふうに考えていらっしゃるのか伺います。","respondent":"矢部教育総合支援センター長","answer":"様々な相談案件がありますけれども、発見できた場合は、そのような対応を学校はしていくと思います。","voiceIndex":253,"id":"exchange-114"},{"speaker":"松本委員","kind":"質問","question":"これは区にこうしてほしい、教育委員会にこうしてほしいというよりも、問題を明らかにすることも大事なのかなと思っていまして、生徒のほうからヘルプ、ＳＯＳというふうなものが上がったときに、ご対応はもちろんしていただくと思うのですけれども、ただ一方で、では、その実効力のある何か法的な対応が可能なのかというところは、これはいかがでしょうか。この点についてお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"私たちは、身近なところは児童相談所、子ども家庭支援センターになりますが、今回、ご案内の１０月の通知のほうに、こういう宗教も関わった虐待のような事案については、相談機関がたくさん紹介されておりましたので、そちらのほうをご覧いただくというふうになるかと存じます。","voiceIndex":255,"id":"exchange-115"},{"speaker":"松本委員","kind":"質問・要望","question":"ありがとうございました。次の質問にいきます。学校運営費のうち、防災ヘルメットについて伺いたいのですけれども、７年生用の防災ヘルメットの購入費が上がっているかと思います。私のほうから伺いたいのが、小学生の防災頭巾については、各ご家庭が自費で、自分のお金で用意するというふうなところでよろしいでしょうか。","respondent":"勝亦学務課長","answer":"小学生の防災頭巾に関しましては、入学に当たり、そろえていただく学用品として、各ご家庭にご負担をいただいておるところです。","voiceIndex":257,"id":"exchange-116"},{"speaker":"松本委員","kind":"質問","question":"先ほど、虐待の議論をずっとしていたのですけれども、残念ながら、親が子どもの安全ということにあまり関心がないということもあろうかと思います。その際に、保護者が防災頭巾を用意しない、あるいは用意したとしても明らかに粗悪品で安全確保面から問題があるといった場合に、学校としては、どういうふうに対応していくことになるのでしょうか。","respondent":"勝亦学務課長","answer":"基本的には、市販のもので、例えば、いすにつけられるものでという形で、大体共通の性能のものをお願いしている形になりますので、それにもし満たないようなものであれば、学校のほうから各ご家庭にお話をするような形になろうかと思います。","voiceIndex":259,"id":"exchange-117"},{"speaker":"松本委員","kind":"質問","question":"中学生の防災ヘルメットについては、これは区が負担するというふうになっている。小学生については保護者負担というふうになっているわけです。さらに言えば、よく考えたら、私たち議員についても、防災ヘルメットはたしか支給、貸与というか、用意はされているかと思うのです。当区としてもそういったところを検討してもいいのではないかと思いますが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"現在、中学生の方へのヘルメットにつきましては、防災教育、防災意識の向上、ある程度、防災へ関わっていただくという意味では、購入して区費で負担しているものです。","voiceIndex":261,"id":"exchange-118"},{"speaker":"大倉委員","kind":"質問・要望","question":"よろしくお願いします。３５９ページ、クラブ・部活動等経費、あと、３７７ページ、学校ホームページ経費、あと、環境教育学習について伺えればと思います。８月に会議があってキックオフが行われて、今、会議をしているところですというところで、１組、進んでいるというところで、このキックオフが始まってすぐ進んでいるというのは非常にすばらしいと考えています。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"先ほど申し上げましたとおり、ガイドラインを今後踏まえていきまして、さらに具体化してまいりたいと思いますので、その辺りを含めて、また会議を継続していけたらと考えています。部活動指導員のお尋ねです。現在の状況はということで、１５名は配置されているのですが、１１校です。複数配置のところと、どうしても見つからない状態の学校がございまして、その状況です。","voiceIndex":264,"id":"exchange-119"},{"speaker":"大倉委員","kind":"質問・要望","question":"一方、部活動のほうなのですが、１５校中１１校ということで、全校配置を目指しているということだったかと思うのですが、今、１１校ということで、４校足らないというところでは、また、部活動も１校につき１つということではないと思いますので、部活動指導員以外の外部指導員の活用などもしながらやっているのかと思うのですが、その取組と併せて、今後の部活動指導員。","respondent":"矢部教育総合支援センター長","answer":"地域移行の話もありますし、部活動指導員も補助金を受けているものですので、より充実した部活のために推進してまいりたいと考えています。","voiceIndex":267,"id":"exchange-120"},{"speaker":"大倉委員","kind":"質問","question":"すみません、先に結論を言ってしまったのですけれども、今後、部活動指導員と外部指導員も含めてなのか、部活の地域移行のバランスというのは、どの程度をとっていくのかというところは、どう考えたらいいのかなと思いまして、その点の考え方について、全部が地域移行ではないし、全部が部活動指導員でもないと思うので、その辺のバランスはどういうふうに考えたらいいのか教えてください。","respondent":"中谷指導課長","answer":"地域移行の在り方というのは、様々なニーズに応えるいろいろな方々とのマッチングというところがあるかと思いますので、その辺りは、今後、区長部局との連携の中で、いろいろな情報をまず共有する中で。","voiceIndex":269,"id":"exchange-121"},{"speaker":"大倉委員","kind":"質問・要望","question":"次に移ります。学校ホームページなのですが、以前もちょっと質問したことがあるのですが、学校によって更新頻度や内容にかなりばらつきがあるのですが、この理由について教えていただきたいのと、あと、環境教育について、先ほどもエコルとごしの話が出て、社会科見学でかなりの学校が利用されているというようなことだったのですが、どのくらい行っているのか教えてください。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"そういった中で、各学校の中の工夫、特色を出していくということで、各学校が工夫をしながら情報発信をしているということで、更新ですとか、そういったタイミングがずれているというふうに考えているところです。エコルとごしの見学ですが、今年度は、教育総合支援センターで把握しているところにつきましては、３年生が１０校、６年生が１校です。そのほか、これからも計画されるというふうに思います。","voiceIndex":271,"id":"exchange-122"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは健康上の目的でやっているのかなというところで思ってはいるのですが、ただ、今、ペットボトル削減で、マイボトル運動みたいなものが行われていて、ある種、それは正にマイボトル運動なのではないかなというふうに思っているのですが、そういったことも含めて、子どもたちに、実はこういうことは環境にかなり配慮した活動なのだよ。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"そういった周知していただくものの中で、確実に学校からお知らせをしていただく中には、当然ホームページに掲載をする、教室の中でプリントとしてお配りする、口頭で子どもたちに伝える、様々な方法がありますので。水がいかに大事かということを学んで、実際に水を、蛇口の栓をひねるということにつなげていくというような取組もしていますので、ある程度、授業の中での長いスパンの中での指導も必要だと考えています。","voiceIndex":274,"id":"exchange-123"},{"speaker":"大倉委員","kind":"質問","question":"学校のホームページ上でそういったお知らせをする際に、ホームページ上でお知らせをしてくださいねというお知らせを教育委員会のほうの手続でできるのかどうかということで、それができれば、学校でやる先生方の負担の軽減になると思って、頻度は様々あるということだったのですが、それを軽減するために教育委員会でできないのかという質問だったので、もう一度ご答弁をお願いしたいのと、水のほうですが。","respondent":"勝亦学務課長","answer":"学校のホームページの更新につきましては、各学校で操作をするような仕様になってありますので、教育委員会での操作はできない形となっています。簡単に入力できるようなＣＭＳというようなシステムを使ってありますので、大きな負担にはならないかなというふうに捉えてあります。","voiceIndex":277,"id":"exchange-124"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、ページ３６０、教育指導費から、がん教育と性教育についておよび新型コロナウイルス感染症の感染予防対策について、順不同でお伺いしていきますので、よろしくお願いいたします。がん教育について伺います。本年４月からＨＰＶワクチンの接種勧奨が再開されました。現在、学校のがん教育において、ＨＰＶワクチンの扱いはどうなっているのでしょうか。ご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"がん教育につきましては、６年生の保健で病気の予防、８年生の保健で健康な生活と疾病の予防について学習いたします。令和２年度より、全ての中学校、義務教育学校の後期課程において、がん専門医による指導を実施しております。","voiceIndex":282,"id":"exchange-125"},{"speaker":"鈴木（博）委員","kind":"質問","question":"発がんウイルス感染症は、ＨＰＶ（ヒトパピローマウイルス）感染のみではありません。Ｂ型肝炎ウイルスなど他の発がんウイルスに関する知識を深めることが、がん予防一般の学習内容として適切であると思われますが、教育委員会のお考えはいかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"Ｂ型肝炎など、ほかの発がんウイルス感染症に対する予防については、８年生の「がんとその予防」の中でも触れられておりまして、がん専門医による外部講師の指導の中でもお話をしています。","voiceIndex":284,"id":"exchange-126"},{"speaker":"鈴木（博）委員","kind":"質問","question":"性教育について伺います。国立感染症研究所の報告によれば、今期の梅毒流行は、男性は２０代から５０代まで幅広く患者が分布し、約４０％に性風俗の利用歴があったこと。現在、学校における性教育において、１、性感染症に対する一般的な知識、２、不特定多数との安易な性交渉の弊害などについて、どのような学習が行われているのかご説明をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"各学校におきましては、文部科学省から令和３年５月に配布されました「生命（いのち）の安全教育」の教材を活用いたしまして、発達段階に応じて性に関連する安全教育も進めているところです。","voiceIndex":286,"id":"exchange-127"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今ご答弁をお聞きしましたが、不特定多数との安易な性交渉の弊害について、具体的なご答弁をもう一度お願いします。","respondent":"矢部教育総合支援センター長","answer":"この教材につきましては、中学生のほうも指導内容が示されておりますので、発達段階におきまして、そのような教材を利用して安全教育を進めてまいりたいと考えています。","voiceIndex":288,"id":"exchange-128"},{"speaker":"鈴木（博）委員","kind":"確認","question":"今、症状が出ていないか確認してください。私のクリニックの患者さんにもお話を伺いましたが、全く情報がないので、自分の子どものクラスにコロナの陽性者がいるか心配、何をどう注意したらよいか分からない、誰がコロナか分からないので、クラスの子どもと接触するのにも気を遣う。以上、学校現場のコロナ情報提供を再検討すべき時期に来ていると思われますが、区のお考えを伺います。","respondent":"勝亦学務課長","answer":"そういった意味で、学年に限った情報であっても、個人が特定される可能性があります情報提供の内容については、慎重に検討する必要があると考えております。","voiceIndex":290,"id":"exchange-129"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そうすると、再び感染症が増加してきている現在、教育委員会が相変わらずデルタ株以前の感染者の隔離・隠匿をするという厳格な感染予防対策を基本的に継続するものと伺いました。非常に残念な対応だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":292,"id":"exchange-130"},{"speaker":"のだて委員","kind":"質問・要望","question":"私からは、３６９ページの特別支援教育費に関わって、特別支援教室を中心に伺います。入学してから発達障害が分かり不登校になってしまった児童の保護者からお話を伺いましたので、ちょっと長いですけれども紹介したいと思います。なぜ転校するのにこのようにハードルがあるのか、発達障害や不登校の子も通える、子どもに合わせた対応を求めますが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"そういった面談を行っていただいた中で、そのお子様に最も適した状況であるということを、送り出す学校、受け入れる学校それぞれのほうで確認した上で、その子の最適な結論を導いて手続に入るというところで、ちょっとステップが多くなっているというふうに考えてあります。","voiceIndex":294,"id":"exchange-131"},{"speaker":"のだて委員","kind":"質問・要望","question":"その子に合わせた対応をしていただきたいと求めましたので、その答弁もいただきたいと思いますが、いろいろ状況を見て、適切だというところで判断をしていくということなのですが、その方の場合、直接区役所の窓口に手続しなければいけないと言われて行った後に、校長との面談をその前にしてもらわなければ手続できないと言われて、二度手間になってしまったという状況もありましたので。","respondent":"勝亦学務課長","answer":"その二度手間になってしまったというようなところ、窓口での対応につきましては、こういった転校の手続について、より分かりやすく、学校、それからホームページ等、保護者の方にも丁寧に周知していくということが必要だと考えています。","voiceIndex":296,"id":"exchange-132"},{"speaker":"のだて委員","kind":"質問・要望","question":"特別支援教室の期間の問題も、基本的に１年に限定されたというところで改悪をされましたけれども、児童生徒にとって必要な指導、支援が十分に行えるようにしてほしいと思いますけれども、この間、区議会などでも議論がありまして、必要に応じて２年を超えて実施することができるということになっておりますが、これが現場に伝わっていないということで。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"お休みの先生が出たときの代替というところで、この特別支援教室に関しては、都費の講師が配置できないような東京都の仕組みということもございまして、このことに関して、課題であるということを、特別区、２３区内で共有しています。時間講師の続きですが、やはり人がいないということはとても心配なところでございまして、教育総合支援センターの中では、介助員、学習支援員を配置するということは相談に乗っていますので。","voiceIndex":298,"id":"exchange-133"},{"speaker":"のだて委員","kind":"質問・要望","question":"この期間、原則１年で、延長も１年ということですけれども、都議会の議論の中で、やはり障害を持っている方たち、様々な課題があって、それを改善していくためには、そうした期間ではできないこともありますから、その子に応じて、必要に応じて、２年を超えてできるということになっていると思いますが、これをぜひ現場に周知をしていただきたいと思いますけれども、いかがでしょうか。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"ですので、繰り返しになりますが、人数の１２人に１人というところ、そして、そういった補充ができないシステムということも含めて、特別区としての東京都への要望ということでやってまいりたいと思います。ただ、今ご指摘のとおり、東京都のほうにも確認しましたが、その後の延長については、就学相談委員会、結局、区のほうの委員会できちんと検討して、可能性もあるということは聞いていますが、基本的には１年間で退室いただくように。","voiceIndex":301,"id":"exchange-134"},{"speaker":"のだて委員","kind":"質問・要望","question":"期間の問題も、２年以上の可能性はあるということですから、ぜひそういったことも含めて、現場の教員の方に周知をしていただきたいというふうに思います。改善すべきと求めると、区は、様々なことから判断していると。ＷＩＳＣは１つの方法と答弁しました。なぜこの検査を増やせないのか伺います。訪問相談の枠も増やしていただきたいと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"訪問相談は、名前だけだと、今、私がお伝えしました巡回相談員と、あと、東京都や区から出している特別な専門家が訪問するものがあるのですが、そちらはかなり手厚く行っているはずなのですが、人数と対応していないということがもしもあるのでしたら。","voiceIndex":304,"id":"exchange-135"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ拡充をさせているということですので、ぜひそれは需要に応じて、こうした支援が遅れるということがないように、子どもたちの教育が保障されるように、ぜひ増やしていっていただきたいというふうに思います。区は、これまで計画的に進めていくと答弁してきましたけれども、なぜつくらないのか伺います。","respondent":"矢部教育総合支援センター長","answer":"計画どおり進めております。品川区総合実施計画、品川区長期基本計画に基づきまして進めているところです。今後もインクルーシブ推進ですとか、国や東京都の動向を注視しながら、区としてもしっかり検討しながら進めてまいりたいと考えています。","voiceIndex":306,"id":"exchange-136"},{"speaker":"塚本委員","kind":"質問","question":"私からは、３７９ページ、学校維持管理費、これは学校への水筒の持参についてです。３６９ページ、特別支援教育サポート経費、これは巡回相談員について、あと、３７５ページの学校ＩＣＴ活用経費ということで、順に伺っていきたいと思います。これは置いていっても大丈夫なのだというものを全部置けるような環境はあるのかというところを最初にお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"様々学校の環境、スペースのこともありますし、お子さんたちの数にもよるので一概に申し上げられませんが、基本的には、後ろのロッカーですとか、横の空きロッカーとか、そういうところに置いているものと考えております。","voiceIndex":309,"id":"exchange-137"},{"speaker":"塚本委員","kind":"確認","question":"そういった中で、コロナもこの先第８波等もありますけれども、様々な形で日常を取り戻していく中で、水筒の持参というのは今後どのようにしていくのか。学校内で水分を補給すると、以前のように水筒を持たずに学校の水道水で水分を補給する、こういったことに戻していくというふうにはならないのかなというところについて、どのように捉えていらっしゃるか伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"荷物のこととなりますと、またそこへの配慮も必要ですので、今後、ガイドラインの中身も、また、これから国や都の動向も含めながら、感染状況も踏まえながら検討してまいります。","voiceIndex":311,"id":"exchange-138"},{"speaker":"塚本委員","kind":"質問","question":"一定程度、コロナが収束をしたとしても、また新たな感染症対策ということで言えば、非接触型というような形での給水機みたいなものですか、そういうものも検討していく必要があるのではないかというふうにも思いますけれども、こういった学校の設備面においての給水の今後の対策ということで、区のご見解を伺いたいと思います。","respondent":"勝亦学務課長","answer":"今後の給水の在り方ということで、今、非接触型の給水というようなご紹介をいただきました。今後の感染症の対策ですとか、様々な新しい技術等出てきておりますので、そういった状況を見ながら、今後研究していきたいと考えています。","voiceIndex":313,"id":"exchange-139"},{"speaker":"塚本委員","kind":"質問・要望","question":"最初に確認をさせていただきたいのですが、この巡回相談員というのは、保育園から学校ということで、同じ人が同じ子を見るというような体制で実施をされているものなのか。ここのところについて確認をお願いいたします。","respondent":"矢部教育総合支援センター長","answer":"教育総合支援センター所管の巡回相談員は、特段幼稚園、保育園との連携をしているものでございません。","voiceIndex":315,"id":"exchange-140"},{"speaker":"塚本委員","kind":"質問・要望","question":"巡回相談員という方が、就学前からずっと発達障害等の早期発見、早期療育ということを目的にされているわけでありますので、切れ目なく小・中学校へということで支援を継続していくということでいくと、ここはやはりこの２つの継続性というのは非常に意味のあるものなのではないかというふうに考えているところなのですけれども、現在はそこがなされていないということで。","respondent":"矢部教育総合支援センター長","answer":"幼保と小との連携につきましては、就学支援シートですとか、保育の保育要録、幼稚園の指導要録、または、児童生徒実態把握表など、保護者に理解を得ながら情報共有をしているものもあります。","voiceIndex":317,"id":"exchange-141"},{"speaker":"塚本委員","kind":"確認","question":"分かりました。１つ確認をしておきたいのですけれども、以前の本会議の一般質問で、巡回相談員ですとか、カウンセラーですとか、教員ですとか、こういった方々がいろいろ関わって、特別支援といったことについての個別指導計画等を考えていくというところにおいて、集団守秘義務というような考え方を１回質問したことがあります。","respondent":"矢部教育総合支援センター長","answer":"少なくとも公務員または会計年度任用職員、きちんと委託も含めて個人情報の管理はしっかりできておりますので、特にお子さんの個人情報につきましては厳重に管理をしています。","voiceIndex":319,"id":"exchange-142"},{"speaker":"塚本委員","kind":"質問","question":"そういう前提の中で、集団守秘義務ということで、関係者の間では、しっかりした支援をするために、集団という中での少し広げた、要件緩和したような形で情報共有するということは、そういう意味ではなかなか難しいと、それは難しいのだ、こういう見解でよろしいですか。","respondent":"矢部教育総合支援センター長","answer":"難しい場面は間違いなくあると思います。ただ、お子さんについて、特に保護者のご了解を得ている場合は、きちんと情報共有しますし、そこがとれない中では、大変慎重に、命に関係するようなことがあれば、すぐ連携しますけれども、その辺りは大変慎重になることになります。","voiceIndex":321,"id":"exchange-143"},{"speaker":"塚本委員","kind":"質問・要望","question":"あまり時間もないので、ハイブリッド授業は、どのぐらい実施されているものなのかということがまず第１点と、それから、教師が１人で教室で、教室にいる生徒を前にして授業をするのと、一方で、オンラインで配信をして、オンラインの先で授業を受けている子たちの両方をケアするというのは、なかなか現実問題としては難しいと、やらないよりはもちろんやったほうがいいと思いますけれども。","respondent":"中谷指導課長","answer":"その際の授業の仕方というところですけれども、例えば、ロイロノートというアプリケーションがありまして、これを使いながら、１つの教員が投げかけた問いに対して、クラスの中での子どもたちも考えると同時に、オンラインで参加してご自宅で見ているお子さんも一緒に考える。","voiceIndex":323,"id":"exchange-144"},{"speaker":"塚本委員","kind":"確認","question":"１つ確認したいのは、ＩＣＴ支援員は、こういったことに関しても協力を大いに得られるというところでしょうか。そこを最後にお伺いしたいと思います。","respondent":"勝亦学務課長","answer":"ＩＣＴ支援員につきましては、授業の構成ですとか、現場での授業の支援、そういったことにも従事をするような形で学校と協力をしております。","voiceIndex":325,"id":"exchange-145"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"その中で特に就学人口が増加したことは、子どもたちに対して学びの環境をつくるということで大変必要なことだということも理解しておりますが、例えば、１年生に入学した後で調査する中で、古い校舎なので行かなかったというような、そういう傾向はないのかどうか、その辺を確認をさせていただきたいと思います。そこら辺の関係で１回教えてください。","respondent":"勝亦学務課長","answer":"そういった中で、学校が新しいから選んだというものに関しましては、ランキングでいいますと、大体、小学校ですと４番目、お答えいただいている方の全体の３分の１程度の方が、そういったお答えをしていただいているところです。","voiceIndex":328,"id":"exchange-146"},{"speaker":"鈴木（真）委員","kind":"質問","question":"やはりどうしてもそういう状況は出てくると思うのです。以前ですと、小規模校に対して、ＩＣＴの特別支援的なものをやっていたと思うのですが、今、ＩＣＴが全校に配付されておりますので、そういう特別な支援というものがなくなっていると思うのです。何か小規模校に対してフォローするようなものは、教育委員会としては考えることはできないのかどうかお聞きしたいと思います。","respondent":"勝亦学務課長","answer":"かつては、そういったところに先行して１人１台タブレットを配布するような形にしてございましたが、今は全ての児童にタブレットが行き渡っている状況です。","voiceIndex":330,"id":"exchange-147"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"これは要望にしておきます。それと、おととい、１５日の日本経済新聞に出ていたのですけれども、「不登校２４万人の波紋」というような記事がありました。小学校で不登校となるケースもあり、幼保小の連携も重要だろうと。品川区ですと保幼小連携ということでやっていらっしゃいますが、教育委員会側から見て、小学校へ入るときにその成果が出ているかどうか、その辺のお考えをお聞きしたいと思います。","respondent":"矢部教育総合支援センター長","answer":"１年生、いろいろなお子さんがいますけれども、比較的順調に学校になじんできているのではないかと認識して、成果があると考えております。","voiceIndex":332,"id":"exchange-148"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"連携をぜひとっていっていただきたいと思います。ただ、この間、どうしても児童生徒に対して、どう生きるか、未来を切り開く力を育んでいくのか、その辺をうまく伝えていくために、どのように教育委員会としてお力添えいただいたか、一番の責任者という形で教育長の考え方、生きる力に対する思い、何かお言葉をいただければと思うのですが、お願いいたします。","respondent":"中島教育長","answer":"ご存じのように、一斉休校を端緒といたしますコロナの様々な対応、この中で子どもたちは、いろいろな制約を受けてまいりました。","voiceIndex":334,"id":"exchange-149"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1526#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":118705,"voices":337}},{"id":"r04-20221122-4","meetingId":"r04-c-settlement","date":"2022年11月22日","dateIso":"2022-11-22","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時５１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を117件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"初めに、町会・自治会について質問いたします。支援の中において、助成金・補助金のメニューも大変充実しておりますが、昨年の決算特別委員会でもお話ししました、補助金・助成金の整理や見直しについて、お聞きいたします。町会・自治会活動活性化促進調査の中で、補助金を利用していない団体、また補助金の使い方が分かりにくいとの声に対しまして、どのような改善を行っているのか教えてください。","respondent":"伊崎地域振興部長","answer":"それに加えて、「補助制度を知らなかった」、「申請の仕方が分からない」などのお声がないように、毎年４月の町会長・自治会長会議で改めて変更点等をご説明するとともに、日々、地域センターの職員や地域活動課の職員がご相談に応じ。","voiceIndex":2,"id":"exchange-001","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"確認","question":"ハンドブックの改定であります。町会長への周知も確認が取れました。濱野前区長がおっしゃっておりました。」とあります。品川区でもこのようなガイドラインを策定し、町会・自治会などの補助金の長期化・固定化する課題を解決するべきと考えますが、ご見解をお聞かせください。品川区に２０１もある町会・自治会。そこで、この課題に対し、品川区としてできること、やっていることを教えてください。","respondent":"伊崎地域振興部長","answer":"補助金の内容につきましては、先ほどもご説明いたしましたように、毎年、町会長・自治会長会議で丁寧なご説明を行い、その中で、また、あるいは日々の地域センターが町会の活動を支援する中で、ご意見、ご要望を伺い、ご利用状況も鑑みて、毎年、見直しを行ってきております。","voiceIndex":4,"id":"exchange-002","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問・要望","question":"毎年会議で、ガイドラインと同じようなことをやっているということを確認しました。そこでご要望があります。会館を所有していても、地代の値上がりで、会館を手放すべきではとの話合いが持たれるようになっております。新規に地代金を補助するような制度をつくっていただくことは可能なのか、ご見解をお聞かせください。","respondent":"伊崎地域振興部長","answer":"先ほど申し上げましたように、活動拠点の整備は非常に重要なことではありますが、現在、土地の購入費用は助成対象としておりませんので、公平性の観点などを考慮して、借地料の支援については、現在のところ困難であると考えております。","voiceIndex":6,"id":"exchange-003"},{"speaker":"松澤委員","kind":"質問・要望","question":"土地の公平性という部分で、今、助成金の考えはないというお話でしたけれども、いろいろ困っている町会もある中、ぜひ前向きなご検討を要望いたします。これは要望といたします。過去の議事録の中で、渡部委員長との質疑の中に、令和３年度１月から、乳幼児親子や小・中・高生を対象に、ニーズ、どんなところが欲しいかというアンケート調査をしたとありますが、どのような調査結果になったのでしょうか。","respondent":"柏原子ども未来部長","answer":"そういったところとの整合性と併せて、また保育園以外の施設と合築の場合も、そういった施設の事業といったところも考えながら、どういった児童センターを建て替えできるかといったところでの検討を今進めているところです。","voiceIndex":8,"id":"exchange-004"},{"speaker":"松澤委員","kind":"質問・要望","question":"児童センターの今後の在り方について幾つかご要望があります。１８歳以上への受入れ拡大についてのご見解をお聞かせください。児童センターに求められる機能は年々増加しており、１つで全ての施設を賄うのは相当なご苦労があるかと考えます。ですので、先ほどありました品川区の２５館ある施設の強みを最大限に活かし、機能の分散化を図ることはできないでしょうか。","respondent":"柏原子ども未来部長","answer":"１８歳以上の受入れの拡大の部分です。これにつきましては、現在、第２期品川区子ども・若者計画を検討しています。そうした中で、子ども・若者の活動拠点の整備といったところの必要性が取り上げられて、議論を今行っているところです。","voiceIndex":10,"id":"exchange-005"},{"speaker":"松澤委員","kind":"確認","question":"１８歳以上の受入れは、そういった議論がある、検討があるということを確認しました。施設の分散化です。現在、品川区にはこのような大型の室内遊び場というものはありませんが、ぜひ今後の児童センターの在り方について、検討してはいただけないでしょうか。改修計画の中におきまして、例えばこれらの施設を統合することも可能ではないでしょうか。ご見解をお聞かせください。","respondent":"柏原子ども未来部長","answer":"児童センターの在り方については多角的な視点が必要だというのは我々も認識していますので、今後、具体的に検討する中で、今頂いたご提案等を含めて、議論を深めていきたいと思ってあります。","voiceIndex":12,"id":"exchange-006"},{"speaker":"松澤委員","kind":"質問・要望","question":"たくさん要望いたしましたが、ぜひ検討の在り方の中で、本庁舎移転に伴う跡地活用の中でも大規模な児童健全育成施設が検討されることを要望しまして、次の質問に移ります。は避難所運営です。このようなシステムが確実に実施できるとなれば、避難所や物資の偏りを防ぐことができ、安否確認も迅速に行われるものと認識しておりますが、品川区としてどのように計画や方針を決めていくのか教えてください。","respondent":"滝澤災害対策担当部長","answer":"今後は、デジタルデバイドが叫ばれる中で、デジタル技術の入手が難しい方への対応につきましては、どのような方法がよいのか、当事者のご意見を聞きながら、災害時のみならず平常時からの対応について、区として検討を具体化してまいります。","voiceIndex":14,"id":"exchange-007"},{"speaker":"松澤委員","kind":"提案","question":"当事者の方の意見というのはとても参考になりますので、ぜひお聞きしながら、対応のお願いをしていただきたいと思います。ぜひ品川区でもこのような周知の取組みをすべきと考えますが、ご見解をお聞かせください。女性の視点を取り入れた避難所の運営モデル地区をつくることをご提案いたします。行政が一番初めに取組みに対応して、１つの成功事例を構築する。","respondent":"滝澤災害対策担当部長","answer":"過去の災害においても、女性の参加の有効性が多々言われているところでもあり、区でも避難所運営をはじめ、災害対策の様々な場での女性の参加が進むことが重要と考えております。今後、庁内の関係部署とも連携し、災害対策における女性の参加について周知を進めてまいります。","voiceIndex":16,"id":"exchange-008"},{"speaker":"松澤委員","kind":"確認","question":"二葉三丁目の女性参加率の多さというのは会報でも確認いたしました。ぜひ、そういった町会が増えていくことを望んでいます。次に、学校防災、教育防災についてお聞きいたします。初めに、教育委員会における防災教育とはどのように考えているのか教えてください。防災教育をどのように学習しているのかもお願いいたします。","respondent":"米田教育次長","answer":"防災教育についてお答えいたします。","voiceIndex":18,"id":"exchange-009"},{"speaker":"松澤委員","kind":"提案","question":"先月の１０月２７日、これは鈴ヶ森中学校において、「防災クリエイティ部！」という事業が開設されております。防災とデジタルを融合した新しい取組み。私は長く、学校を中心に防災の取組みを推薦していましたので、このような新事業を開催したことは、大変に評価が高いところです。そこで、１つご提案があります。新たな防災リーダーの育成に寄与するものと考えますが、ご見解をお願いいたします。","respondent":"滝澤災害対策担当部長、米田教育次長","answer":"今後についてですが、デジタルポスターや動画を生徒に作成していただき、今年度末の防災フェアでのお披露目を考えておりますとともに、今後、他の中学校などへの波及につきましても検討していきたいと考えております。私からは、地域防災部の発足についてのご提案を頂きました。地域の防災は、ポンプ隊などの具体的な防災活動の推進とともに、有事の際に協力し合えるよう、日常的な人と人とのつながりが肝要であると認識しております。","voiceIndex":20,"id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"前向きなご答弁、本当にありがとうあります。ぜひ、学校を中心とした活動が品川区中に広がりますように願いを込めまして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私からは、松澤委員に引き続きまして質問します。子ども政策の関係です。そして、こども政策の基本理念にのっとり、心身の発達過程にある子どもに関する施策を策定し実施する責務を有することが地方自治体にも求められています。品川区として、これらをどのように受け止め、施策、組織に反映させていこうとしているのか、お考えをお聞きしたいと思います。","respondent":"柏原子ども未来部長","answer":"こうしたことから、これから策定されるこども大綱やこども家庭庁の動向を見極めながらにはなりますけれども、今後の区の体制といったところの大枠は保ちながらも、国・都との連携といったところは機動的に連携できるように、やっていけるようにということで。","voiceIndex":25,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今お話がありました、こども大綱。そして、子ども・若者計画。次に、こども家庭庁の重点施策として、妊娠期と、０歳児から２歳児の支援と、子育てを切れ目なく支える伴走型支援、つながり続ける支援の強化も挙げられていますが、その点につきまして、区の現在の取組状況と今後どのように対応していくかについて、お考えをお知らせください。","respondent":"福内健康推進部長","answer":"国が挙げている伴走型支援につきましては、区で既に実施している部分も多くありますが、今後も、保健と福祉の連携を一層強化し、ネウボラネットワークをより充実してまいります。","voiceIndex":27,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"既にそれは我々も委員会でもお聞きしておりますし、保健と福祉の連携をこれからも進めていただきたいと思いますので、どうぞよろしくお願いいたします。次に、児童福祉法の一部が６月３０日に改正されました。区として、設置についてはどのように考えているのでしょうか。そして、検討状況をお聞きするとともに、現時点での課題などについて、お考えがあれば教えてください。","respondent":"柏原子ども未来部長","answer":"こども家庭センターの設置に向けての検討状況といったところです。こども家庭センターの定義といいますか、概要ですけれども、こちらはいわゆる区で今行っております子ども家庭総合支援拠点、これは区でいう子ども家庭支援センターになります。","voiceIndex":29,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今、最後にお話がありましたが、本当に名前が似ている。児童相談所が来年１月に竣工し、令和６年１０月の開設となりますが、児童相談所と子ども家庭支援センターの連携はどのように図っていくのでしょうか。さらに、新設されると思いますこども家庭センターとの関係の点についても、関連をもう一度お聞きしたいと思います。","respondent":"柏原子ども未来部長","answer":"そうした中で、連携のイメージといたしましては、区立の児童相談所が出来上がりますので、そこと子ども家庭支援センターとの関係ですが、例えば通告・相談の窓口、虐待等の通告の相談の一報の窓口については、一元化していきたいというふうなところもございまして。","voiceIndex":31,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今回のこども基本法の成立および児童福祉法が改正されたことにより、一時保護の司法審査導入、児童福祉に関する資格の創設などが関わってくると思いますが、影響についてはどのように想定されているでしょうか。児童相談所の所長や、意思決定過程を支える管理職を育てる必要があると思いますが、専門職のキャリアパス、要するに異動や昇進のルートについては、どのように考えていくのでしょうか。","respondent":"柏原子ども未来部長","answer":"ただし、子どもの安全を確実に確保する必要がある場合には、ちゅうちょなく一時保護が実施できるような判断の基準が整理されていると聞いておりますので、我々といたしましても、今後、児童福祉分野に精通した例えば弁護士であるとか、そういった方のご協力を頂いて。","voiceIndex":33,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"なぜ児童相談所をつくったのかという根本に帰るとそこにあると思いますので、その辺もご検討をよろしくお願いしたいと思います。こことの連携はどうなっていくのか。それともう一点、先日、１１月１２日に、養育家庭体験発表会が開かれたということが、この前、発表されていますが、里親の関係につきましても、これからどのように増やしていくのか、その点につきましてもお考えをお聞きしたいと思います。","respondent":"柏原子ども未来部長","answer":"後段でご質問がありました里親制度といったところの啓発等々でも連携ができないかということで、品川景徳学園とは今お話をさせていただいているといったところです。乳児院の関係です。","voiceIndex":35,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区立児童相談所の開設に対してはもちろん賛成していますが、財政上の負担が新たに発生してくると思います。設置に伴う直接的な費用規模をどの程度と試算されているのか、お聞きしたいと思います。既に開設されている５区の状況についてはいかがでしょうか。この辺につきましても、令和２年から、またその後進んでいない状況ですので、その辺の状況についても交渉状況について教えていただければと思います。","respondent":"柏原子ども未来部長、黒田財政課長","answer":"まだ検討段階ではありますけれども、区では、１年間のランニングコスト、これは人件費も含めてですけれども、１５億円程度かかるのではないかというところで試算をしています。配分割合について、改めて今年度、都区の財政調整協議を行いますが、特別区側は、児童相談所の設置につきましては、児童福祉法に基づく設置ということでありまして、都区の合意事項であります都と区の役割分担の変更に該当し。","voiceIndex":37,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"財政調整の問題はぜひ進めていただきたいと思います。品川区の令和３年度決算の財政調整が４５９億円でした。財政調整の協議は最近資料を見させていただいたのですが、特別区長会からも、財政調整の問題で、都議会議員に対して要望していくという話も聞いております。次に、子ども政策ということで、就学前教育について確認させていただきたいと思います。現状と今後の推進についてお考えを教えてください。","respondent":"柏原子ども未来部長","answer":"就学前教育の小学校へのスムーズな連携といったところでは、この事業は大切であると考えていますので、今後も工夫を図りながら、様々進めていければと思ってあります。","voiceIndex":40,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今おっしゃったスムーズな連携を図っていただくように、これからも大変厳しい状況の中、我々もなかなか学校に行きにくい状況ですから、連携を取るといっても、幼稚園・保育園とうまくタイミング的にも合わない、また控えてしまうようなことがあると思いますので、その辺のところ、しっかり注意を払いながら進めていっていただきたいと思います。","respondent":"柏原子ども未来部長","answer":"こういったことをやることによって、「情報交換をすることができて、保育の学びにつながった」、「地域や公園などでの危険な箇所の共有、事故防止対策を一緒に検討できた」というようなお声も頂いておりまして、こういったところで連携しながら。","voiceIndex":42,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あれはすごくいいなと思っていまして、その中で、どのように連携を取っているのかということも確認したかったので質問させていただきました。今の段階では分からないですが、子どもたちにとっていい方向に進められるような計画を検討していただきたいと思いますので、それを要望します。１つの課題は解消されておりますし、残る大きな課題は敷地ではないかと考えています。","respondent":"柏原子ども未来部長","answer":"今、委員からご指摘がありましたとおり、幼保連携型認定子ども園化に向けて検討を進めているところでございまして、２つの大きな課題の内一つ、事業者の社会福祉法人化という部分についてはクリアしたところでございまして、残るは。","voiceIndex":44,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぷりすくーるは、現状の人数的には、減らすことなく維持していただきたいと思うし、逆に言えば、広くできればもっと増やすことも考えられると思いますので、最初からというか、このテーマになるたびに、面積の問題、今、９０平米不足というお話がありましたけれども、この課題をどうやっても解消できない状況で今まで来ていますので、もうそろそろ次の対策を打っていただいて。","respondent":"中山会計管理者","answer":"これにより、品川区の財政状況や運営状況の見える化をすることができますので、行政経営マネジメント力の向上、あるいは区民の皆様への周知といったもの、説明責任の向上につながると考えています。","voiceIndex":46,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"今年もつくられています、「よくわかる！品川区財務諸表」ですか、あの資料もすごくコンパクトにまとめられているのですが、やはりなかなか分かりにくいので、これからも分かりやすい形を進めていただきたいと思って、検討をよろしくお願いします。そこで、これまでの区の行政評価、事務事業評価の取組みについてお聞かせください。私は実施すべきと考えますが、その目的と活用についてお聞きします。","respondent":"久保田企画部長","answer":"併せまして、実施を通して、職員の業務改善への動機づけにつながるような手法についても検討してまいります。","voiceIndex":48,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ぜひ実施をお願いしたいと思います。もう一点、平成２７年度に策定されました品川区総合戦略におきまして、総合戦略推進委員会による評価が行われています。総合戦略における事務事業評価はどのように行われたのでしょうか。今後の取組みについてもお聞きしたいと思います。","respondent":"久保田企画部長","answer":"事務事業評価を通して事業の見直しを行いまして、効率的・効果的な行政運営を推進することにより、総合戦略の目標の実現に向けて取り組んでまいりたいと考えているところです。","voiceIndex":50,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"最後に、予算関係についてです。物価高騰は今も引き続き話題になっております。大変厳しい生活環境の中で、区として、区民や各種事業者に対してどのような物価高対策を考えているのか。そして、区の物価高対策の財源としては、新型コロナウイルス感染症対応地方創生臨時交付金が活用できると思いますが、現在の活用状況をお聞きしたいと思います。","respondent":"久保田企画部長","answer":"残りの７億３,８００万円が、今後の追加支援対策に活用できるものと考えております。","voiceIndex":52,"id":"exchange-025"},{"speaker":"鈴木（真）委員","kind":"意見","question":"第２回定例会で支援の補正が組まれて、子育てサポートにしてもよかったのですが、１歳・２歳を対象にした中で、どうしてもそれ以外のお子さんをお持ちの方にも枠を広げてほしかったという希望もありました。特に燃料費価格の高騰は、流通部門など様々な業種に影響を及ぼしていると考えますが、どのようにお考えか、お答えをお願いしたいと思います。","respondent":"久保田企画部長","answer":"新しい区長の方針の下、各種支援策を推進していきたいと考えているところであります。","voiceIndex":54,"id":"exchange-026"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区長がいない中で大変だと思いますが、ぜひ支援を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-027"},{"speaker":"つる委員","kind":"質問・要望","question":"初めに、新型コロナウイルス感染症の罹患後症状、いわゆるコロナ後遺症の対応についてお尋ねいたします。現在、感染状況は増加傾向が続いており、東京都は４段階で表す感染状況の警戒レベルを、上から２番目へ１段引き上げました。第８波の入り口に差しかかっているとの指摘もあり、引き続き、感染防止対策とともにワクチン接種の促進が求められます。","respondent":"福内品川区保健所長","answer":"相談件数は多くはない状況です。後遺症対応医療機関は区ホームページでも公表しておりますが、区内には非公開の医療機関も含め２４か所あり、上咽頭擦過療法を実施している医療機関は、現在把握しているところで２か所です。","voiceIndex":58,"id":"exchange-028"},{"speaker":"つる委員","kind":"質問・要望","question":"後遺症によって、就職活動や外出もままならない方もおり、コロナ感染と同様の行政手続きにおける様々な対応も求められ、区民からも安心できる対応を求める声が届いています。品川区でも後遺症の専門医を招いての講演会を開催してはいかがでしょうか。さらに、後遺症によって各種行政手続きが困難な方への寄り添う対応を求めますが、ご見解をお知らせください。","respondent":"福内品川区保健所長","answer":"後遺症により行政手続きが困難な方へは、その方の身体等の状況に応じて対応や援助が必要となると考えており、寄り添った丁寧な対応に努めてまいります。","voiceIndex":60,"id":"exchange-029"},{"speaker":"つる委員","kind":"提案","question":"場合によっては数年から一生付き合っていかなければならない実態もあることから、引き続き、ワクチン接種の推進とコロナ後遺症患者への支援の充実を重ねて要望いたします。次に、子育て支援関連についてお尋ねいたします。そこで、過去の質疑で、在宅子育て支援に関連して部署の整理等を提案していましたが、こども家庭庁発足に際して、区における施策横断での司令塔はどこになるのか。","respondent":"柏原子ども未来部長","answer":"組織的なところで申しましても、こども家庭庁の動きや法の動きというのは、もう少し詳細が見えてきたところで、今の枠組みは大きく変わらないにしても、そうしたところに対応できる機動的な組織というのも必要であろうと思ってありますので。","voiceIndex":62,"id":"exchange-030"},{"speaker":"つる委員","kind":"意見","question":"そこで、こども家庭センターの設置に向けた区の検討状況や、現在の体制からどのような点が強化・拡充されるのか、お知らせください。","respondent":"柏原子ども未来部長","answer":"こちらの設置に向けて、区といたしましては、どういった連携をしなくてはいけないか、どういった体制を取らなくてはいけないのかといった検討を行っているといった状況です。","voiceIndex":64,"id":"exchange-031"},{"speaker":"つる委員","kind":"意見","question":"訪問による生活支援として、子育て世帯訪問支援事業が新設され、要支援児童、要保護児童およびその保護者、特定妊婦等、また支援を要するヤングケアラーも含んだ世帯を訪問し、子育てに関する情報の提供、家事・養育に関する援助等を行うことが示されています。そこで、現在の養成人数と、同事業の担い手として連携が可能か、お知らせください。","respondent":"柏原子ども未来部長","answer":"今後の国の事業との連携といったところです。区では既に養育支援訪問事業といったところを行ってあります。こういったところでの拡張といったところで、子育て世帯訪問支援事業というのは活用できるだろうと思ってございまして、その部分について検討を進めているところです。","voiceIndex":66,"id":"exchange-032"},{"speaker":"つる委員","kind":"質問・要望","question":"その周知文書には、「産婦とは出産後１年以内の女子。この取組みに対して、周産期のグリーフケアを担う団体から称賛の声が寄せられていると伺いました。現在、区が実施している１万円のカタログギフトの贈呈についても、流産をされた方も対象であることを東京都の担当者に確認済みであり、総合経済対策で実施予定の妊娠時の５万円相当の給付についても対象であると認識しています。","respondent":"福内健康推進部長","answer":"総合経済対策の給付につきましては、国からの通知等を確認し、記載について検討してまいります。次に、流産等をされた方への支援につきましては、今年度、保健センターで、ネウボラ相談員や保健師等を対象に、グリーフケアをテーマに研修を実施する予定としています。","voiceIndex":68,"id":"exchange-033"},{"speaker":"つる委員","kind":"質問","question":"学校給食の無償化に関連してお尋ねいたします。地方創生臨時交付金を活用した給食費の値上げ抑制策が２学期・３学期で実施され、保護者からは喜びの声を受けております。国の総合経済対策が示されていますが、来年４月以降の給食の値上げ抑制については示されておりません。そこで、区としての物価動向の現状認識と、区独自の抑制策についてのお考えを伺います。","respondent":"米田教育次長","answer":"区としても同様の見通しを持っております。来年度の区独自の給食費の負担抑制策につきましては、こうした物価、景気の状況や交付金など、国の施策等の動向も踏まえて、十分に検討を進めてまいります。","voiceIndex":70,"id":"exchange-034"},{"speaker":"つる委員","kind":"質問・要望","question":"給食費の無償化については、公明党は国会の場でも議論をリードし、２０１７年の国としての学校給食無償化のアンケートの実施や、２０１９年には保護者負担軽減に向け、「給食無償化に向け、国として自治体に対するインセンティブを検討する」との答弁を文部科学大臣より引き出し、また区議会においても、無償化の実現に向けた方向性を確認しました。","respondent":"米田教育次長","answer":"現在の課題といたしましては、無償化に伴う区の食材費への財政的な負担を年間約１３億円余と見込んでおり、継続的に財源の確保が必要となることが第１に挙げられます。","voiceIndex":72,"id":"exchange-035"},{"speaker":"つる委員","kind":"提案","question":"環境文化に関連してお尋ねいたします。ＳＤＧｓや環境の視点など、区民への取組みのきっかけ・促進として、サステナブルファッションショーやパネルディスカッションの開催を求め、提案してきた、エシカル消費のイベントについては、コロナ禍でも実施していただきましたが、ウィズコロナのイベント展開、オンラインの活用など、民間も行政もノウハウを蓄積したと認識しています。","respondent":"中村都市環境部長","answer":"次世代を担う若い世代が意欲的に関われますように、アパレル業界のオピニオンリーダーの活用を想定したエコルとごしでの環境イベントや講座の活用など、今後もサステナブルファッションショーの開催に向けて、引き続き検討を進めてまいります。","voiceIndex":74,"id":"exchange-036"},{"speaker":"つる委員","kind":"質問","question":"ぜひ、若い世代の声をしっかりと聞いていく、共に一緒に行動を起こしていくという区の姿勢も大事かと思います。その他質問させていただきましたことは未来における品川区にとって大変重要なことだと認識しておりますので、それぞれ積極的な推進をお願いいたしまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-037"},{"speaker":"若林副委員長","kind":"質問・要望","question":"各会計の決算概況などをお聞きいたします。令和３年度一般会計は、当初予算に加え、９回の補正予算も組み、諸課題に対応されました。公明党は特に新型コロナウイルス感染症対策に力点を置き、６回の緊急要望を濱野前区長に行いました。そこで何点かお聞きします。前年度１３５億円の基金を取り崩したことの影響も含め、財政の健全性の説明をお聞きします。ワクチン接種の拡充も確認させてください。","respondent":"黒田財政課長、福内健康推進部長、今井福祉部長、秋山保健整備担当部長","answer":"５月の臨時会の補正予算第２号において、高齢者・障害者の移動にかかる交通費の支援、第２回定例会の補正予算第３号において。国民健康保険事業会計の歳入につきましては、保険料の納付方法に電子マネーの拡充や口座振替一括納付を開始するなど、財源の確保に努め。引き続き、歳入では保険料の収納率の維持、歳出では、できる限り住み慣れた我が家で暮らすという目標の下、サービス提供に努めるなど。","voiceIndex":78,"id":"exchange-038"},{"speaker":"若林副委員長","kind":"質問・要望","question":"港区の高齢者補聴器購入費助成事業を調査してまいりました。そこで、厚生労働省の研究の内容と、港区モデルと言われる当事業の特徴をお知らせいただきたいと思います。","respondent":"今井福祉部長","answer":"２点目は、購入した補聴器の適切な使用を継続するための支援としまして、購入前の補聴器専門医による診断や、購入時は認定補聴器技能者からの購入という条件設定をしています。３点目としては、このような全体の取組みが充実したものになっているという認識です。","voiceIndex":85,"id":"exchange-039"},{"speaker":"若林副委員長","kind":"質問","question":"第２回定例会のご答弁では、正しい知識の普及・啓発に医療機関や業界団体との連携が重要であること、その上で、購入費助成の実施に取り組むと示されました。そこで、医療機関、販売団体との連携を現在どのように進めているかお聞きします。利用者の声、制度や補聴器の満足度、フォローアップといった効果検証が行える仕組みのお考えをお聞きいたします。","respondent":"今井福祉部長","answer":"ただ、こちらも現在、関係機関からの助言を頂きながら、仕組みを十分に検討していきたいと考えています。しっかりと情報共有・交換をした上で、耳の聞こえに関する普及・啓発を進めていくとともに、課題を関係機関と共有してまいりたいと考えております。","voiceIndex":87,"id":"exchange-040"},{"speaker":"若林副委員長","kind":"提案","question":"日本補聴器工業会が行った２０１８年の大規模調査により、様々なデータが明らかになっています。助成については、改めて実施に向けた取組みを要望いたしますが、この事業の肝は、補聴器相談員による診断と、認定補聴器技能者が補聴器のフィッティングを行える仕組みづくりであります。そこで、企画会議の目的や目標をお聞きし、２回を終えての感想と今後の地域連携等の展開のお考えをお聞かせください。","respondent":"今井福祉部長","answer":"初めに、補聴器の購入助成に向けての、各医療機関、そして補聴器販売団体との連携につきましては、やはり、今ご紹介いただきました日本補聴器工業会や日本補聴器販売店協会など、様々な団体がいらっしゃること、それから。","voiceIndex":89,"id":"exchange-041"},{"speaker":"若林副委員長","kind":"質問","question":"妊娠から出産、育児の、切れ目のない支援をお聞きします。品川区の取組みを進めるに当たり、今回は妊娠期から０～２歳児に対象を絞り、現状や課題に対する現時点でのお考えをお聞きいたします。８点にわたりお聞きいたします。複数のサービスを利用した場合の担当者間の連携や情報共有、またマネジメントの仕組みについて、現状と課題はいかがでしょうか。","respondent":"福内健康推進部長、柏原子ども未来部長","answer":"妊婦面接は、妊婦全員を対象に面接を行い、母子保健、子育て情報の紹介や相談対応をしており、８名の助産師が従事しています。こういった児童福祉分野と母子保健分野の連携・協力体制というものを取ってきてありますけれども、ここに国が打ち出しています伴走型支援、相談支援というものを、さらに、そしゃくといいますか、理解しながら、各課題を整理して。","voiceIndex":91,"id":"exchange-042"},{"speaker":"若林副委員長","kind":"質問・要望","question":"先に進めます。屋外の喫煙対策をお聞きいたします。款別審査でも多くの質疑があり、路上喫煙対策と喫煙所の整備が区民から求められております。路上喫煙禁止地区の内外でポイ捨て本数のカウントを始めていることも伺いました。そこで、令和３年度以降の取組みをお聞きします。ポイ捨て本数のカウントの目的と今後の対策への活用をお聞きいたします。","respondent":"伊崎地域振興部長","answer":"そこで、コンテナ型の設置を検討いたしまして、立地的に可能であるということが、関係者の協議で調いましたため、現在こちらの設置を進めているところです。","voiceIndex":94,"id":"exchange-043"},{"speaker":"若林副委員長","kind":"質問","question":"水辺とまちのにぎわいをお聞きいたします。そこで、舟旅通勤の目的・成果と、区内舟運の活用を含めた今後の展望・展開をお聞きいたします。そこで、星野リゾート等による企画の内容と、地域のまちづくりビジョンや区の関わりをお聞きいたします。旧ゆうぽうと跡地開発を契機に、一層のにぎわいづくりのお考えをお聞きします。もう一点。この事業のスキームと、東京都との協議の考えをお聞きいたします。","respondent":"稲田防災まちづくり部長、山崎文化スポーツ振興部長、有江都市整備推進担当部長","answer":"重ねて、区は日頃から東京都に対しまして申入れをしています。今後も引き続き継続して要請を行ってまいりたいと考えております。そこに、関係協力の事業者への働きなども含めて、今後、様々、研究・検討してまいります。五反田駅周辺にぎわいゾーンまちづくりビジョンや、区との関わりについてですけれども、まちづくりビジョンでは、地元の商店街や住民、企業、区など。","voiceIndex":96,"id":"exchange-044"},{"speaker":"若林副委員長","kind":"質問・要望","question":"最後に、学校老朽化に関連し、お聞きいたします。学校改築が進む一方、未改築校の環境整備も進められ、その一つとして、体育館の舞台照明の更新があります。今年度は、立会小学校、浅間台小学校の２校で工事が行われました。そこで、地域ごとの改築済みと未改築の学校数をそれぞれお知らせください。最後に、未改築の学校への整備は、可能な限り早期に行うよう要望いたしますが、ご見解を伺います。","respondent":"米田教育次長","answer":"最後に改築の関係ですが、総合実施計画に基づきまして、令和６年度までは年１校のペースにて改築を進めてまいりたいと考えています。以降のペースにつきましては、改築に要する経費等、社会情勢なども鑑みながら検討を行ってまいりたいと考えています。","voiceIndex":100,"id":"exchange-045"},{"speaker":"若林副委員長","kind":"質問","question":"すみません。最後の質問は、未改築校の学校の整備というのは、舞台照明のお話、角度でお聞きしていました。いずれにいたしましても軽量、従来の５分の１程度の重さとも伺っておりますので、安価というところもあります。そのほか、しゅんせつの問題、それから妊娠から出産の問題等々、また今後しっかり公明党としても取り組んでまいりますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-046"},{"speaker":"おくの委員","kind":"質問・要望","question":"そういう中、「これから１０年後、２０年後、未来にわたり、品川区民の安心安全な生活と命を守るために、早急に新ルートの運用停止を求める意見書を国に提出することを町会長とともに求めます」とする請願が区議会に提出されました。区は、この請願をどのように受け止めているのでしょうか。伺います。そして、町会長会議で、国土交通省が羽田新飛行ルートについて説明を行っていると伺いました。伺います。","respondent":"中村都市環境部長","answer":"国は町会その他地元への説明につきましては、これまでオープンハウス説明会やニュースレターの発行など様々行ってまいりましたけれども、その都度、町会長会議や、あと区内全域の１３地域の町会長会議で周知が行われてきたところです。","voiceIndex":105,"id":"exchange-047","title":"町会・自治会支援"},{"speaker":"おくの委員","kind":"質問・要望","question":"町会長会議での説明について、いつどのような形で何回行ってきたかと伺いましたので、その点の説明が、お答えがなかったように思います。具体的にお答えいただきたいのですが、いかがでしょうか。","respondent":"中村都市環境部長","answer":"したがいまして、回数自体、何回というのは詳しく覚えておりませんけれども、それぞれの地域センター毎に、１３地域センターというところで説明を行った中で、運用開始前は各地域センター辺りで３回から４回／毎、それから運用開始後におきましては。","voiceIndex":107,"id":"exchange-048","title":"町会・自治会支援"},{"speaker":"おくの委員","kind":"質問・要望","question":"私はそれを非常に大事にしたいと思います。そこで、２点伺います。区は運用停止を求めたことは、これまでに一度もないのではないかと思いますけれども、その点はいかがでしょうか。それから第２点、区は重く受け止めるというのなら、また願いの強さが背景にあるのですから、やはり運用停止を国に求めるべきだと思うのですけれども、この点はいかがでしょうか。","respondent":"中村都市環境部長","answer":"その結果、固定化回避検討会が設置されました。この固定化回避検討会では現在、区の求めに応じまして検討が行われている最中と認識しております。令和４年８月３日に最新の検討会が開催されまして、その中でリスク評価などの検討が行われていることが公表されております。","voiceIndex":109,"id":"exchange-049"},{"speaker":"おくの委員","kind":"質問・要望","question":"固定化回避を求めていくというご答弁でしたけれども、結局、この検討会で検討されている新しい飛行方式を取っても、着陸の直前は滑走路に向かって一定の距離を直線で飛ぶことがどうしても必要になるのは間違いないことですから、品川区の上を飛ぶことにはどうしてもなってしまいます。やはり請願に真正面から応えて、国に対して新ルートの運用停止を求めるべきだと思います。伺います。伺います。伺います。","respondent":"有江都市整備推進担当部長","answer":"ただいまのご質問にお答えいたします。武蔵小山パルム駅前地区再開発の概要ですけれども、総事業費が約４６０億円、区補助金約１０１億円、高さ約１４２メートル、地上４１階、地下２階建ての建物でございまして、総戸数は６２４戸です。","voiceIndex":111,"id":"exchange-050"},{"speaker":"おくの委員","kind":"質問","question":"それなのに、従来の店舗数すら把握されていない。そのうち、再開発で建てられた建物に入って営業しているのは四、五店舗にすぎないのではないかというように、近隣の方からも伺っております。伺います。それから、この地域コミュニティが壊れてしまったかなども含めた、数字だけではない、再開発が住民や店に及ぼしている影響を把握すべきではないかと私は思うのですが、この点はいかがでしょうか。伺います。","respondent":"有江都市整備推進担当部長","answer":"再開発事業を進めるに当たっては、商店街の振興組合と連携を図りながら、周辺のにぎわいの継続についても検討するため、区も情報共有の場を設置しながら進めておりまして、今後も引き続き継続して行ってまいりたいと思います。","voiceIndex":113,"id":"exchange-051"},{"speaker":"おくの委員","kind":"質問・要望","question":"私はもう少し把握して、再開発地域の住民に心を寄せていただきたいと思います。次へ行きたいと思います。そこで伺います。既に完了した、先ほどの２つの地区の超高層マンションの総床面積、それから権利床の面積、保留床の面積はそれぞれ幾らだったでしょうか。デベロッパーは保留床を幾らで売却して幾らの利益を上げたのでしょうか。伺います。","respondent":"有江都市整備推進担当部長","answer":"武蔵小山パルム駅前地区の総床面積ですが、約７万５,０００平米です。武蔵小山駅前通り地区の総床面積ですが、約５万３,５００平米です。権利床の面積、保留床の面積につきましては非公開でございまして、保留床の売却額や売却益につきましても把握はしておりません。","voiceIndex":115,"id":"exchange-052"},{"speaker":"おくの委員","kind":"質問","question":"先ほど伺った総事業費４６０億円から、区の補助金１０１億円を引くと、三井不動産レジデンシャルが手にする、事業者が負担する分の３５９億円という額が試算できます。結局、デベロッパーのもうけをつくり出すために、税金から補助金を出して行っているのが、再開発ではないのでしょうか。伺います。そしてまた、こうした再開発はやめるべきだと思いますけれども、いかがでしょうか。伺います。","respondent":"有江都市整備推進担当部長","answer":"再開発は、都市計画の観点からも、必要性、緊急性、公共性が高い地区で実施されるものでありまして、適正な補助金を交付し、事業が実施されるものです。そのため、開発企業の利益を増すためのものとは考えてございません。","voiceIndex":117,"id":"exchange-053"},{"speaker":"おくの委員","kind":"質問","question":"デベロッパーのもうけを保障するためにそのようなマンションが必要になるのであって、そのもうけのために地域コミュニティを壊し、住民を追い出すような再開発は中止すべきだと思います。そのことを申し上げて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、障害者福祉と広町開発、新庁舎建設問題について伺います。初めは障害者福祉についてです。障害者権利条約についての区の認識、区の障害者福祉政策への位置づけを伺います。区として、障害者福祉に携わる区の職員研修に、障害者権利条約を学ぶことを位置づけるべきだと考えますが、いかがでしょうか。勧告・総括所見では、障害者福祉の予算面も含め、抜本的な改善が求められています。","respondent":"今井福祉部長","answer":"内閣府の障害者政策委員会において審議中の障害者基本計画に反映されるものと認識しております。区としましては、国の基本計画等を確認の上、令和５年度に策定予定の障害福祉計画などに反映してまいりたいと考えております。","voiceIndex":121,"id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、これを基本にして、品川区としても障害者福祉を進めていただけるように求めておきたいと思います。示されているものは、多くが２３区で最低水準という実態となっています。これは品川区だけです。こういう実態は、新しい区長の下で早急に改善が必要だと思いますが、いかがでしょうか。障害者福祉の予算の抜本的引上げを求めます。いかがでしょうか。","respondent":"今井福祉部長","answer":"現在、令和３年７月に改定いたしました第６期品川区障害福祉計画および第２期品川区障害児福祉計画の中で、ニーズの見込みなどを確認しつつ、グループホームの整備等を進めているところです。","voiceIndex":123,"id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者権利条約に、私はほど遠い実態だと思います。そして品川区は、２３区の中でも大変、障害者福祉が遅れているという実態です。改めて抜本的な改善を求めたいと思います。そして具体的に、今回は、救急代理通報システムとグループホームについて伺います。救急代理通報システムについてです。その仕組み、対象者、利用料、１人にかかる費用を説明してください。","respondent":"今井福祉部長","answer":"令和３年度に年齢制限を廃止したところです。利用料は、非課税世帯が月に１００円、課税世帯が月に１,０００円、１人にかかる経費につきましては、非課税世帯が月に２,８３０円、課税世帯が月に１,９５０円です。","voiceIndex":125,"id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この間、人工呼吸器をつけた方のお母さんから、自分が突然倒れたときに子どもがどうなってしまうか心配でたまらないとの相談を受け、重度障害者の世帯への対象拡大と利用料の無料化を求めてきました。介護者が倒れたら、障害者にとっても命の危険にさらされることになることについて、どう考えるのかについても伺いたいと思います。","respondent":"今井福祉部長","answer":"介護者の皆様の不安を軽減する方法につきましては、１例を挙げますと、ショートステイ利用の方法等もありますので、個別にご相談をお受けする中で、検討して対応してまいります。","voiceIndex":127,"id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者を含めたニーズというのは全く分からないのでしょうか。それから私は、介護者が倒れたら、障害者にとっても命の危険にさらされることになるのではないかということもお聞きしましたので、答えていただきたいと思います。介護者が１人で生活しているわけではないのです。必要性について認めるのかどうかも伺いたいと思います。障害者も対象を広くしていただきたいと思いますが、いかがでしょうか。","respondent":"今井福祉部長","answer":"救急代理通報システムにつきましては、重度の緊急事態のリスクの高い方を優先しており、繰り返しになりますが、ご本人の不安を解消することを主の目的として事業を展開しておりますので、現時点で介護者の方を含めた対象に広げる考えはございません。","voiceIndex":129,"id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私が伺っているのは、介護者の不安の解消のためではなくて、介護者が倒れたら、その介護者が見ている方の命に関わる問題なのだということで訴えているのです。そのことの必要性については認められるのかどうなのか、そのことについて答えがないのでお願いします。","respondent":"今井福祉部長","answer":"救急代理通報システムの介護者の方も含めた配置ということですけれども、先ほどから繰り返しになりますけれども、障害者ご本人のところには設置しておりますので、今、現時点でのところでは、介護者の方への必要性については、今のところは考えておりません。","voiceIndex":131,"id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"介護者の不安ではないのです。私は改めて、一日も早くこのことの必要性を認めて、実現を強く求めておきたいと思います。利用料についてです。利用料の徴収は、受益者負担の観点から無料とすることは考えていないということでしたけれども、法律の考え方と矛盾するのではないかと私は思いますが、伺います。今回の私の一般質問で、利用料は検討中との答弁でしたが、受益者負担の考え方を変えるのか、伺います。","respondent":"今井福祉部長","answer":"ただし、救急代理通報システムにつきましては、地域生活支援事業の任意事業に位置づけられております。地域生活支援事業の利用者負担につきましては、国の実施要綱に基づき、実施主体の判断によるものとされておりますが、利用料については引き続き検討しているところです。","voiceIndex":133,"id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、障害者のサービスというのは権利保障だと思うのです。私は、受益者負担という考え方はやめていただいて、ぜひとも救急代理通報システムの利用料は無料にということで、改めて求めておきたいと思います。次に、障害者のグループホームの増設について伺います。施設入所者のうち、北海道と東北に入られている方の人数も教えてください。区は何人分の増設が必要と考えているのかの数もお聞かせください。","respondent":"今井福祉部長","answer":"今後、障害福祉計画にも、ニーズ量が令和４年度は２１８人分ということで、今、記載しているところですので、それと現在の実際のグループホームの定員が１３９人ですので、依然、７９人の方が計画上は必要だということですが、先ほど申しましたとおり、相談支援事業所からは。","voiceIndex":135,"id":"exchange-062"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"区外に入られている方が３５６人もいるわけです。こういう形で、何らかの理由で通所施設に通えなくなった方に、通所できるための寄り添った支援が必要ではないかと思いますが、いかがでしょうか。どのような支援をされているのかも伺います。遠くの施設に入らざるを得ない。そして、グループホームは、計画を立てて、きちんと入れるような形で計画を持つことが必要だと思いますが、いかがでしょうか。","respondent":"今井福祉部長","answer":"引き続き、整備を着実に進めてまいります。","voiceIndex":137,"id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、それではとてもとても足りないと思います。勧告でも、これから出されて、しっかりとその受皿をつくるためにも計画を立てて、グループホームの増設を求めたいと思います。次の質問、広町開発と新庁舎建設について伺います。この間、税金を投入して、ＪＲと日建設計に委託して行ってきた、広町地区開発構想に向けた検討、広町地区整備検討について、検討の期間と年数、投じた税金の総額を伺います。","respondent":"有江都市整備推進担当部長","answer":"まちづくりの検討については、土地再編を含めた地区全体のまちづくりの方向性を検討するためのＪＲとの共同検討と、区有地の再編に係る土地利用の検討を行うための単独検討の、２つの異なる目的の委託等を相互に連携させながら、関係者と協議しつつ、検討を進めてきたところです。","voiceIndex":139,"id":"exchange-064"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"膨大な資料を共産党が情報公開で取りましたが、ここのパネルで示しているように、９９％が黒塗りです。非公開。そして、丸ごと非公開で、報告書が何ページあるのかさえ分からないという状況です。ここで、この公開についてですが、区民に対しては全て非公開という状況ですが、この資料はいつか公開されるのか、また公開されるとしたらいつなのか、また公開されないものがあるのか、伺いたいと思います。","respondent":"有江都市整備推進担当部長","answer":"情報公開につきましてですけれども、主に２点あります。１点目ですけれども、区民の皆様にご説明をしたりご意見を頂くための素案を作成する準備段階のものであり、公開することで区民の皆さんの間に混乱を生じさせるおそれがあると認められることから非公開としたものです。","voiceIndex":141,"id":"exchange-065"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それが、今、答弁されたことなのかなと思うのですけれども、新庁舎の基本条件の整理、４０ページ丸々非公開。４のにぎわい施設の基本条件の整理も２０ページが丸々非公開。伺いたいと思います。それから、にぎわい施設の基本計画案の業務検討も委託されていると思いますが、どんな報告書が来ているのか、伺いたいと思います。にぎわい施設とはアリーナとしての基本計画案の検討なのかも伺います。","respondent":"有江都市整備推進担当部長","answer":"黒塗りにされた理由ですけれども、新庁舎の計画につきましては、令和元年に、土地再編による広町敷地への区庁舎移転に向けての検討を進めると、行財政改革特別委員会でご報告して以降、機能検討、基本構想、基本計画と、それぞれ区民の意見を聞きながら検討を進めてまいりました。","voiceIndex":143,"id":"exchange-066"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"その中身がどうなのかということは答えていただけるのか。そのことも伺いたいと思います。それは、土地交換から超高層の庁舎ありき、現区庁舎跡ににぎわい施設アリーナ建設など、大枠を全てＪＲと品川区は決めてしまったということではないのか、伺いたいと思います。そして、大枠を決めたところで、初めて区民参加の装いを取ったのではないか、伺います。","respondent":"有江都市整備推進担当部長","answer":"にぎわい施設の件につきましては、繰り返しになりますけれども、区の中心区画である大井町エリアのさらなるにぎわい向上のため、多くの集客が可能な多目的な施設が必要と考えて検討してきたものです。","voiceIndex":145,"id":"exchange-067","title":"町会・自治会支援"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、ＪＲと品川区が広町開発と一体に検討してきたために、庁舎建て替えがゆがめられた結果の産物が、超高層の庁舎とアリーナ建設ではないかと思います。庁舎建て替えは白紙に戻し、広町開発と切り離して、現庁舎と土地交換をした合計２万２,０００平米の敷地を使って、区民参加で災害に強く、そして住民自治を位置づけた新庁舎を検討し直すべきと強く求めて、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-068"},{"speaker":"木村委員","kind":"質問","question":"イノベーションしながわを代表して、令和３年度の総括質疑を行います。最初に、令和３年度の災害復旧特別会計からです。本区のお考えをお聞きしたいのと、過去にはどのような被害があり、どのような爪痕を残していったのでしょうか。本区はいざというときのために準備はできているのでしょうか。分かりやすく明確にお答えを頂きたいと思います。","respondent":"滝澤災害対策担当部長","answer":"区では、このような過去の災害の教訓などを踏まえて、災害の未然防止、災害発生時の被害の拡大防止、災害の復旧・復興のそれぞれの段階において、公助と自助、共助の役割分担を具体化するとともに、品川区地域防災計画を随時見直すことにより、国、東京都、関係機関だけではなく。","voiceIndex":149,"id":"exchange-069"},{"speaker":"木村委員","kind":"質問","question":"大きな被害をもたらすのは、やはり地震とか大雨、それから火災等が考えられますけれども、行政としてはどのようなことを一番心配しているのか。ほかにあるとすれば、どのようなことが考えられますか。区民に対し、常日頃から行っている防御体制、安全に命を守るには、どのような訓練が必要で、どのような指導を行っているのでしょうか。お知らせください。","respondent":"滝澤災害対策担当部長","answer":"このため、区民に対しては、一人一人が主観的に災害リスクを認識し、それぞれの方が実施できる自助訓練を具体化していきたいと考えております。","voiceIndex":151,"id":"exchange-070"},{"speaker":"木村委員","kind":"意見","question":"有事になれば、我々人間はパニックを起こして、逆に被害を大きくしてしまう可能性が大いにあるでしょうし、いざというときのために、行政としては、どのような訓練がやはり必要と考えますか。その点のお考えをお聞かせください。","respondent":"滝澤災害対策担当部長","answer":"先ほど、自助訓練の具体化という話をいたしましたが、併せて共助につきましても、避難行動要支援者に対する支援など、地区ごと、マンションごとの特性をそれぞれ主観的に分析し、それぞれが実施すべき共助訓練を実施していただくことが必要と考えております。","voiceIndex":153,"id":"exchange-071"},{"speaker":"木村委員","kind":"質問","question":"１９９５年１月１７日に起きた阪神・淡路大震災、２０１１年３月１１日の東日本大震災など震度７を記録しました。ある程度の被害を想定し、準備をしておかなければいけませんが、現在の本区の準備状況は、最低限を想定しているのか、それとも最大限を想定しての準備なのか、どのようになっているのでしょうか。お聞かせください。","respondent":"滝澤災害対策担当部長","answer":"死者３００人弱、負傷者約４,５００人の人的被害を出し、避難所避難者も８万７,０００人を超える数と想定されております。区といたしましては、東京都の被害想定を踏まえた対応が確実に実施できる体制を整えてまいる所存であります。","voiceIndex":155,"id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"何よりも大事なこと、絶対に守らなければいけないことは、やはり人の命です。多くの命を守るためには、どのようなことに注意し、どのような準備が必要でしょうか。その準備ができていると思いますけれども、その準備とは、各家庭なのか、それとも巨大なビル群なのか。何とお考えでしょうか。お聞かせください。","respondent":"滝澤災害対策担当部長","answer":"区では、このような自助・共助の取組みをしっかりと支援するとともに、公助との役割分担を具体化し、それぞれがそれぞれの役割を果たすことで、より災害に強いまち品川区を築くための施策を推進してまいります。","voiceIndex":157,"id":"exchange-073"},{"speaker":"木村委員","kind":"意見","question":"ぜひ、あらゆることを、あらゆる有事のための準備をお願いしたいと思います。次に、衛生手数料の中の獣医衛生手数料、令和２年度収入済額が８９９万円余、令和３年度の収入済額が９１８万円余からですけれども、令和２年度とほぼ同額のこの事業、４つの項目があります。これですと、１頭に何度も注射することになりますけれども、ご説明を願いたいと思います。","respondent":"福内健康推進部長","answer":"決算書の犬の登録数は、令和３年度の新規登録数であり、令和３年度末の総登録数は１万３,２９２頭となっています。一方、狂犬病予防接種は、狂犬病予防法で飼い主に対し、年１回の接種が義務づけられており、令和３年度に注射済みの件数です。","voiceIndex":159,"id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"愛犬を飼っている区民が大変多くいるということは、ペットたちにも、また人間にもすばらしいことと私は思っています。ですから、なるべく人様の迷惑にならないように、私自身も、完璧ではありませんけれども、ルールやマナーを守ることを念頭に飼っているつもりであります。ペットに関する苦情・相談などはどのように受け、対処されているのでしょうか。そのことに対してお答えください。","respondent":"福内健康推進部長","answer":"しかしながら、犬や猫のふん尿や鳴き声に関する苦情が一定数あることから、ペットを飼う際のマナーやルールについて、しつけ方教室の実施なども通じて、飼い主に行き届くような啓発を充実していく必要があると考えております。","voiceIndex":161,"id":"exchange-075"},{"speaker":"木村委員","kind":"質問・要望","question":"人権啓発事業です。１,１５９万円余から質問ですけれども、令和２年度は１,１３８万円余でした。人は何のために生まれてきて何のために生き続けているのでしょうか。人権に対して行政としてのお考えをお聞かせください。そして、一刻も早く終結させるには、私たちに何ができるのでしょうか。それもあれば、お聞かせいただきたいと思います。","respondent":"堀越総務部長","answer":"区として何ができるかですが、非核平和都市宣言などを行っております区の姿勢を継続的に示しながら、多文化共生、国際理解の促進を通じまして、将来の世代にわたり国際社会の平和と安定が保たれるよう、そのような形で区としての務めを果たしていきたいと考えているところです。","voiceIndex":163,"id":"exchange-076"},{"speaker":"木村委員","kind":"質問・要望","question":"両国に早く平和が戻ってくることを願って、次の質問に移りたいと思います。１９１ページの中段より少し下の区民保養所、５,８２８万円余からですけれども、令和２年度の区民保養所経費、７,６６６万円余と比べると、１,８４０万円ほど減額された決算となりました。区民の願いが感じられると思いますけれども、どういうことが感じられるのか、もしあれば教えていただきたいと思います。お聞かせください。","respondent":"伊崎地域振興部長","answer":"ただ、新型コロナウイルス感染症の今後の状況を見込むのは大変難しゅうありますので、区としましては、感染対策を十分取りながら、区民の皆様に保養所をご利用いただき、健康増進とリフレッシュを図っていただきたいと考えております。","voiceIndex":165,"id":"exchange-077"},{"speaker":"木村委員","kind":"質問・要望","question":"常日頃、疲れを癒やす、心を癒やすための保養所は、区民のためにもなくてはならない保養所だと私は思っていますし、４０万人以上の区民が使う施設、区民が一丸となって、笑顔あふれる保養所を取り戻していただきたいと考えています。歩行喫煙防止の結果や呼びかけなどは、どのように行っているのでしょうか。これもまたお聞かせください。","respondent":"伊崎地域振興部長","answer":"歩行喫煙防止推進事業の結果につきましては、現在、具体的な数値としてお示しするのは困難な状況ですが、委員ご指摘のとおり、区といたしましても、きれいに美化が進んでいるという認識はしております。","voiceIndex":167,"id":"exchange-078"},{"speaker":"木村委員","kind":"質問","question":"スポーツ推進費からお聞きいたします。２０３ページの一番上、高齢者スポーツの普及とスポーツの充実からの質問ですけれども、普及とは、スポーツが一人でも多くの高齢者に親しんでもらえること、充実とは、スポーツを通じた健康が十分に伝わることだと私は思っておりますけれども、それでいいのかどうか、お聞かせください。そして、人生２００年をどのように思われますか。","respondent":"山崎文化スポーツ振興部長","answer":"それで最後に、人生２００年時代というのは、なかなか、例えば生活習慣などを改善することで元気に長生きするいわゆる健康寿命を延伸するというような考え方かと捉えております。","voiceIndex":169,"id":"exchange-079"},{"speaker":"木村委員","kind":"質問","question":"人生２００年は私もびっくりいたしましたけれども、これから２００年生きるとなると、何年生きないといけないのか、計算できませんでした。次に、こころの健康づくり事業、１,９４７万円余から質問です。私は、健全な心とは、自分の考えを自分自身がコントロールできるかということだと思っています。本区品川区では、自ら命を絶つ自殺者は年間どれほどの数に上るのか。お聞かせください。","respondent":"福内健康推進部長","answer":"男性が女性に比べ、多い状況です。原因については、詳細な分析というのはなかなか難しいところがありますが、経済的なもの、健康面、もしくは家族の中でのいろいろな関係の問題等々があります。","voiceIndex":171,"id":"exchange-080"},{"speaker":"木村委員","kind":"質問・要望","question":"次は、３０１ページのリサイクル活動支援事業からお聞きいたします。無論、物を大事にすることは、学校や家庭でもきちんと教えているとは思いますけれども、我が家でも２人の子どもを厳しく育てたつもりです。全体的に、現在の子どもたちは物を大事にする教えを受けていると思いますけれども、今の子どもたちを見て、どのように感じられますでしょうか。我々の学生時代も、いじめというものは日常茶飯事です。","respondent":"品川品川区清掃事務所長、米田教育次長","answer":"未来を担う子どもたちの環境意識を高めることは、地球環境保全においても大変重要なことであり、引き続き環境啓発活動を進めてまいります。児童・生徒にいじめはあってはならないものですが、どの学校でも起こり得るものとして認識し、未然防止と早期発見、早期対応に当たることが肝要だと考えています。","voiceIndex":173,"id":"exchange-081"},{"speaker":"木村委員","kind":"質問・要望","question":"３６７ページの５行目になります。特色ある教育活動経費、４７４万円余ですけれども、その４行下にも、特色ある教育活動経費７０７万円余と、２つの経費が記載されています。事業内容が違うのでしょうけれども、内容を分かりやすくお聞かせいただきたいと思います。これは１つだけですのでお願いいたします。","respondent":"米田教育次長","answer":"教育総合支援センターでは、学校と家庭の連携推進事業等として、いじめ、不登校、暴力行為、虐待など、生活指導上の課題に対して地域全体で取り組む教育体制を構築している事業となります。","voiceIndex":176,"id":"exchange-082"},{"speaker":"木村委員","kind":"質問","question":"１３９万円余と記載されておりますけれども、未来の大人たちに現在の大人がどのようなことを教えているのでしょうか。学校の授業とは違い、また見たこともない、聞いたこともない、あらゆるジャンルの経験者が話す内容にさぞや興味をそそられ、想像たくましく未来が湧き上がってくると思いますけれども、その後の子どもたちの成長のほどは、どのように感じているのでしょうか。","respondent":"米田教育次長","answer":"成果としては、やはり地域の方々との触れ合いを通して地域への理解が深まり、地域への愛着を持つことにつながっていることが大きなことだと認識しています。","voiceIndex":178,"id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"食器購入等、令和２年度は５,８７０万円余であります。学校単位で行っているのでしょうか。それをお聞かせください。そして、３８３ページの下から４行目、学校施設建設費からの質問でありますけれども、令和２年度学校施設建設費は１０校、約５７億２,７０７万円余、令和３年度は６校、３５億９,５４３万円余、この事業を行う、次回の施設建設を行う学校は決まっているのでしょうか。","respondent":"米田教育次長","answer":"学校施設建設の推進のご要望と受け止めさせていただきました。総合実施計画に基づきまして、現在は年１校のペースで改築に着手してまいりたいと考えています。","voiceIndex":180,"id":"exchange-084"},{"speaker":"藤原委員","kind":"質問","question":"藤原です。総括質疑をします。私は銭湯が大好きです。これは高齢者クラブだと思うのですが、改めて高齢者クラブの目的、現状、そして課題を教えてください。これはシルバー人材センターだと思うのですけれども、ここに関しても、目的、そして現状、課題を教えてください。道路点検パトロール、本当に地味な仕事ですけれども、していただいていると思うので、ここは実績、そして課題を教えてください。","respondent":"福内健康推進部長、今井福祉部長、伊崎地域振興部長、稲田防災まちづくり部長","answer":"他の時期は２２件の公衆浴場で実施し、参加者数は延べ３,７８０人でした。これらの課題に対応するために、特に品川区高齢者クラブ連合会、いわゆる品高連の皆様が、高齢者クラブ同士を結びつけて。課題としましては、シルバー人材センターの事業報告等を拝見しますと、やはり会員の獲得と、事業収入増、それから事故防止ですけれども。そういうもので毎日実施していますが、課題といたしましては、これが大きな事故につながったりして、高齢者も含めた。","voiceIndex":185,"id":"exchange-085"},{"speaker":"藤原委員","kind":"質問・要望","question":"「きょういく」と「きょうよう」。２０２５年、団塊の世代が７５歳以上ということで、品川区の団塊の世代の方、７５歳以上の方の人数とその割合を教えてください。今、社会福祉士のクラスは満員だと伺うのですけれども、介護福祉士のクラスは空きが多くあるということなので、その辺を教えていただきたいのと、分析をしていればその辺も教えてください。この辺についても、分かれば教えていただけますか。","respondent":"今井福祉部長","answer":"今後も７５歳以上の高齢者の増加が見込まれますので、今お話があった、介護予防の先の介護認定の率も上昇が見込まれるところです。","voiceIndex":190,"id":"exchange-086"},{"speaker":"藤原委員","kind":"質問","question":"「藤原さん、何を言っているんですか。来てほしい人がいるからです。だから、私はいつも処遇改善と、給料を上げてほしいとお願いするのです。ガソリン等が上がるから、車の送り迎えのガソリン代が上がって、もう大変ではないですか。そして、役所も福祉部はこの人数で大丈夫ですか。人と人ではないですか。ですから、役所の人数、ケアマネジャーの人数、そして処遇改善。その辺についてはいかがでしょうか。","respondent":"今井福祉部長","answer":"最後に区の職員ですけれども、このような介護予防や介護で、実際には実務が増えてくるところですが、効率化またはＤＸ化なども進めておりますので、今後も引き続き効率的に、介護保険制度、介護予防の事業を実施していきたいと考えています。","voiceIndex":192,"id":"exchange-087"},{"speaker":"藤原委員","kind":"質問","question":"部長、言っていることは分かるのですけれども、やはり最後は人と人でしょう。いろいろな方がいろいろなご相談に来て、介護を受ける方が増えていくのですから。次は、西大井駅周辺のことをお伺いします。初めに、ニコンの本社が今、建築されていますが、完成はいつでしょうか。そして、完成されたときに、昼間人口はどのぐらい増えるでしょうか。西大井駅周辺の再開発の予定はどうなっているでしょうか。","respondent":"中村都市環境部長、有江都市整備推進担当部長","answer":"新社屋が完成しますと、３,０００人を加えて、最大で全体で４,０００人ということで、今、説明を受けているところです。西大井駅周辺における再開発の動きですけれども、現在、２つの地区でまちづくり協議会がそれぞれ設立されております。まちの課題や将来のまちづくりの方向性などについて、地権者の皆様の方で現在検討されております。","voiceIndex":194,"id":"exchange-088"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、私は何回もお願いしていますけれども、西口にも改札口をぜひつくっていただきたいと思います。その辺は、まちづくりとしてどう考えるのか。そして、私は西大井がこれからもっともっと発展すると思っているのですけれども、西大井からシェアサイクルで、いろいろなところに行けるような形を取っていただきたいと思うのですけれども、その辺についてはいかがでしょうか。お願いします。","respondent":"中村都市環境部長、稲田防災まちづくり部長、伊崎地域振興部長","answer":"こちらは今後、令和６年にニコンの本社も竣工しまして、駅の利用者の増加も見込まれますので、利便性という意味から、可能な限り。区は、事業を開始してから積極的に、シェアサイクルポートを設置してきたのですけれども、現在９３か所ほどあるのですが、ただ、駅周辺というのが。現在は、運営に混乱が生じないように、徐々に会員の募集を行っておりまして、今は２１名の方が創業支援スペースに入居していただいておりますが。","voiceIndex":197,"id":"exchange-089"},{"speaker":"藤原委員","kind":"質問・要望","question":"止まることをきっかけに本数が増えたわけですから、原踏切がなかなか開かなくなってしまった。やはり、補助２０５号線から補助２９号線という意味で、立体という意味で、原踏切をどういうふうにしていくかということをお伺いします。だから、あそこは１時間だけでも、通学のとき、朝１時間でもいいので、歩行者専用道路にしていただきたいと思うのですけれども、いかがでしょうか。これはどういうことですか。","respondent":"有江都市整備推進担当部長、稲田防災まちづくり部長、中村都市環境部長","answer":"このような状況において、鉄道を上げるとか下げるとかということだけで、この課題を検討するものではないと認識しております。交通管理者である警察との協議、通学路であるため教育委員会との連携が、重要になってくるですので、まずは車両への注意喚起を行い、交通安全を保っていき。したがいまして、西大井駅周辺のまちづくりのさらなる進展が図られますように、マスタープランの見直しの中については検討してまいりたいと考えております。","voiceIndex":201,"id":"exchange-090"},{"speaker":"藤原委員","kind":"質問","question":"部長、子どもの安全が一番ですよ。それなら、教育委員会と警察と、すぐ協議してください。おかしいですよね。１時間でいいので止めてください。次は基金についてお伺いします。基金の設置と運用ですけれども、改めて、基金はどういうときに設置するのでしょうか。基金の設置のセクションと運用のセクションが違うと思うのですけれども、それぞれ、違うのであるならばなぜ違うのか教えてください。","respondent":"黒田財政課長、中山会計管理者","answer":"基金は、特定の目的のために、財産の維持や資金の積み立て、定額資金の運用を行うために、条例によりまして、議会の議決を経て設置されるものでございまして、この基金は。基金の設置と運用というところになります。運用につきましては、私ども会計管理室でやらせていただいております。","voiceIndex":205,"id":"exchange-091"},{"speaker":"藤原委員","kind":"質問","question":"実際、運用はどうしているのかということをお伺いします。運用の判断基準というのは、どのようにしているのか。運用専門の部署があるのか。現在の時点での、運用実績についてお伺いします。","respondent":"中山会計管理者","answer":"少し運用方針のところについてお話をしますと、購入できる債券については４種類としております。国債と政府保証債、それから財投機関債、地方債ということで、元本が限りなく安全に保障されるという安全性の確保をまず第１に考えております。","voiceIndex":208,"id":"exchange-092"},{"speaker":"藤原委員","kind":"質問・要望","question":"たしか、私が１期目のときだから、２０年前ぐらいですか。それともう一点は、もし元本保証でということの大前提になってしまうならば、元本保証で、金利がいいものというふうに決めてしまえば、運用というよりも事務的手続きだけでよくなってしまうのではないかというのも１つ思うのですけれども、その辺の答弁をしていただきたいのと、２３区の中での実績というのはどのぐらいなのでしょうか。","respondent":"中山会計管理者","answer":"事務的にというお話もありましたが、例えば日々、国債の利率も変わっておりますし、購入するのは国債より、今はどちらかといいますと財投機関債が多いのですけれども、そちらにつきましては、どれぐらいレートが乗ってくるかということもありますので。","voiceIndex":210,"id":"exchange-093"},{"speaker":"吉田委員","kind":"質問・要望","question":"小山台住宅等跡地における福祉施設等整備事業基本計画業務委託について伺います。事業者の選定に当たって、具体的にどういう視点で、この会議室、交流スペースを、地域のにぎわいに資する場所として判断するのか伺いたいと思います。ここに地域のにぎわいとして会議室を設置するというのは、どういうことを想定しているのか伺います。これをこの施設に求める意義も併せて伺いたいと思います。","respondent":"今井福祉部長","answer":"これまで、こちらの整備計画につきましては、議会の５月の厚生委員会で報告するとともに、６月には整備計画の説明会を住民の方々に行うとともに、今回、基本設計の業務委託として、事業者の選定の公募をしたところです。","voiceIndex":213,"id":"exchange-094"},{"speaker":"吉田委員","kind":"提案","question":"その辺も少し分かりにくいと思うのですが、その辺の配点の考え方についても伺いたいと思います。次の質問に行きます。そうなると、この募集の中に、この施設の人たちのための備蓄倉庫のようなものが見えないのですけれども、それは、こういうものをつくるときは当然、提案の中にそれが入ってくることが前提ということでしょうか。７０床から９０床といいながら、可能な限り多く、９０床を超える提案も認める。","respondent":"今井福祉部長","answer":"もともとこちらの小山台住宅跡地におきましては、東京都と一緒に、財務省の小山台住宅等跡地利用方針を平成３０年１０月に策定いたしまして、説明会の中でもご説明したとおり、まずは跡地全体に必要な機能の土地利用を考えたときに、防災機能、それから。","voiceIndex":215,"id":"exchange-095","title":"町会・自治会支援"},{"speaker":"吉田委員","kind":"提案","question":"分かりました。どういう多機能を区としては目指しているのか伺いたいと思います。提案者の提案に委ねて、その中から選ぶほうが、区が発想するよりよいアイデアが来るということを期待することもあるかもしれませんけれども、やはり区としての事業のイメージは持っていただきたいと思いますが、見解を伺います。運営事業者も気になるところですが、いつ頃の選定になるのか教えていただけるでしょうか。","respondent":"今井福祉部長","answer":"現在、今後のスケジュールにつきましては、令和５年度に、基本設計の段階で、計画の説明会をする予定でございまして、今後それを後でまた実施設計、それから令和７年度以降に工事説明会、やはり工事の段階を終えましてから、また先ほど、施設の管理運営についての事業者は。","voiceIndex":217,"id":"exchange-096","title":"町会・自治会支援"},{"speaker":"吉田委員","kind":"質問・要望","question":"これからでもぜひ聞いていただきたいのですけれども、その点について改めて伺います。それから、運営事業者の選定は分かりました。以前もどこかの款別審査で質問したことがあるのですけれども、基本は事業者の公募のための情報提供だというのは理解できるのですけれども、施設整備施策に関心を持つ区民の方にとっては大変有益な情報なので、どこかに残しておいていただきたいのですが、いかがでしょうか。","respondent":"今井福祉部長、堀越総務部長","answer":"それから近隣の説明会ですけれども、議会、そしてこちらの説明会、６月の整備計画説明会以降、事業内容または施設内容等、変更はございませんので、この計画の中で公募を進めたもので、現段階では次の近隣への説明会については。プロポーザル等の公募の件のホームページへの掲載に関するご質問ですけれども、ご質問にありましたように、公募を目的としているものではありますけれども、事業者選定後、公募期間が終了したものについても、多少。","voiceIndex":219,"id":"exchange-097"},{"speaker":"吉田委員","kind":"質問・要望","question":"近隣の説明については、やはりまめに行っていただきたいと思います。次に、リニア中央新幹線のことについて伺います。説明責任はＪＲ東海にあるとは考えておりますが、区として受けた説明内容は、区としても区民に対して報告すべきと考えますが、いかがでしょうか。ＪＲ東海として区民への説明会を行うように、区として促してほしいと思うのですけれども、その点についても見解を伺います。","respondent":"有江都市整備推進担当部長","answer":"ということで、オープンハウス型説明会の内容を掲載しておりますが、その内容としましては、品川区内の３つの箇所におきまして、ＪＲの社員が直接、今の状況、掘進の状況、そもそものリニア中央新幹線の概要等を含めて、直接。","voiceIndex":222,"id":"exchange-098"},{"speaker":"吉田委員","kind":"質問・要望","question":"教室型の説明会は、全体として、品川区内でいろいろなところに影響がありますので、そこの地域で、いろいろなところで開かれるのはいいと思うのですけれども、まずは調査掘進が止まってしまっているあたりの、例えば北品川とか、そういうところで実施していただきたいと思うのですが、それをＪＲ東海に求めるべきと考えますが、見解を伺います。","respondent":"有江都市整備推進担当部長","answer":"基本的な説明会をどういう形で行うかどうかみたいなものを含めまして、基本的にはリニア中央新幹線はＪＲ東海の責任の下で実施されているものですので、区の立場としましては、区民へのそういった周知みたいなものにつきまして。","voiceIndex":224,"id":"exchange-099"},{"speaker":"吉田委員","kind":"質問・要望","question":"オープンハウス型とはいえ、止まっている地域で説明会が開かれるということはいいと思います。ただ、教室型の説明会も開くべきではないかということを、区として主張していただきたいと思います。ただ、区としては、区民の立場に立って、そういう不安に思っている区民がいるわけですから、その立場に立って、区としてそれを求めていただきたいということです。ぜひその辺について見解を伺いたいと思います。","respondent":"有江都市整備推進担当部長","answer":"区の立場としましても、オープンハウス型説明会は最近いろいろな事業でやっておりますけれども、様々な疑問・質問に対して、かなり丁寧に対応できるものだと認識しておりますので、今回、品川区の地区の中では、６日間にわたって３つの箇所で行いますので。","voiceIndex":226,"id":"exchange-100"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。それはぜひ開いていただきたいと思います。ただ、区民の中にはやはり教室型説明会を要望する声が多いのです。区として区民の立場に立った要求をきちんと突きつけてほしいということで、今、繰り返して主張しておりますので、ぜひ、そのことについては改めてお願いしたいと思います。これだけ時間がかかった調査掘進は調査掘進として不適切ではないかと考えますが、区としての見解を伺います。","respondent":"有江都市整備推進担当部長","answer":"実質的に調査掘進で得られた知見・データを含めて、本掘進に多分入っていくと思うのですけれども、本掘進に入る前には、必ず、住民の皆さんを含めて、きちんとした説明をして実施するということは、あらかじめ、調査掘進に入る前から明言しておりますので。","voiceIndex":228,"id":"exchange-101"},{"speaker":"吉田委員","kind":"質問・要望","question":"区については、区民の立場に立った主張をぜひ続けていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":230,"id":"exchange-102"},{"speaker":"松本委員","kind":"質問","question":"最初に、新庁舎整備について伺います。品川区議会日本維新の会としては、新庁舎整備計画を見直すべきと考えているところから、また質問を行っていきたいのですけれども、新庁舎整備について、今年の７月に、品川区新庁舎整備基本計画（素案）が公開されて、パブリックコメントに付されました。さらに、この区の方針決定の前に、区民と意見交換をする場というのはどの程度あったのか、伺います。","respondent":"榎本新庁舎整備担当部長","answer":"それをいつ検討したかですけれども、この間、平成２９年から行財政改革特別委員会の中で、庁舎の機能修繕の検討を始めて、それから改築の検討を始めて、令和２年度には庁舎機能の検討委員会を開いて、それぞれ、学識、公募、区民等を入れた形で検討してきました。","voiceIndex":232,"id":"exchange-103"},{"speaker":"松本委員","kind":"質問・要望","question":"ただ、少しやはりおかしいのではないかと思うのが、パブリックコメントの区の見解というか、区の意見のところで、パブリックコメントで区民の方たちから図書館や福祉施設を造ってほしいというものに対する区の見解として、行政施設を集約するから、これは造らないのだと書いてあるのです。少子高齢化が進む。こうした発想というのは当然かと思います。なぜ現庁舎跡地の活用を想定しなかったのか、伺います。","respondent":"榎本新庁舎整備担当部長","answer":"要は、土地区画整理事業と並行して進めていますので、新庁舎の建設予定地は途中で、ある程度分かって、そこにどういうものを建てようかという検討を進めていましたけれども、現庁舎については、まだ道路の拡幅とか、新しい道路を造るとか。","voiceIndex":234,"id":"exchange-104"},{"speaker":"松本委員","kind":"質問・要望","question":"概算事業費４００億円以上というところを引き続きですけれども、移転費、解体費用等が入っていないということを一般質問でも伺わせていただきました。それに加えまして、ＰＦＩについても一般質問では伺わせていただきました。改めてＰＦＩ方式について、複数社から費用を削減できるとの回答を得ながら、なぜさらなる調査・検討がなかったのか、伺います。","respondent":"榎本新庁舎整備担当部長","answer":"新庁舎整備部門としては、新庁舎建設予定地に何を入れるかという形で聞いたのですが、当然、本庁舎の跡が空くということが分かるわけですから、そこも含めて要望を出してきていると理解しております。それについては、また総合的な観点から、区として検討していく予定です。","voiceIndex":236,"id":"exchange-105"},{"speaker":"松本委員","kind":"質問","question":"私がずっとこの間、一般質問から伺っているのは、ＰＦＩというのは確かにいろいろなご批判もあると思います。これは、総務省内閣府もいろいろなことを言って、こうしてほしい、こうしたら何とかなるのだというような話をしているところです。その中で、当区で策定しているのか。策定していないとしたら、なぜか。していないのであれば直ちに策定するべきだと思いますが、見解を伺います。","respondent":"久保田企画部長","answer":"区としましては、民間活力を活用するための具体的な方針や手続きをあらかじめ定めることは有用と捉えておりまして、引き続き、情報収集を進めまして、検討してまいりたいと考えているところです。","voiceIndex":238,"id":"exchange-106"},{"speaker":"松本委員","kind":"質問","question":"先ほど申し上げましたように、定めるように言われているところの８４.３％が定めている。次に、監査委員、選挙管理委員会の在り方、選挙管理委員の在り方について伺います。品川区においても議選監査委員を廃止して、より専門性の高い人材に就任していただき、しっかりと行政を監査してもらうべきと考えますが、区の見解を伺います。当区においても包括外部監査を導入すべきと考えますが、見解を伺います。","respondent":"堀越総務部長","answer":"一方で、政策面に精通している議員選出の監査委員に監査していただいていますので、相互にそれぞれの専門性を活かしながら、補完し合って監査を行っていただいていると認識しておりますので、監査委員の在り方については様々議論があることは承知しておりますが、現時点では。","voiceIndex":240,"id":"exchange-107"},{"speaker":"松本委員","kind":"質問","question":"議選監査委員については、報酬も問題かと思います。議員報酬とは別に、月額１８万２,０００円、報酬が支払われているという状況です。改めて、この議選監査委員。先ほどのご答弁で、廃止は考えていないということですけれども、では、この報酬を見直していくという考え方もあると思いますが、見解を伺います。日当制にするとか、いろいろあると思いますけれども、こちらについて見解を伺います。","respondent":"堀越総務部長","answer":"行政委員会の委員についてのご質問です。職責・地位にふさわしい額を、区議会の議決による条例で定めているところですので、現時点で見直しという考えはございません。同様に、選挙管理委員の報酬についても、同様の考え方です。","voiceIndex":242,"id":"exchange-108"},{"speaker":"松本委員","kind":"質問","question":"ここの点では最後の点ですけれども、ほかの自治体を見ますと、そもそも特別職の報酬を検討するときに、従来は一般の公務員の皆さんの報酬・給与等が上がるから、それと併せてどうですかということで、検討してくださいというような諮問のされ方がされておりますが、先ほどの行政委員の日当制などを導入するタイミングには、ここはそういう聞き方、諮問の仕方ではなくて。","respondent":"堀越総務部長","answer":"したがいまして、そういった趣旨も含めて総合的な判断を頂いたと考えているところでございまして、諮問の表現につきましては、どのような形がふさわしいかについては、いろいろと研究させていただきたいと考えています。","voiceIndex":244,"id":"exchange-109"},{"speaker":"松本委員","kind":"質問","question":"最後に区長公用車。もう時間がないので少しお伺いしたいのですけれども、結構、首長公用車についてはいろいろな指摘がされておりますけれども、当区、品川区の区長公用車の車種、購入年について伺います。さらに、購入価格あるいはリース価格、リースの場合は更新時期について伺います。しっかりとここも考えていかないといけないところだと思っていますので、ご答弁をお願いします。","respondent":"堀越総務部長","answer":"区長公用車の車種ですが、トヨタクラウンロイヤルサルーンＧという車で、リース車です。リース価格は５５２万４,８４８円で、これは７年リースとなっています。更新時期は令和６年度、令和７年２月を予定しているものです。","voiceIndex":246,"id":"exchange-110"},{"speaker":"湯澤委員","kind":"質問・要望","question":"品川区議会自民党は、令和３年度品川区一般会計、国民健康保険事業会計、後期高齢者医療特別会計、介護保険特別会計、災害復旧特別会計、全ての歳入歳出決算を認定いたします。コロナ禍、物価高が重なる中であるからこそ、より一層の区民生活・福祉の維持・向上にさらに努めていただくことを要望いたします。ここで何点か取り上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":250,"id":"exchange-111"},{"speaker":"若林副委員長","kind":"提案","question":"公明党はこの１年、コロナ対策に特に力を注ぎ、６回の緊急要望を区長に行いました。区におかれましては、これまでの経験を踏まえ、コロナ関連対策や、様々な交流の活発化をはじめ、福祉向上への施策の展開をお願いいたします。本決算特別委員会では、款別審査、総括質疑において、会派から様々な意見、要望、提案を行いました。今後の区政運営および来年度予算に反映されるよう求め、意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":252,"id":"exchange-112"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"区職員の３３％を占める会計年度職員のうち８６％は女性であり、同一労働同一賃金、ジェンダー平等の観点からも、他区のように昇給制度を設けるなど待遇改善を求めます。教室型説明会を求めるとともに、技術が未確立でかつてない環境破壊のリニア中央新幹線は中止を求めるべきです。新庁舎です。問題だらけで、保護者からも声の上がる英語スピーキングテストは、結果の入試活用の中止を都に求めるべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":254,"id":"exchange-113"},{"speaker":"大倉委員","kind":"提案","question":"令和３年度は、普通会計の実質収支は約６９億円の黒字となり、経常収支比率は７４.８％、人件費率は１３.５％と、健全財政を維持していることを確認いたしました。今回の決算特別委員会において、我が会派の所属議員が質問の中で指摘・提案した項目を真摯に受け止め、次年度予算をはじめ、今後の施策に反映するよう要望いたしまして、イノベーションしながわの意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":256,"id":"exchange-114"},{"speaker":"須貝委員","kind":"質問・要望","question":"令和３年度決算に対する品川改革連合の意見表明をします。令和３年度の一般会計、国民健康保険事業会計、後期高齢者医療・介護保険・災害復旧の３つの特別会計の各決算を認定します。１０月にコロナ感染は減少し、観光・飲食・サービス業にも明るさが見えてきたものの、１１月中旬からまた拡大しています。以上で、令和３年度決算に対する品川改革連合の意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":258,"id":"exchange-115"},{"speaker":"吉田委員","kind":"提案","question":"以下、意見を述べます。新庁舎計画は拙速に進めるべきではありません。現在、区は、すまいるスクールの昼食提供を検討中とのことでしたが、区の検討のみで拙速に決めるべきではなく、当事者の意見が政策に反映される市民参加の機会をつくることを求めます。その他、各款別審査で指摘・提案させていただいた意見を予算編成に活かしていただくことを要望して、品川・生活者ネットワークの意見表明を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":260,"id":"exchange-116"},{"speaker":"せらく委員","kind":"提案","question":"本年度の形式収支は約７０億円の黒字となりました。区におかれましては、今回の決算特別委員会において弊会派の各委員の質疑の中で指摘・提案した点について検討され、次年度の予算や今後の施策・事業に反映していただくことを要望するとともに、区が遂行する政策等については評価・検証・改善を徹底していただき、区民サービスの向上が図られることを求め、品川区議会日本維新の会の意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":262,"id":"exchange-117"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1528#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":123230,"voices":269}},{"id":"r04-20221124-10","meetingId":"r04-cm11","date":"2022年11月24日","dateIso":"2022-11-24","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和４年陳情第５２号、現職区議会議員の立候補に関する条例の制定を求める陳情","agenda":"令和４年陳情第５２号、現職区議会議員の立候補に関する条例の制定を求める陳情","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"これは判断するのは、裁判をして、司法ですから分かりませんけれども、そういう可能性のあるもの、勧告だけではなくて、勧告する条例の制定を求めますとなっていますので、それはなかなか難しいのではないか。難しいというか、できないでしょうということで、我々とすると、やはり願意に沿い難いということで結論を出させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"今のこういうルールになっている根拠となる法律では、どのような規定になっているのか、分かれば伺いたいのと、今回、区長選挙は、新たな区長が決まれば４年後も区長選挙がこの時期になると思うのですが、そのときも、区議の欠員があった際は、同時に区議補欠選挙もやられるのかという２点を伺いたいと思います。","respondent":"工藤区議会事務局長","answer":"４年後ですけれども、またこちらも法律の適用ということで、４年後の選挙がいつになるかというところがありますので、４年後にあるかどうかというのは、現在のところ、私の立場としてはコメントはできないです。","voiceIndex":16,"id":"exchange-002"},{"speaker":"大倉委員","kind":"意見","question":"まさに、非常に丁寧にご説明いただいて、根拠もあわせてお話しいただいているかと考えていますが、今のご説明の中でも、法令の中で定められているところでありますし、それを、あくつ委員からありましたけれども、品川区議会として法令違反になるようなことを議会自らやるということについては、非常に疑義を感じるところがあるので、今回の陳情に対しては、不採択ということで、会派としては思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-003"},{"speaker":"のだて委員","kind":"意見","question":"一応、私たちとしても、後でも述べますけれども、議員の身分は、任期を全うするということでも保障されていると考えています。事前に辞めるかどうかというのも、区議会議員の姿勢次第だと考えていますので、不採択と考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"本日結論を出すということで、不採択とします。立候補に当たって区議会議員を最後まで全うするかどうか、全うすることも、事前に辞職することも、本人の姿勢次第です。反社会的な態度や言動を行った場合は、区議を続ける資格はないと辞職を求めることもありますが、今回は区議の資格を問うものではないと思いますので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-005"}]},{"id":"topic-02","title":"令和４年第３回定例会","agenda":"令和４年第３回定例会","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"固定資産税・都市計画税の軽減措置の継続を求める意見書についてご説明いたします。本意見書は、東京都が現在実施している固定資産税および都市計画税に係る軽減措置を令和５年度以降も継続するよう求めるものです。以下、案文を読み上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-006"}]},{"id":"topic-03","title":"品川区議会における個人情報保護","agenda":"品川区議会における個人情報保護","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"幾つか伺いたいのですけれども、まず、今回の品川区の条例案が全国市議会議長会案と大体同じ内容になっていると思うのですが、その理由と、また、幾つか変更している点がありますけれども、その違いと、変更した理由を伺います。","respondent":"工藤区議会事務局長","answer":"ただ、先ほどご説明しましたように、ある部分では法律から読み込んで、こういった条例をつくりますので、例えば変更点として、先ほど開示のところでご説明しましたように、事務処理上困難その他正当な理由があるときに、一定の期間をいただくわけですけれども。","voiceIndex":54,"id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"開示のところは若干詳しくご説明いただいていましたけれども、ほかにもいろいろなところで処理の期限のところは変えていらっしゃるかと思います。それと、手数料については今、検討中ということですけれども、この期間も議会の中でも言わせていただいておりますが、ぜひ無料にしていただきたいと思いますけれども、いかがですか。","respondent":"工藤区議会事務局長","answer":"最後の手数料関係ですけれども、先ほどご説明いたしましたように、今、執行機関でその辺を協議していると聞いておりますので、これまでも執行機関と同様、私どもは考え方を合わせておりましたので、そのような執行機関の検討状況を見まして。","voiceIndex":56,"id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"手数料のところは、執行機関と合わせていくということもありますけれども、ぜひ区議会として、無料にしていっていただきたいと思います。あわせて、審議会についての規定がありますが、法律では審査会と審議会の２つの規定があるという中で、今回、区議会としては、両方の機能を備えた審議会を位置づけるということで、こうした理由と、これも今がどうなっているのかを伺いたいと思います。","respondent":"工藤区議会事務局長","answer":"それで、２つあるという部分につきましては、先ほどご説明したとおり、区では１つの審議会で審議をされているです。","voiceIndex":58,"id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"審議会のところは、区に倣ってということなのですけれども、法改正上では２つあるというのを１つにするというのはなぜなのかという、そこの理由を改めて伺いたいのと、議会のあり方ということもありますし、議会の中でも情報公開について、質疑などの意見も出ていますので、この場合は、議会運営委員会に参加をしていない会派や議員の意見の反映もしていかなければいけないと思うのですけれども。","respondent":"工藤区議会事務局長","answer":"審議会の考え方はいろいろとあろうかと思います。何度も繰り返しになりますけれども、先ほどご説明しましたように、一つの審議会で両方の機能を兼ねるということで、例えば、専門性のある方が集まって審議会がつくられているわけです。","voiceIndex":60,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"今回、その両方の機能を備えた審議会をつくるとした考え方を伺いたいのと、先ほど議会運営委員会に参加していない会派とか議員の意見の反映というところもお聞きしたので、質疑できる場をつくってほしいということなのですけれども、それを伺いたいと思います。","respondent":"工藤区議会事務局長","answer":"こういった条例案に対する審査ですけれども、こちらにつきましては、議会運営委員会の資料等については会派の皆さん、無所属の議員の方にも情報提供しておりますし、ＳｉｄｅＢｏｏｋｓにも、今回説明しましたように比較表等もおつけしておりますので。","voiceIndex":63,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"最後に、少数会派や無所属議員の意見の反映というところはやっていただきたいと思いますし、資料提供はされるかもしれませんが、質疑できる場というのはないと思いますので、これは事務局に求めるのか、委員長に求めるのか分かりませんが、ぜひそういった場を保障していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-012"},{"speaker":"石田委員","kind":"質問","question":"１点だけ、区議会における個人情報というそもそものところなのですけれども、これかな、あれかなと思い当たるというところはあるのですが、まだはてながついているので、そもそも区議会における個人情報というのはどういうものかというのを、具体的に分かる言葉で教えてください。","respondent":"工藤区議会事務局長","answer":"区民に関しては、そういうところが考えられるです。それから、内部の部分では、例えば職員の人事情報とか、議員の皆様の履歴、表彰等が行われたとか、そういった履歴等といった部分が個人情報に当たるのではないかと考えているところです。","voiceIndex":67,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問","question":"私からは２点、伺います。それと文言のところで、第２条の第１１項のところに、さっきも説明があったのですけれども、横引きをしているという説明がそもそもあって、全国市議会議長会（例）の中のものに、「行政文書」という文言があるのですけれども、議会運営委員会の資料の１１ページの第１１項のところで、いわゆる定義です。そこだけ、内容的には全然賛成なのですが、２点教えてください。","respondent":"工藤区議会事務局長","answer":"最初に個人情報ファイルの関係のご質問です。ファイル簿の関係です。今、委員からお話ございましたように、最低で１,０００人という形になっておりまして、区議会の中でも１,０００人ということで定めるです。","voiceIndex":70,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5486#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":21881,"voices":87}},{"id":"r04-20221125-9","meetingId":"r04-cm11","date":"2022年11月25日","dateIso":"2022-11-25","committee":"文教委員会","time":"午後 １時４３分～午後 ２時１２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"松澤副委員長","kind":"意見","question":"説明が終わりました。本件は、１１月１日の文教委員会における「令和４年特別区および東京都人事委員会勧告等について」のご報告の中でも、今回の条例改正に関わる部分の説明があり、ご質疑等もいただいておりますので、そのほかで特にご質疑等がございましたら、ご発言をお願いしたいと思います。本件につきまして、特にご質疑等がございましたら、ご発言をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"},{"speaker":"安藤委員","kind":"確認","question":"東京都のほうと、あと特別区のほうの各労働者側といいますか、労働組合との妥結はいつ行われたのかということをまず１点お伺いしたいのと、それと、特別給のほうは勤勉手当ということなのですが、この勤勉手当というのはどういう制度なのか伺いたいと思います。今回、特別給の改正について、期末手当ではなく勤勉手当のほうに割り当てた理由も伺います。そこら辺の確認をお伺いしたいと思います。","respondent":"中谷指導課長","answer":"３点いただいたかと思います。組合との協議が行われたかということですけれども、今期の給与改定等に関連しまして、東京都に関しては、東京都労働組合連合会との交渉で妥結等を既に経ているというところがあります。","voiceIndex":5,"id":"exchange-002"},{"speaker":"安藤委員","kind":"確認","question":"勤勉手当については、今のご説明では、どういう制度なのか、どういうときに手当がつくのかということが分からなかったので、もう少し制度の内容について伺いたいのと、なぜ今回、勤勉手当のほうに割り当てたのかという理由についても伺ったので、ちょっと先ほどの説明だと分からなかったので、もう一度お願いしたいと。","respondent":"中谷指導課長","answer":"ちなみに、その年代というところなのですけれども、こちらも国の考えの中で、２０歳代半ばにまず重点を置いているということ。初任の係長の若手職員にも一定の改善が及ぶようにしているということがあります。もう１点に関しましては、令和４年度現在に引上げということで早速に引き上がっていきますが、令和５年度もその同じ金額でということになります。ですので、今後、先々は引上げ分ということで回っていくということを認識しております。","voiceIndex":7,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。すみません、１点だけ。近年、急激な物価高もありますし、あと、教員不足がすごく深刻化していて、倍率も下がり続けている中ではないですか。そこについては、区教委としてのお考え、特に改定の額についてお考えを伺いたいなと。不十分だというふうな認識はあるのかということをお伺いしたいと思います。","respondent":"中谷指導課長","answer":"最後に、教員不足というところになるのですけれども、全国的に、ご指摘いただいた教員不足という状況は、今年発生しているところがあると考えていますが、今回、改定額というところにつきましては、今回の勧告を受けた形で、他の自治体におかれましても。","voiceIndex":10,"id":"exchange-004"},{"speaker":"若林委員","kind":"確認","question":"確認。給料表の改正のところの、学校教育職員のところで、公民較差分が月額で８２８円で０.２０％、(2)の幼稚園教育職員の公民較差分が、給与月額で８９６円、０.２４％、この根拠というか、国ではどのような内容で示されているのか。なぜ１と２で較差分の月額とかパーセントが違うのか。","respondent":"中谷指導課長","answer":"こちらですけれども、まず、幼稚園教育職員に関しては、特別区人事委員会の中での勧告ということで、１０月１１日に行われたものをそのまま適用しているという形になります。なので、区の職員の方々も同様という形で、特別区の公民較差ということでの数字になります。","voiceIndex":13,"id":"exchange-005"},{"speaker":"若林委員","kind":"質問・要望","question":"すみません、本当にそもそもなのですが、固有教員と幼稚園教育職員は、品川区において、この改正によって、同水準の給与になるという理解でいいのか。そういう聞き方をするとあれかな。では、本当に単純な質問で、せっかく新旧対照表があるので、これを使ったほうが分かりやすいのであれば、ご説明があればいただきたい。","respondent":"中谷指導課長","answer":"幼稚園教育職員のほうに関しては、まず１級が教諭、２級が主任教諭、そして３級が副園長、４級が園長という形の役回りになりまして、３級と４級が管理職ということで、こちら以外の１級と２級のほうで今回の改定ということで、下線が引いてある部分が、今回。","voiceIndex":15,"id":"exchange-006"},{"speaker":"若林委員","kind":"確認","question":"なるほど。新旧対照表を使っての説明で、より理解が進みました。別に比較しても意味がないのかもしれませんけれども、確認ですけれども、固有教員のほうは６級まであって、幼稚園のほうは４級まであって、だから、１級同士を単純に比較してもあまり意味がないのでしょうか。","respondent":"中谷指導課長","answer":"そうです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"若林委員","kind":"意見","question":"ないのだけれども、片や１５万５,６００円。片や１７万４,２００円。こういうふうに今回改正されるのだなという、正に新旧対照表ということで理解いたします。いずれにしても、教員、職員の皆さんが、お仕事をしっかり励んでいただける、そういうふうなまた取組を教育委員会としても進めていただければなというふうに存じます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-008"},{"speaker":"渡部委員","kind":"質問","question":"すみません。品川区で採用しているわけですから、いや、もっと言うと、東京都より安ければ困るのだけれども、高い分には困らないと、すごく分かりやすい言い方ですると、私はそう思っています。あるのだったら、あるで研究していきます。ないのだったら、あるようにお願いをしていきますという落ちがありますけれども、どちらにしても。今の仕組みとしてはどうなのか。","respondent":"中谷指導課長","answer":"今現在、そういう仕組みはないということが回答になろうかと思います。今現在、特別区の中で固有の教員、学校教育職員を置いている状況といいますと、４区ありまして、千代田区、杉並区、中野区、そして品川区というような状況になっております。","voiceIndex":21,"id":"exchange-009"},{"speaker":"渡部委員","kind":"質問・要望","question":"そういう答えなのですけれども、やはりそこの部分は品川区にこれから力を入れていただきたいなと思うところもあるので、研究は進めますし、何とか手当みたいな形であてがえるのであれば、そういう方法もあるのかなとか、現に、区の先生になってもらうから、周りから見れば一緒だとは言いつつ、やっぱりこの品川区の先生で特別なことをやっていただくことがこれから出てくるかもしれませんし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"松澤副委員長","kind":"確認","question":"ご異議なしと認めます。よって、本案は、全会一致で原案のとおり可決決定いたしました。次に、第１００号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例につきまして、各会派の態度を確認いたします。自民党からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-011"},{"speaker":"松澤副委員長","kind":"意見","question":"ご異議なしと認めます。よって、本案は、全会一致で原案のとおり可決決定いたしました。以上で、本件および議案審査を終了いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":35,"id":"exchange-012"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"議案審査の委員長報告については、正副委員長にご一任いただきたいと思いますが、よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-013"},{"speaker":"松澤副委員長","kind":"意見","question":"正副委員長でまとめします。以上で、委員長報告についてを終了いたします。以上で、本日の予定は全て終了いたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5084#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":8579,"voices":37}},{"id":"r04-20221125-5","meetingId":"r04-cm11","date":"2022年11月25日","dateIso":"2022-11-25","committee":"総務委員会","time":"午後 １時４５分～午後 ２時１７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"前回１１月１日にも報告はあったのですけれども、こういう条例という形で出ましたので、改めて何点かお聞かせいただきたいと思います。品川区として、実際に月例給が上がる割合は、どれぐらいの方が月例給が上がるということになるのか、その点を伺いたいと思います。その点をお願いします。","respondent":"崎村人事課長","answer":"２点ご質問をいただきまして、全体でどのぐらいの職員が賃上げになるのかというご質問ですが、ざっとですが、全体で約５０％、半分ぐらいの職員が賃上げになるというような見込みです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう１つお聞きしたいのが、会計年度任用職員なのですけれども、この会計年度任用職員は、たしか１,３００人ぐらいの人数だったと思うのですけれども、これは区の職員の何％ぐらいに当たるのかという、その割合を教えていただきたいです。その改善は本当に緊急に求められていることだと思うのですけれども、その点について伺いたいと思います。","respondent":"崎村人事課長","answer":"今年度中には結論を出されるといったこともありますので、結論が出されて勤勉手当の支給がなされるということになれば、地方自治法の改正等々もありますので、そういった部分については適切に対応していきたいというふうに考えているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっとそもそものところを教えていただきたいのですが、この一時金が、期末手当と勤勉手当に分けられた理由というか、経緯を教えていただきたいのと、また、なぜ会計年度任用職員の方には勤勉手当がそもそもつかないのかという、そこら辺の理由についても教えていただけたらと思います。","respondent":"崎村人事課長","answer":"制度の導入当初の期末・勤勉手当の分けというのは、なかなか今すぐにしっかりとしたお答えができないところなのですけれども、ただ、民間の場合でも、やはり考課査定分というものと、我々の期末手当と言っている分の均等に支給される分、また。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"会計年度任用職員という、こういう形になって、職員の３分の１が重要なところも担っているということもあるにもかかわらず、均等待遇にほど遠い状況になっていると思うのです。そういう点では、区のほうからも改善に向けてしっかりと取り組んでいただきたいと思いますし、発言もしていっていただきたいと思います。来年度は、ぜひ均等待遇というところで改善されるように取組を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"中小企業もそうですが。そういうことに関して、区の見解としては、区民、また、区内中小企業は大丈夫だというような見解なのですか。それとも、実質、町場は大変だというふうに、区の見解としてはお持ちなのでしょうか。答えられる範囲で答えてください。","respondent":"崎村人事課長","answer":"今回の給与実態調査の結果を踏まえて、今回の人事委員会の勧告の中では引上げという結果が出たというところで対応させていただいているところですので、その点はご理解いただければと考えております。","voiceIndex":12,"id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"実質、皆さん、給与が上がっているところも相当出ているという話ですが、そこを調べた厚生労働省の見解ですら、１００名以上の企業は全法人の１％しかないのに、その１％の企業に勤めている人たちの給与が上がったから、今回、上げてもいいような見解が出ているのだと思うのですが、この人事委員会勧告に関しても、実際これだけ、実質。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-006"},{"speaker":"せらく委員","kind":"質問・要望","question":"１点だけ確認をさせていただきたいのですが、第９８号議案のところで、会計年度任用職員は期末手当の改正のみで、月額の給料のほうは変動なしということでしょうか。確認させてください。","respondent":"崎村人事課長","answer":"委員のおっしゃるとおり、今回の会計年度任用職員に係る部分の改正につきましては、来年度以降の期末手当の支給の配分を、３月分をなくして、６月と１２月にそれぞれ１.２０月分ということで、均等になるように改正するものですので、特に賃上げといいますか。","voiceIndex":15,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"その３月があることが、そもそもちょっと不思議な気がしていたのですけれども、この度、３月期末手当を廃止ということにした理由があれば教えていただきたいのと、労使の交渉の中で、今言える部分があるのかないのか分からないですけれども、１１月１７日の深夜に妥結したというか、そういうことについて、何かその中で、もし特筆すべき意見というか。","respondent":"崎村人事課長","answer":"３月期末手当が支給できるようになったのは、かなり歴史的な部分になってきて、私もすぐお答えができないです。","voiceIndex":17,"id":"exchange-008"},{"speaker":"つる副委員長","kind":"確認","question":"そうすると、ちょうど４,０００人ぐらいですね。それぞれの職員の方の給与口座に振り込むという形になると思うのですが、振込みの銀行、また口座先によっては手数料があると思うのですが、これは別件でいろいろ確認すると、例えば１０５円とか、国家公務員だとか、いろいろあるのですが、この辺の振込みの手数料についてはどういうふうになっているのか、それを教えていただいてよろしいでしょうか。","respondent":"崎村人事課長","answer":"申し訳ございません。振込みの手数料につきましては、全て会計管理室のほうで振込み手続き等の管理をしている関係で、人事課ではそこまでの把握はしてございません。","voiceIndex":20,"id":"exchange-009"},{"speaker":"つる副委員長","kind":"質問","question":"所管の理事者がいらっしゃらないのであれなのですが、一般論で言えば、振込みの手数料が１回大きい部分で減るという、毎月の給料と、それから３月期末は３月期末で単独で、たしか合わせて（の振込み）だったか、３月の給料と合わせてだから変化はないのではないですか。多分一緒くたに、３月の給料で３月期末手当は一緒になっていたような気がするのです。ただ、６月と１２月は別ですよね。一般論でいいです。","respondent":"崎村人事課長","answer":"３月の期末手当につきましては、３月の給料の振込みと同じ３月１５日になりますので、そういうことで言えば、振込み回数には影響はないところです。","voiceIndex":22,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"賛成です。ただ、ちょっと意見だけ申し上げたいと思います。職員の３分の１を占める会計年度任用職員の均等待遇こそ求められるときに、ここのところが引き上がらないということも問題だと指摘をしておきたいと思います。今後に向けた改善を求めて、賛成としたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-011"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほど申し上げましたが、国民の暮らし、そして経営が厳しい、倒産や廃業が起きている中で、厳しい中で、国民の皆さんを守る公務員の皆さんが、今この時期に給与を上げることは、私は間違いだと思います。私は、公務員の皆さんもしばらく我慢していただきたいと思います。今回のこの条例案に対しては反対とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"吉田委員","kind":"意見","question":"今の議論の中でもいろいろ課題はあることが分かりましたし、会計年度任用職員は、この手当のことだけでなく、やはり不安定な身分ということで、こういう人たちが一般の職員よりも不利な立場にありながら、いろいろな職を担わされているということ自体、いろいろ課題だというふうに思っております。ただ、いろいろな交渉の結果、労使の妥結をしたということですので、この改正については賛成をいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":30,"id":"exchange-013"},{"speaker":"せらく委員","kind":"質問・要望","question":"訳としては、これまでも公務員の給料改定がありましたが、調査対象が企業規模５０人以上で、かつ、事業所規模が５０人以上の事業所ということで、比較的規模の大きい事業所が対象になっていると思います。実際の民間の生活水準と離れた調査結果になっていることや、倒産のリスクがない公務員に、民間企業と同水準の給与を求めることがふさわしいのかといった点で、品川区議会日本維新の会は反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2250#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":10686,"voices":44}},{"id":"r04-20221125-10","meetingId":"r04-cm11","date":"2022年11月25日","dateIso":"2022-11-25","committee":"議会運営委員会","time":"午後 ３時５５分～午後 ３時５８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5488#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":1129,"voices":8}},{"id":"r04-20221219-10","meetingId":"r04-cm12","date":"2022年12月19日","dateIso":"2022-12-19","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時３１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議会運営上の変更","agenda":"議会運営上の変更","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"配置を決めるに当たってのルールや基準というのがあるのかどうか伺いたいのと、本人の希望というのはどのように反映されるのか、何か聞いたりするのかどうかも含めて伺いたいと思います。","respondent":"渡辺委員長","answer":"委員長案ですので、私のほうからご説明いたします。年度当初もそうなのですが、議会運営委員会で協議する際に、委員長案をたたき台にして行うという慣例がありますので、そこの経緯も見直しました。","voiceIndex":19,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"具体的なルールや基準というのはないということであれば、説明していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-002"}]},{"id":"topic-02","title":"議員提出議案","agenda":"議員提出議案","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ちょっと全般的なことについても伺っていきたいと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":32,"id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回個人情報保護に関する条例を作成していくに当たって、審議会などで諮ったりということもあったのかというのを確認させていただきたいのですけれども、ほかの議会ですと、審議会に諮って、パブリックコメントとかをもらって実施していくという流れがあるのですけれども、品川区ではどうなっているのかというところを確認させていただきたいと思います。","respondent":"工藤区議会事務局長","answer":"区の条例の、今回の改正等に伴う件につきましては、区のほうで審議会を持ってありますので、その中で諮りながら、条例案を設定したと聞いているところです。","voiceIndex":34,"id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回諮ったということで、その中でどういった意見があったのかというところをご説明いただきたいというふうに思います。それと今回条文を見させていただいて、匿名加工情報とか、仮名加工情報というような規定が、定義がされておりますけれども、その違いが何かというところと、こうした加工情報を実際につくっていくのかどうかというところを伺います。","respondent":"工藤区議会事務局長","answer":"２点目の匿名加工情報や仮名加工情報につきましては、私どものほうでも、議会の中ではそういった取扱いというのは想定してございませんが、法律の条文の中で定義を定めるというところがございまして、それにのっとって、そのような用語を条例の中に入れているものです。","voiceIndex":36,"id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"今回匿名加工情報とか、仮名加工情報は想定していないということでした。そうすると、個人情報ファイル簿というのも、今のところ情報がないということですから、つくらないということなのか、そこをお聞きしたいと思います。仮につくるということになったときに、何か今回の条例の改正とかが必要なのか、どのような形でやっていくのかというところを伺いたいと思います。","respondent":"工藤区議会事務局長","answer":"今後何かそういった部分について変更があった場合に条例を改正するのかという部分につきましては、法律に基づいて、法律の考えにのっとって、区議会のほうで条例をつくっておりますので、元の法律の部分で変更が生じる場合には。","voiceIndex":38,"id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"それで、今回匿名加工情報とか、仮名加工情報の定義は、法律に沿ってつくっていくということなのですが、今回、議会としては個人情報保護法の中では除かれているというところで、これも法律にのっとってつくっていく必要もないわけですから、個人情報保護をしっかりやるということが重要だと思うのですけれども、データを利活用していくための匿名加工情報ですとか。","respondent":"工藤区議会事務局長","answer":"そういった意味では、議会の中ではファイル簿という部分はないというふうに考えてあります。今回法律の中で、議会が実施機関として除かれたわけです。","voiceIndex":41,"id":"exchange-007"},{"speaker":"のだて委員","kind":"意見","question":"最後に議会の条例をつくっていくということになるので、全ての議員に関わることだと思いますので、どういった形がいいか分かりません。全員協議会などを開いて、また少数会派の方の意見も反映していくべきではないかというふうに、特に今回一応最終本会議までは、来年の１月１２日ということになりますので、そういった機会をぜひ設けるべきではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-008"},{"speaker":"安藤副委員長","kind":"提案","question":"議員提案で議員全員が関わる重要な問題なのですけれども、この間、私も正副でいろいろな案を出させていただきましたし、前回なども出させていただいたわけですけれども、議員同士の理解が深まっているわけでもございませんし、私たちの会派としても、議会運営委員会を受けて、いろいろ研究していくと、これはもっと深める必要がある内容だ、必要な条例だなというふうに思っていまして、今。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":45,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"提案","question":"うちの会派としてもそれを理解した上で今日臨んでいるのですけれども、安藤副委員長のほうから、そちらの会派のほうで、匿名・仮名情報についてのご指摘はあったのですけれども、何かそれ以外で今回全国市議会議長会のほうからのひな形の、そのときの横引きだという話で今まで来たのですが、それを今日になって急に問題点がたくさんあるのだとおっしゃられているのですけれども、そのほかに何かご指摘が。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-010"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"だから、議会が独自につくるということになりますと、議会の独自性が求められると思うのです。ですから、そういった点でやはり法律の根本的な目的に私たちはもちろん反対していますし、それを可能にするような規定を入れるということ、そもそもそれでいいのかという問題をちょっと考えようと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問","question":"私の質問の仕方が悪かったのかもしれませんが、先ほど匿名加工情報以外のところで、全員協議会を開くような必要性が何かあるのですかということで聞いたつもりだったのですけれども、先ほどのことはのだて委員からも質問がありました。今回は法律自体に反対だから、これを全員協議会でやってくれというふうに聞こえたのですけれども、法律には除外規定などいっぱいあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"提案","question":"事務局で、前回の議会運営委員会の中でも検討している状況、全国市議会議長会からの提案、基本的なもの、行政としても絡んでいます。そういうことを含めて、この件に関しては、全員協議会を開く必要はないと思いますので、今日の議会運営委員会で結論を出していただきたいと思います。もちろん賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-013"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど申し上げたとおりでございまして、先ほどの最初のご意見だと、多数の課題があるようなお話でしたが、ほかにあるのですかと伺ったら、先ほどと同じ主張の繰り返しであって、それがあまり普遍的でないようにも思いましたので、私はこの場でもって検討すべきものかなと、結論を出すものかなと、会派としてというか、私はそう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-014"}]},{"id":"topic-03","title":"議員研修会","agenda":"議員研修会","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"先ほどの資料No.１６の予定に関することで、議長なのか議会運営委員会なのかというところで、卒業式、入学式は、ここ数年、議会のほうから自粛というか、出席のご辞退を申し上げていると思うのですけれども、日程の確保も含めて、どれぐらいの時期にそれを、これから見極められるのかもしれないのですけれども、見極めの時期というといつぐらいに出る、出ないという話が決まるのかというところだけ。","respondent":"工藤区議会事務局長","answer":"これらの日程につきましては、早い段階で教育委員会のほうと調整してまいりたいというふうに思っております。日程等につきましては、また改めて周知したいというふうに思っております。","voiceIndex":84,"id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5490#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":19637,"voices":86}}]);
